import React, { useState, useEffect } from 'react';
import { 
  Monitor, Printer, ScanLine, Camera, Plus, Search,
  CheckCircle, XCircle, AlertCircle, Trash2, Settings,
  RefreshCw, ChevronDown
} from 'lucide-react';
import './ProfileSettings.css';
import './AddDeviceModal.css';

const DevicesSection = ({ devices = [], onAddDevice, onDeleteDevice, onRefresh }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  const categories = [
    { id: 'all', label: 'All Categories' },
    { id: 'printer', label: 'Printers' },
    { id: 'scanner', label: 'Scanners' },
    { id: 'camera', label: 'Cameras' },
    { id: 'other', label: 'Other Devices' },
  ];

  // Device type to category mapping
  const getDeviceCategory = (type) => {
    const printerTypes = ['thermal-printer', 'inkjet-printer', 'laser-printer', 'dot-matrix-printer', 'label-printer'];
    const scannerTypes = ['barcode-scanner', 'document-scanner', 'qr-code-scanner'];
    const cameraTypes = ['security-camera', 'webcam', 'document-camera'];
    
    if (printerTypes.includes(type)) return 'printer';
    if (scannerTypes.includes(type)) return 'scanner';
    if (cameraTypes.includes(type)) return 'camera';
    return 'other';
  };

  // Format device type for display
  const formatDeviceType = (type) => {
    if (!type) return 'Unknown';
    return type
      .split('-')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  };

  // Calculate stats
  const stats = {
    total: devices.length,
    online: devices.filter(d => d.status === 'online').length,
    offline: devices.filter(d => d.status === 'offline').length,
    printers: devices.filter(d => getDeviceCategory(d.type) === 'printer').length,
    scanners: devices.filter(d => getDeviceCategory(d.type) === 'scanner').length,
    cameras: devices.filter(d => getDeviceCategory(d.type) === 'camera').length,
  };

  const statCards = [
    { id: 'total', label: 'Total Devices', value: stats.total, icon: Monitor, color: '#6b7280' },
    { id: 'online', label: 'Online', value: stats.online, icon: CheckCircle, color: '#10b981' },
    { id: 'offline', label: 'Offline', value: stats.offline, icon: XCircle, color: '#ef4444' },
    { id: 'printers', label: 'Printers', value: stats.printers, icon: Printer, color: '#3b82f6' },
    { id: 'scanners', label: 'Scanners', value: stats.scanners, icon: ScanLine, color: '#8b5cf6' },
    { id: 'cameras', label: 'Cameras', value: stats.cameras, icon: Camera, color: '#f59e0b' },
  ];

  // Filter devices
  const filteredDevices = devices.filter(device => {
    const matchesSearch = device.name?.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesCategory = categoryFilter === 'all' || getDeviceCategory(device.type) === categoryFilter;
    return matchesSearch && matchesCategory;
  });

  const handleRefresh = async () => {
    setLoading(true);
    setError(null);
    try {
      if (onRefresh) await onRefresh();
    } catch (err) {
      setError('An unexpected error occurred');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="section-container devices-section">
      {/* Section Header */}
      <div className="devices-header">
        <div className="devices-header-content">
          <div>
            <h2>Device Management</h2>
            <p>Manage printers, scanners, cameras, and other hardware devices</p>
          </div>
          <button className="add-device-btn" onClick={() => setIsAddModalOpen(true)}>
            <Plus size={18} />
            Add Device
          </button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="device-stats-grid">
        {statCards.map((stat) => (
          <div key={stat.id} className="device-stat-card">
            <div className="stat-card-content">
              <span className="stat-card-label">{stat.label}</span>
              <span className="stat-card-value">{stat.value}</span>
            </div>
            <div className="stat-card-icon" style={{ color: stat.color }}>
              <stat.icon size={20} />
            </div>
          </div>
        ))}
      </div>

      {/* Search and Filter */}
      <div className="devices-toolbar">
        <div className="search-box">
          <Search size={18} />
          <input
            type="text"
            placeholder="Search devices..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
        <div className="filter-dropdown">
          <select 
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
          >
            {categories.map((cat) => (
              <option key={cat.id} value={cat.id}>{cat.label}</option>
            ))}
          </select>
          <ChevronDown size={16} className="dropdown-arrow" />
        </div>
        <button className="refresh-btn" onClick={handleRefresh} disabled={loading}>
          <RefreshCw size={16} className={loading ? 'spinning' : ''} />
        </button>
      </div>

      {/* Error Banner */}
      {error && (
        <div className="error-banner">
          <AlertCircle size={18} />
          <span>{error}</span>
        </div>
      )}

      {/* Device List or Empty State */}
      <div className="devices-content">
        {filteredDevices.length > 0 ? (
          <div className="devices-list">
            {filteredDevices.map((device) => (
              <div key={device.id} className="device-item">
                <div className="device-icon">
                  {getDeviceCategory(device.type) === 'printer' && <Printer size={24} />}
                  {getDeviceCategory(device.type) === 'scanner' && <ScanLine size={24} />}
                  {getDeviceCategory(device.type) === 'camera' && <Camera size={24} />}
                  {getDeviceCategory(device.type) === 'other' && <Monitor size={24} />}
                </div>
                <div className="device-info">
                  <span className="device-name">{device.name}</span>
                  <span className="device-type">{formatDeviceType(device.type)}</span>
                </div>
                <span className={`device-status ${device.status}`}>
                  {device.status === 'online' ? <CheckCircle size={14} /> : <XCircle size={14} />}
                  {device.status}
                </span>
                <div className="device-actions">
                  <button className="device-action-btn">
                    <Settings size={16} />
                  </button>
                  <button 
                    className="device-action-btn delete"
                    onClick={() => onDeleteDevice?.(device.id)}
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="empty-state">
            <div className="empty-icon">
              <Monitor size={48} />
            </div>
            <h3>No devices found</h3>
            <p>Get started by adding your first device</p>
            <button className="add-device-btn" onClick={() => setIsAddModalOpen(true)}>
              <Plus size={18} />
              Add Device
            </button>
          </div>
        )}
      </div>

      {/* Add Device Modal */}
      {isAddModalOpen && (
        <AddDeviceModal 
          onClose={() => setIsAddModalOpen(false)}
          onAdd={(device) => {
            onAddDevice?.(device);
            setIsAddModalOpen(false);
          }}
        />
      )}
    </div>
  );
};

const AddDeviceModal = ({ onClose, onAdd }) => {
  const [formData, setFormData] = useState({
    name: '',
    type: 'thermal-printer',
    ipAddress: '',
    port: ''
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    onAdd({
      ...formData,
      id: Date.now(),
      status: 'offline'
    });
  };

  return (
    <div className="modal-overlay">
      <div className="add-device-modal">
        <div className="modal-header">
          <h3>Add New Device</h3>
          <button className="close-btn" onClick={onClose}>×</button>
        </div>
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Device Name</label>
            <input
              type="text"
              value={formData.name}
              onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
              placeholder="Enter device name"
              required
            />
          </div>
          <div className="form-group">
            <label>Device Type</label>
            <select
              value={formData.type}
              onChange={(e) => setFormData(prev => ({ ...prev, type: e.target.value }))}
            >
              <optgroup label="Printers">
                <option value="thermal-printer">Thermal Printer</option>
                <option value="inkjet-printer">Inkjet Printer</option>
                <option value="laser-printer">Laser Printer</option>
                <option value="dot-matrix-printer">Dot Matrix Printer</option>
                <option value="label-printer">Label Printer</option>
              </optgroup>
              <optgroup label="Scanners">
                <option value="barcode-scanner">Barcode Scanner</option>
                <option value="document-scanner">Document Scanner</option>
                <option value="qr-code-scanner">QR Code Scanner</option>
              </optgroup>
              <optgroup label="Cameras">
                <option value="security-camera">Security Camera</option>
                <option value="webcam">Webcam</option>
                <option value="document-camera">Document Camera</option>
              </optgroup>
              <optgroup label="Other Devices">
                <option value="cash-drawer">Cash Drawer</option>
                <option value="customer-display">Customer Display</option>
                <option value="card-reader">Card Reader</option>
                <option value="biometric-device">Biometric Device</option>
                <option value="pos-terminal">POS Terminal</option>
                <option value="other-device">Other Device</option>
              </optgroup>
            </select>
          </div>
          <div className="form-row">
            <div className="form-group">
              <label>IP Address</label>
              <input
                type="text"
                value={formData.ipAddress}
                onChange={(e) => setFormData(prev => ({ ...prev, ipAddress: e.target.value }))}
                placeholder="192.168.1.100"
              />
            </div>
            <div className="form-group">
              <label>Port</label>
              <input
                type="text"
                value={formData.port}
                onChange={(e) => setFormData(prev => ({ ...prev, port: e.target.value }))}
                placeholder="9100"
              />
            </div>
          </div>
          <div className="form-actions">
            <button type="button" className="cancel-btn" onClick={onClose}>Cancel</button>
            <button type="submit" className="save-btn">
              <Plus size={16} />
              Add Device
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default DevicesSection;
