import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import './RevenueChart.css';

const fmt = (v) => `₹${Number(v || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

const RevenueChart = ({ data = [] }) => {
  if (!data.length || data.every(d => d.revenue === 0)) {
    // Still render the chart but show a helpful empty-state overlay when all zeros
  }
  return (
    <div className="revenue-chart">
      <h3 className="chart-title">Revenue Trend</h3>
      <ResponsiveContainer width="100%" height={300}>
        <LineChart data={data}>
          <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
          <XAxis dataKey="month" stroke="#6b7280" />
          <YAxis stroke="#6b7280" tickFormatter={(v) => `₹${(v >= 1000 ? (v/1000).toFixed(1)+'k' : v)}`} />
          <Tooltip formatter={(value) => [fmt(value), 'Revenue']} />
          <Legend />
          <Line
            type="monotone"
            dataKey="revenue"
            stroke="#8b5cf6"
            name="Revenue (₹)"
            strokeWidth={2.5}
            dot={{ r: 4, fill: '#8b5cf6' }}
            activeDot={{ r: 6 }}
          />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
};

export default RevenueChart;
