import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Header from './components/layout/Header';
import Dashboard from './pages/Dashboard';
import Inventory from './pages/Inventory';
import Shop from './pages/Shop';
import Profile from './pages/Profile';
import HomePage from './pages/HomePage';
import Login from './pages/Login';
import AdminLogin from './pages/AdminLogin';
import PrivacyPolicy from './pages/PrivacyPolicy';
import Register from './pages/Register';
import ForgotPassword from './pages/ForgotPassword';
import BackendStatusGate from './components/common/BackendStatusGate';
import './App.css';

/** Simple wrapper to protect internal routes */
const ProtectedRoute = ({ children }) => {
  const token = localStorage.getItem('token');
  const adminToken = localStorage.getItem('adminToken');
  if (!token && !adminToken) {
    return <Navigate to="/login" replace />;
  }

  return children;
};

/** Simple wrapper to prevent logged-in users from accessing public auth pages */
const PublicRoute = ({ children }) => {
  const token = localStorage.getItem('token');
  if (token) {
    return <Navigate to="/dashboard" replace />;
  }
  return children;
};

/** Layout that includes the top Header for the internal app pages */
function AppLayout({ children }) {
  return (
    <div className="app">
      <Header />
      <main className="main-content">
        {children}
      </main>
    </div>
  );
}

function App() {
  return (
    <Router>
      <BackendStatusGate />
      <Routes>
        {/* Public landing page — no internal Header */}
        <Route path="/" element={<HomePage />} />

        {/* Internal app routes — wrapped with AppLayout (Header) */}
        {/* Standalone auth pages — no internal Header */}
        <Route path="/login" element={<Login />} />
        <Route path="/admin/login" element={<AdminLogin />} />
        <Route path="/privacy-policy" element={<PrivacyPolicy />} />
        <Route path="/terms-of-service" element={<PrivacyPolicy />} />
        <Route path="/refund-policy" element={<PrivacyPolicy />} />
        <Route path="/cookie-policy" element={<PrivacyPolicy />} />
        <Route path="/security-policy" element={<PrivacyPolicy />} />
        <Route path="/register" element={<Register />} />
        <Route path="/forgot-password" element={<PublicRoute><ForgotPassword /></PublicRoute>} />
        <Route
          path="/dashboard"
          element={
            <ProtectedRoute>
              <AppLayout>
                <Dashboard />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/superadmindashboard"
          element={
            <ProtectedRoute>
              <AppLayout>
                <Dashboard />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/inventory"
          element={
            <ProtectedRoute>
              <AppLayout>
                <Inventory />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/shop"
          element={
            <ProtectedRoute>
              <AppLayout>
                <Shop />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        <Route
          path="/profile"
          element={
            <ProtectedRoute>
              <AppLayout>
                <Profile />
              </AppLayout>
            </ProtectedRoute>
          }
        />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </Router>
  );
}

export default App;
