import { useEffect, useState } from 'react';
import axios from 'axios';
import { Loader2, RefreshCw, UserPlus, Users } from 'lucide-react';
import './LocalUsersDemo.css';

const EMPTY_FORM = {
  name: '',
  email: ''
};

function LocalUsersDemo() {
  const [users, setUsers] = useState([]);
  const [form, setForm] = useState(EMPTY_FORM);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const loadUsers = async () => {
    try {
      setLoading(true);
      setError('');
      const response = await axios.get('/api/users');
      setUsers(response.data ?? []);
    } catch (err) {
      setError(err.response?.data?.error || 'Unable to load local users.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadUsers();
  }, []);

  const handleSubmit = async (event) => {
    event.preventDefault();
    if (!form.name.trim() || !form.email.trim()) {
      setError('Name and email are required.');
      return;
    }

    try {
      setSaving(true);
      setError('');
      await axios.post('/api/users', {
        name: form.name.trim(),
        email: form.email.trim()
      });
      setForm(EMPTY_FORM);
      await loadUsers();
    } catch (err) {
      setError(err.response?.data?.error || 'Unable to save the local user.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <section className="lud-shell py-5">
      <div className="container py-3">
        <div className="lud-card">
          <div className="lud-header">
            <div>
              <span className="lud-kicker">Local API Demo</span>
              <h2>React talking to Spring Boot on the same origin</h2>
              <p>
                This section reads and writes sample users through relative requests to
                <code> /api/users</code>. No separate frontend server and no external API is involved.
              </p>
            </div>
            <button type="button" className="lud-refresh" onClick={loadUsers} disabled={loading || saving}>
              {loading ? <Loader2 size={16} className="lud-spin" /> : <RefreshCw size={16} />}
              Refresh
            </button>
          </div>

          <div className="row g-4 align-items-start">
            <div className="col-lg-5">
              <form className="lud-form" onSubmit={handleSubmit}>
                <div className="lud-form-head">
                  <UserPlus size={18} />
                  <span>Add a sample user</span>
                </div>

                <label htmlFor="demo-user-name">Name</label>
                <input
                  id="demo-user-name"
                  value={form.name}
                  onChange={(event) => setForm((previous) => ({ ...previous, name: event.target.value }))}
                  placeholder="e.g. Kavya Rao"
                />

                <label htmlFor="demo-user-email">Email</label>
                <input
                  id="demo-user-email"
                  type="email"
                  value={form.email}
                  onChange={(event) => setForm((previous) => ({ ...previous, email: event.target.value }))}
                  placeholder="kavya@smms.local"
                />

                <button type="submit" className="lud-submit" disabled={saving}>
                  {saving ? <Loader2 size={16} className="lud-spin" /> : <UserPlus size={16} />}
                  Save locally
                </button>

                {error && <p className="lud-error">{error}</p>}
              </form>
            </div>

            <div className="col-lg-7">
              <div className="lud-list-card">
                <div className="lud-list-head">
                  <div className="lud-list-title">
                    <Users size={18} />
                    <span>Stored users in H2</span>
                  </div>
                  <span className="lud-count">{users.length}</span>
                </div>

                {loading ? (
                  <div className="lud-empty">
                    <Loader2 size={18} className="lud-spin" />
                    <span>Loading local users...</span>
                  </div>
                ) : users.length === 0 ? (
                  <div className="lud-empty">
                    <Users size={18} />
                    <span>No sample users yet. Add one from the form.</span>
                  </div>
                ) : (
                  <div className="lud-list">
                    {users.map((user) => (
                      <article key={user.id} className="lud-user">
                        <div>
                          <h3>{user.name}</h3>
                          <p>{user.email}</p>
                        </div>
                        <span>#{user.id}</span>
                      </article>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

export default LocalUsersDemo;
