import React, { useState, useEffect } from 'react';
import { 
  Clock, Sun, Moon, Calendar, Edit, Save, Info, CheckCircle
} from 'lucide-react';
import './ProfileSettings.css';

const BusinessHoursSection = ({ businessHours, onSave }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState(businessHours);
  const [saving, setSaving] = useState(false);

  // Sync form data when businessHours changes
  useEffect(() => {
    setFormData(businessHours);
  }, [businessHours]);

  const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  
  // Parse working days to get active days
  const getActiveDays = () => {
    const workingDays = businessHours.workingDays?.toLowerCase() || '';
    if (workingDays.includes('monday to sunday') || workingDays.includes('all days')) {
      return days;
    }
    // Add more parsing logic if needed
    return days;
  };

  const activeDays = getActiveDays();

  // Check if currently open based on business hours
  const isCurrentlyOpen = () => {
    const now = new Date();
    const currentTime = now.getHours() * 60 + now.getMinutes();
    
    const parseTime = (timeStr) => {
      if (!timeStr) return 0;
      const match = timeStr.match(/(\d+):?(\d+)?\s*(AM|PM)?/i);
      if (!match) return 0;
      let hours = parseInt(match[1]);
      const minutes = parseInt(match[2] || 0);
      const period = match[3]?.toUpperCase();
      
      if (period === 'PM' && hours !== 12) hours += 12;
      if (period === 'AM' && hours === 12) hours = 0;
      
      return hours * 60 + minutes;
    };

    const openTime = parseTime(businessHours.opening);
    const closeTime = parseTime(businessHours.closing);
    
    return currentTime >= openTime && currentTime <= closeTime;
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await onSave(formData);
      setIsEditing(false);
    } catch (error) {
      console.error('Failed to save business hours:', error);
    } finally {
      setSaving(false);
    }
  };

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  return (
    <div className="section-container">
      {/* Section Header */}
      <div className="section-header teal">
        <div className="section-header-content">
          <div className="section-title-group">
            <Clock size={24} />
            <div>
              <h2>Business Hours</h2>
              <p>Set your store's operating hours and working days</p>
            </div>
          </div>
          <button 
            className="edit-details-btn"
            onClick={() => setIsEditing(!isEditing)}
          >
            <Edit size={16} />
            {isEditing ? 'Cancel' : 'Edit Hours'}
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="section-content">
        {isEditing ? (
          <div className="edit-form">
            <div className="form-row">
              <div className="form-group">
                <label>Opening Time</label>
                <input
                  type="text"
                  value={formData.opening}
                  onChange={(e) => handleChange('opening', e.target.value)}
                  placeholder="e.g., 7:00 AM"
                />
              </div>
              <div className="form-group">
                <label>Closing Time</label>
                <input
                  type="text"
                  value={formData.closing}
                  onChange={(e) => handleChange('closing', e.target.value)}
                  placeholder="e.g., 10:00 PM"
                />
              </div>
            </div>
            <div className="form-group">
              <label>Working Days</label>
              <input
                type="text"
                value={formData.workingDays}
                onChange={(e) => handleChange('workingDays', e.target.value)}
                placeholder="e.g., Monday to Sunday"
              />
            </div>
            <div className="form-actions">
              <button className="cancel-btn" onClick={() => setIsEditing(false)} disabled={saving}>
                Cancel
              </button>
              <button className="save-btn" onClick={handleSave} disabled={saving}>
                <Save size={16} />
                {saving ? 'Saving...' : 'Save Changes'}
              </button>
            </div>
          </div>
        ) : (
          <div className="business-hours-display">
            {/* Status Banner */}
            <div className={`status-banner ${isCurrentlyOpen() ? 'open' : 'closed'}`}>
              <div className="status-info">
                <CheckCircle size={20} />
                <div>
                  <span className="status-label">
                    {isCurrentlyOpen() ? 'Currently Open' : 'Currently Closed'}
                  </span>
                  <span className="status-hours">
                    {businessHours.opening} - {businessHours.closing}
                  </span>
                </div>
              </div>
              <span className={`status-badge ${isCurrentlyOpen() ? 'open' : 'closed'}`}>
                {isCurrentlyOpen() ? 'OPEN' : 'CLOSED'}
              </span>
            </div>

            {/* Time Cards */}
            <div className="time-cards-grid">
              <div className="time-card">
                <div className="time-card-icon yellow">
                  <Sun size={24} />
                </div>
                <span className="time-label">Opening Time</span>
                <span className="time-value">{businessHours.opening || '7:00 AM'}</span>
              </div>
              <div className="time-card">
                <div className="time-card-icon blue">
                  <Moon size={24} />
                </div>
                <span className="time-label">Closing Time</span>
                <span className="time-value">{businessHours.closing || '10:00 PM'}</span>
              </div>
            </div>

            {/* Working Days */}
            <div className="working-days-section">
              <div className="working-days-header">
                <Calendar size={18} />
                <span>Working Days</span>
              </div>
              <p className="working-days-text">{businessHours.workingDays || 'Monday to Sunday'}</p>
              <div className="days-pills">
                {days.map((day) => (
                  <span 
                    key={day} 
                    className={`day-pill ${activeDays.includes(day) ? 'active' : ''}`}
                  >
                    {day}
                  </span>
                ))}
              </div>
            </div>

            {/* Info Banner */}
            <div className="info-banner">
              <Info size={18} />
              <div>
                <strong>Business Hours Tips</strong>
                <p>Accurate business hours help customers know when to visit your store. These hours may be displayed on your store profile and used for order scheduling.</p>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default BusinessHoursSection;
