import React, { useState, useEffect } from 'react';
import { 
  Phone, MapPin, Mail, Globe, Edit, X, Save, Info
} from 'lucide-react';
import './ProfileSettings.css';

const ContactSection = ({ contactInfo, onSave }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    address: contactInfo?.address || '',
    phone: contactInfo?.phone || '',
    email: contactInfo?.email || '',
    website: contactInfo?.website || '',
    instagram: contactInfo?.instagram || '',
    twitter: contactInfo?.twitter || ''
  });
  const [saving, setSaving] = useState(false);

  // Sync form data when contactInfo changes
  useEffect(() => {
    if (contactInfo) {
      setFormData({
        address: contactInfo.address || '',
        phone: contactInfo.phone || '',
        email: contactInfo.email || '',
        website: contactInfo.website || '',
        instagram: contactInfo.instagram || '',
        twitter: contactInfo.twitter || ''
      });
    }
  }, [contactInfo]);

  const handleSave = async () => {
    setSaving(true);
    try {
      await onSave(formData);
      setIsEditing(false);
    } catch (error) {
      console.error('Failed to save contact info:', error);
    } finally {
      setSaving(false);
    }
  };

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  return (
    <div className="section-container">
      {/* Section Header */}
      <div className="section-header green">
        <div className="section-header-content">
          <div className="section-title-group">
            <Phone size={24} />
            <div>
              <h2>Contact Information</h2>
              <p>Manage your store's contact details and location</p>
            </div>
          </div>
          <button 
            className="edit-details-btn"
            onClick={() => setIsEditing(!isEditing)}
          >
            <Edit size={16} />
            {isEditing ? 'Cancel' : 'Edit Details'}
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="section-content">
        {isEditing ? (
          <div className="edit-form">
            <div className="form-group">
              <label>Store Address</label>
              <textarea
                value={formData.address || ''}
                onChange={(e) => handleChange('address', e.target.value)}
                placeholder="Enter store address"
                rows={3}
              />
            </div>
            <div className="form-row">
              <div className="form-group">
                <label>Phone Number</label>
                <input
                  type="text"
                  value={formData.phone || ''}
                  onChange={(e) => handleChange('phone', e.target.value)}
                  placeholder="Enter phone number"
                />
              </div>
              <div className="form-group">
                <label>Email Address</label>
                <input
                  type="email"
                  value={formData.email || ''}
                  onChange={(e) => handleChange('email', e.target.value)}
                  placeholder="Enter email address"
                />
              </div>
            </div>
            <div className="form-group">
              <label>Website</label>
              <input
                type="text"
                value={formData.website || ''}
                onChange={(e) => handleChange('website', e.target.value)}
                placeholder="Enter website URL"
              />
            </div>
            <div className="form-actions">
              <button className="cancel-btn" onClick={() => setIsEditing(false)} disabled={saving}>
                Cancel
              </button>
              <button className="save-btn" onClick={handleSave} disabled={saving}>
                <Save size={16} />
                {saving ? 'Saving...' : 'Save Changes'}
              </button>
            </div>
          </div>
        ) : (
          <div className="contact-display">
            <div className="contact-card large">
              <div className="contact-icon">
                <MapPin size={20} />
              </div>
              <div className="contact-details">
                <span className="contact-label">Store Address</span>
                <span className="contact-value">{contactInfo.address || 'Not provided'}</span>
              </div>
            </div>

            <div className="contact-grid">
              <div className="contact-card">
                <div className="contact-icon blue">
                  <Phone size={20} />
                </div>
                <div className="contact-details">
                  <span className="contact-label">Phone Number</span>
                  <span className="contact-value">{contactInfo.phone || 'Not provided'}</span>
                </div>
              </div>

              <div className="contact-card">
                <div className="contact-icon purple">
                  <Mail size={20} />
                </div>
                <div className="contact-details">
                  <span className="contact-label">Email Address</span>
                  <span className="contact-value">{contactInfo.email || 'Not provided'}</span>
                </div>
              </div>

              <div className="contact-card">
                <div className="contact-icon green">
                  <Globe size={20} />
                </div>
                <div className="contact-details">
                  <span className="contact-label">Website</span>
                  <span className="contact-value">{contactInfo.website || 'Not provided'}</span>
                </div>
              </div>
            </div>

            <div className="info-banner">
              <Info size={18} />
              <div>
                <strong>Keep Your Contact Info Updated</strong>
                <p>Accurate contact information helps customers find your store and reach you easily. This information may also be used for order notifications and support communications.</p>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ContactSection;
