import React, { useState, useEffect, useRef } from "react";
import { Mail, Lock, Store, Eye, EyeOff, Loader2, ArrowLeft, CheckCircle } from "lucide-react";
import { useNavigate, Link } from "react-router-dom";
import api from "../services/api";
import "bootstrap/dist/css/bootstrap.min.css";
import "./Login.css"; // Reuse Login styles for consistency

export default function ForgotPassword() {
  const navigate = useNavigate();
  
  // Steps: 'email' -> 'otp' -> 'reset' -> 'success'
  const [step, setStep] = useState('email');
  const [email, setEmail] = useState('');
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [maskedEmail, setMaskedEmail] = useState('');
  const [resendTimer, setResendTimer] = useState(0);
  
  const otpRefs = useRef([]);

  // Resend timer countdown
  useEffect(() => {
    if (resendTimer > 0) {
      const timer = setTimeout(() => setResendTimer(resendTimer - 1), 1000);
      return () => clearTimeout(timer);
    }
  }, [resendTimer]);

  // Handle OTP input
  const handleOtpChange = (index, value) => {
    if (value.length > 1) {
      const pastedOtp = value.slice(0, 6).split('');
      const newOtp = [...otp];
      pastedOtp.forEach((char, i) => {
        if (index + i < 6) {
          newOtp[index + i] = char;
        }
      });
      setOtp(newOtp);
      const nextIndex = Math.min(index + pastedOtp.length, 5);
      otpRefs.current[nextIndex]?.focus();
    } else {
      const newOtp = [...otp];
      newOtp[index] = value;
      setOtp(newOtp);
      if (value && index < 5) {
        otpRefs.current[index + 1]?.focus();
      }
    }
  };

  const handleOtpKeyDown = (index, e) => {
    if (e.key === 'Backspace' && !otp[index] && index > 0) {
      otpRefs.current[index - 1]?.focus();
    }
  };

  // Step 1: Send OTP
  const handleSendOtp = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    
    if (!email.trim()) {
      setError('Please enter your email address');
      return;
    }

    setLoading(true);
    try {
      const response = await api.post('/forgot-password', { email: email.trim() });
      setMaskedEmail(response.data.email || email);
      setSuccess('OTP sent successfully! Check your email.');
      setStep('otp');
      setResendTimer(60);
      setOtp(['', '', '', '', '', '']);
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to send OTP. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // Resend OTP
  const handleResendOtp = async () => {
    if (resendTimer > 0) return;
    
    setError('');
    setLoading(true);
    try {
      await api.post('/forgot-password', { email: email.trim() });
      setSuccess('OTP resent successfully!');
      setResendTimer(60);
      setOtp(['', '', '', '', '', '']);
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to resend OTP.');
    } finally {
      setLoading(false);
    }
  };

  // Step 2: Verify OTP and proceed to reset
  const handleVerifyOtp = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    
    const otpValue = otp.join('');
    if (otpValue.length !== 6) {
      setError('Please enter the complete 6-digit OTP');
      return;
    }

    setLoading(true);
    try {
      await api.post('/verify-otp', { email: email.trim(), otp: otpValue });
      setSuccess('OTP verified! Set your new password.');
      setStep('reset');
    } catch (err) {
      setError(err.response?.data?.error || 'Invalid or expired OTP.');
    } finally {
      setLoading(false);
    }
  };

  // Step 3: Reset Password
  const handleResetPassword = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (newPassword.length < 6) {
      setError('Password must be at least 6 characters');
      return;
    }

    if (newPassword !== confirmPassword) {
      setError('Passwords do not match');
      return;
    }

    setLoading(true);
    try {
      const otpValue = otp.join('');
      await api.post('/reset-password', { 
        email: email.trim(), 
        otp: otpValue, 
        newPassword 
      });
      setStep('success');
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to reset password.');
    } finally {
      setLoading(false);
    }
  };

  // Get step title
  const getStepTitle = () => {
    switch(step) {
      case 'email': return 'Forgot Password';
      case 'otp': return 'Verify OTP';
      case 'reset': return 'Reset Password';
      case 'success': return 'Success!';
      default: return 'Forgot Password';
    }
  };

  return (
    <div className="lp-root">
      <div className="lp-card p-4 p-md-5">

        {/* Brand header */}
        <div className="text-center mb-4">
          <div className="lp-brand d-flex align-items-center justify-content-center gap-2">
            <Store size={28} />
            TSAR IT SMMS
          </div>
          <p className="text-muted small mt-2">
            {getStepTitle()}
          </p>
        </div>

        {/* Progress indicator */}
        {step !== 'success' && (
          <div className="d-flex justify-content-center align-items-center gap-2 mb-4">
            <div className={`rounded-circle d-flex align-items-center justify-content-center ${step === 'email' ? 'bg-success text-white' : 'bg-success text-white'}`} style={{width: 28, height: 28, fontSize: 12, fontWeight: 600}}>1</div>
            <div style={{width: 30, height: 2, backgroundColor: step === 'email' ? '#e5e7eb' : '#16a34a'}}></div>
            <div className={`rounded-circle d-flex align-items-center justify-content-center ${step === 'otp' || step === 'reset' ? 'bg-success text-white' : 'bg-light text-muted'}`} style={{width: 28, height: 28, fontSize: 12, fontWeight: 600}}>2</div>
            <div style={{width: 30, height: 2, backgroundColor: step === 'reset' ? '#16a34a' : '#e5e7eb'}}></div>
            <div className={`rounded-circle d-flex align-items-center justify-content-center ${step === 'reset' ? 'bg-success text-white' : 'bg-light text-muted'}`} style={{width: 28, height: 28, fontSize: 12, fontWeight: 600}}>3</div>
          </div>
        )}

        {/* Error message */}
        {error && (
          <div className="lp-error-box mb-4">
            <div className="d-flex align-items-start gap-2">
              <span style={{ fontSize: "1.3rem" }}>⚠️</span>
              <div className="flex-grow-1">
                <p className="fw-bold mb-1" style={{ fontSize: "0.9rem", color: "#991b1b" }}>
                  Error
                </p>
                <p className="mb-0" style={{ fontSize: "0.85rem" }}>{error}</p>
              </div>
            </div>
          </div>
        )}

        {/* Success message */}
        {success && step !== 'success' && (
          <div className="alert alert-success mb-4 d-flex align-items-center gap-2" style={{fontSize: '0.9rem'}}>
            <CheckCircle size={18} />
            {success}
          </div>
        )}

        {/* Step 1: Email Input */}
        {step === 'email' && (
          <form onSubmit={handleSendOtp} noValidate>
            <p className="text-center text-muted small mb-4">
              Enter your registered email address. We'll send you an OTP to verify your identity.
            </p>
            
            <div className="mb-4">
              <label className="lp-label mb-2">
                <Mail size={14} className="me-1" />
                Email Address
              </label>
              <input
                type="email"
                className="lp-input"
                placeholder="Enter your email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                autoFocus
                required
              />
            </div>

            <button type="submit" className="lp-btn-primary mb-4" disabled={loading}>
              {loading ? (
                <>
                  <Loader2 size={17} className="lp-spin" /> Sending...
                </>
              ) : (
                'Send OTP'
              )}
            </button>

            <div className="text-center">
              <Link to="/login" className="lp-link small d-inline-flex align-items-center gap-1">
                <ArrowLeft size={14} />
                Back to Login
              </Link>
            </div>
          </form>
        )}

        {/* Step 2: OTP Verification */}
        {step === 'otp' && (
          <form onSubmit={handleVerifyOtp} noValidate>
            <p className="text-center text-muted small mb-4">
              Enter the 6-digit OTP sent to <strong style={{color: '#16a34a'}}>{maskedEmail}</strong>
            </p>

            <div className="d-flex justify-content-center gap-2 mb-4">
              {otp.map((digit, index) => (
                <input
                  key={index}
                  ref={(el) => (otpRefs.current[index] = el)}
                  type="text"
                  inputMode="numeric"
                  maxLength={6}
                  value={digit}
                  onChange={(e) => handleOtpChange(index, e.target.value.replace(/\D/g, ''))}
                  onKeyDown={(e) => handleOtpKeyDown(index, e)}
                  className="text-center fw-bold"
                  style={{
                    width: 45,
                    height: 50,
                    border: '2px solid #e5e7eb',
                    borderRadius: 10,
                    fontSize: 20,
                    color: '#16a34a',
                    outline: 'none',
                  }}
                  onFocus={(e) => e.target.style.borderColor = '#16a34a'}
                  onBlur={(e) => e.target.style.borderColor = '#e5e7eb'}
                  autoFocus={index === 0}
                />
              ))}
            </div>

            <button type="submit" className="lp-btn-primary mb-3" disabled={loading}>
              {loading ? (
                <>
                  <Loader2 size={17} className="lp-spin" /> Verifying...
                </>
              ) : (
                'Verify OTP'
              )}
            </button>

            <div className="text-center mb-3">
              <span className="text-muted small">Didn't receive the code? </span>
              <button
                type="button"
                className="btn btn-link p-0 small"
                style={{color: resendTimer > 0 ? '#9ca3af' : '#16a34a', textDecoration: 'none'}}
                onClick={handleResendOtp}
                disabled={resendTimer > 0 || loading}
              >
                {resendTimer > 0 ? `Resend in ${resendTimer}s` : 'Resend OTP'}
              </button>
            </div>

            <div className="text-center">
              <button type="button" className="btn btn-link small d-inline-flex align-items-center gap-1" style={{color: '#666', textDecoration: 'none'}} onClick={() => setStep('email')}>
                <ArrowLeft size={14} />
                Change Email
              </button>
            </div>
          </form>
        )}

        {/* Step 3: Reset Password */}
        {step === 'reset' && (
          <form onSubmit={handleResetPassword} noValidate>
            <p className="text-center text-muted small mb-4">
              Create a new password for your account.
            </p>

            <div className="mb-3">
              <label className="lp-label mb-2">
                <Lock size={14} className="me-1" />
                New Password
              </label>
              <div className="position-relative">
                <input
                  type={showPassword ? "text" : "password"}
                  className="lp-input"
                  placeholder="Enter new password"
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  minLength={6}
                  required
                  autoFocus
                />
                <button
                  type="button"
                  className="lp-eye-btn"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            <div className="mb-4">
              <label className="lp-label mb-2">
                <Lock size={14} className="me-1" />
                Confirm Password
              </label>
              <div className="position-relative">
                <input
                  type={showConfirmPassword ? "text" : "password"}
                  className="lp-input"
                  placeholder="Confirm new password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  required
                />
                <button
                  type="button"
                  className="lp-eye-btn"
                  onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                >
                  {showConfirmPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            <button type="submit" className="lp-btn-primary mb-4" disabled={loading}>
              {loading ? (
                <>
                  <Loader2 size={17} className="lp-spin" /> Resetting...
                </>
              ) : (
                'Reset Password'
              )}
            </button>
          </form>
        )}

        {/* Step 4: Success */}
        {step === 'success' && (
          <div className="text-center py-4">
            <div className="mb-4" style={{color: '#16a34a'}}>
              <CheckCircle size={64} />
            </div>
            <h5 className="fw-bold mb-3" style={{color: '#16a34a'}}>Password Reset Successful!</h5>
            <p className="text-muted small mb-4">
              Your password has been changed successfully. You can now login with your new password.
            </p>
            <button className="lp-btn-primary" onClick={() => navigate('/login')}>
              Go to Login
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
