import React, { useState } from "react";
import {
  Mail,
  Phone,
  Lock,
  Store,
  LogIn,
  Eye,
  EyeOff,
  Loader2,
  ArrowLeft,
  Wifi,
} from "lucide-react";
import { useNavigate, Link } from "react-router-dom";
import api from "../utils/api";
import storage from "../utils/storage";
import { isNativeApp } from "../services/api";
import MobileServerSettings from "../components/common/MobileServerSettings";
import "bootstrap/dist/css/bootstrap.min.css";
import "./Login.css";

export default function Login() {
  const [formData, setFormData] = useState({ emailOrPhone: "", password: "" });
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState("");

  const navigate = useNavigate();
  const [showServerSettings, setShowServerSettings] = useState(false);
  const nativeMobile = isNativeApp();

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const attemptLogin = async (id, pw) => {
    setIsSubmitting(true);
    setLoading(true);
    setError("");

    try {
      const response = await api.post("/login", {
        emailOrPhone: id,
        password: pw,
      });

      const { user, token } = response.data;
      if (!user || !token) throw new Error("Invalid response format from server");

      localStorage.removeItem("token");
      localStorage.removeItem("adminToken");
      localStorage.removeItem("user");
      localStorage.removeItem("admin");
      storage.set("user", user);
      localStorage.setItem("token", token);

      navigate("/dashboard");
    } catch (err) {
      setLoading(false);
      setIsSubmitting(false);

      let errorMessage = "";
      let errorDetails = "";

      if (err.response?.status === 401) {
        errorMessage = "Invalid email/phone or password.";
        errorDetails = "Please check your credentials and try again.";
      } else if (err.response?.status === 403) {
        const msg = err.response.data?.message || err.response.data?.error;
        errorMessage = "Access Denied";
        errorDetails = msg || "Your account is blocked. Please contact support.";
      } else if (err.response?.status === 404) {
        errorMessage = "Account not found.";
        errorDetails = "Please make sure you've registered first.";
      } else if (!err.response) {
        errorMessage = "Cannot connect to server.";
        errorDetails = "Please check if the backend is running on port 8080.";
      } else {
        const serverError = err.response?.data?.message || err.response?.data?.error;
        errorMessage = "Login failed.";
        errorDetails = serverError || `Server returned error code ${err.response?.status}. Please try again.`;
      }

      setError(`${errorMessage} ${errorDetails}`);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (isSubmitting || loading) return;
    if (!formData.emailOrPhone || !formData.password) {
      setError("Please fill all fields");
      return;
    }
    await attemptLogin(formData.emailOrPhone, formData.password);
  };

  const showRegisterHint =
    error.includes("not found") || error.includes("Invalid email");
  const showBackendHint = error.includes("backend") || error.includes("port 8080");

  return (
    <div className="lp-root">
      <div className="lp-card p-4 p-md-5">
        <div className="mb-3 d-flex align-items-center justify-content-between">
          <Link to="/" className="lp-link small d-inline-flex align-items-center gap-1">
            <ArrowLeft size={16} />
            Back to Home
          </Link>

          {nativeMobile && (
            <button
              type="button"
              className="lp-link small d-inline-flex align-items-center gap-1"
              style={{ background: 'none', border: 'none', cursor: 'pointer' }}
              onClick={() => setShowServerSettings((prev) => !prev)}
            >
              <Wifi size={16} />
              Server Settings
            </button>
          )}
        </div>

        {nativeMobile && showServerSettings && (
          <div className="mb-4">
            <MobileServerSettings embedded={true} />
          </div>
        )}

        <div className="text-center mb-4">
          <div className="lp-brand d-flex align-items-center justify-content-center gap-2">
            <Store size={28} />
            TSAR IT SMMS
          </div>
          <p className="text-muted small mt-2">
            Login to manage your supermarket dashboard
          </p>
        </div>

        <form onSubmit={handleSubmit} noValidate>
          {error && (
            <div className="lp-error-box mb-4">
              <div className="d-flex align-items-start gap-2">
                <span style={{ fontSize: "1.3rem" }}>!</span>
                <div className="flex-grow-1">
                  <p className="fw-bold mb-1" style={{ fontSize: "0.9rem", color: "#991b1b" }}>
                    Login Failed
                  </p>
                  <p className="mb-0 small" style={{ color: "#7f1d1d", lineHeight: 1.5 }}>
                    {error}
                  </p>
                </div>
                <button
                  type="button"
                  className="btn-close btn-close-sm"
                  onClick={() => setError("")}
                  aria-label="Dismiss error"
                  style={{ fontSize: "0.7rem" }}
                />
              </div>

              {showRegisterHint && (
                <div className="lp-error-hint">
                  <p className="fw-bold mb-2 small" style={{ color: "#1e40af" }}>
                    Quick Solutions:
                  </p>
                  <div className="d-flex flex-column gap-2">
                    <Link to="/register" className="lp-btn-green">
                      Register Your Account
                    </Link>
                    <button
                      type="button"
                      className="lp-btn-blue"
                      onClick={async () => {
                        const demoCreds = { emailOrPhone: "demo@tsaritservices.com", password: "demo123" };
                        setFormData(demoCreds);
                        setError("");
                        await attemptLogin(demoCreds.emailOrPhone, demoCreds.password);
                      }}
                    >
                      Try Demo Account
                    </button>
                  </div>
                  <p className="text-center text-muted mt-2" style={{ fontSize: "0.72rem" }}>
                    Demo: demo@tsaritservices.com / demo123
                  </p>
                </div>
              )}

              {showBackendHint && (
                <p className="mt-2 mb-0 small" style={{ color: "#dc2626" }}>
                  <strong>Tip:</strong>{" "}
                  {nativeMobile
                    ? 'Make sure your PC is on the same WiFi and SMMS is open there, then tap "Server Settings" above to set its IP address.'
                    : "Make sure the backend server is running on port 8080."}
                </p>
              )}
            </div>
          )}

          <div className="mb-3">
            <label className="lp-label">
              <Mail size={16} color="#16a34a" />
              Email or Phone
            </label>
            <div className="position-relative">
              <input
                name="emailOrPhone"
                type="text"
                value={formData.emailOrPhone}
                onChange={handleChange}
                placeholder="Enter email or phone number"
                className="lp-input"
                autoComplete="username"
                required
              />
              <span className="lp-input-icon">
                <Phone size={16} />
              </span>
            </div>
          </div>

          <div className="mb-2">
            <label className="lp-label">
              <Lock size={16} color="#16a34a" />
              Password
            </label>
            <div className="position-relative">
              <input
                name="password"
                type={showPassword ? "text" : "password"}
                value={formData.password}
                onChange={handleChange}
                placeholder="Enter password"
                className="lp-input"
                autoComplete="current-password"
                required
              />
              <button
                type="button"
                className="lp-input-btn"
                onClick={() => setShowPassword(!showPassword)}
                aria-label={showPassword ? "Hide password" : "Show password"}
              >
                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
              </button>
            </div>
          </div>

          <div className="text-end mb-4">
            <Link to="/forgot-password" className="lp-link small">
              Forgot password?
            </Link>
          </div>

          <button
            type="submit"
            className="lp-btn-primary mb-4"
            disabled={loading || isSubmitting}
          >
            {loading ? (
              <>
                <Loader2 size={17} className="lp-spin" /> Logging in...
              </>
            ) : (
              <>
                <LogIn size={17} /> Login
              </>
            )}
          </button>

          <div className="lp-divider mb-3">
            <span className="lp-divider-line" />
            <span className="lp-divider-text">or</span>
            <span className="lp-divider-line" />
          </div>

          <p className="text-center small text-muted mb-0">
            Don't have an account?{" "}
            <Link to="/register" className="lp-link fw-semibold">
              Register now
            </Link>
          </p>
        </form>
      </div>
    </div>
  );
}
