import { useEffect, useRef, useState } from 'react';
import { Loader2, RefreshCw, RotateCcw, ServerCrash } from 'lucide-react';
import { BACKEND_STATUS_EVENT, checkBackendHealth } from '../../services/api';
import './BackendStatusGate.css';

const INITIAL_STATE = {
  known: false,
  online: true,
  checking: true,
  reason: 'starting',
  actionMessage: '',
  restartingBackend: false,
  restartingApp: false,
  hasConnectedOnce: false
};

// A single slow/timed-out request anywhere in the app is not proof the backend
// is down — it just means one request was slow. Require this many consecutive
// failed signals before we trust it enough to block the whole UI.
const FAILURE_THRESHOLD = 2;
const REVERIFY_DELAY_MS = 1200;

const BackendStatusGate = () => {
  const [status, setStatus] = useState(INITIAL_STATE);
  const mountedRef = useRef(false);
  const onlineRef = useRef(true);
  const failStreakRef = useRef(0);

  const updateStatus = (updates) => {
    setStatus((previous) => {
      const next = { ...previous, ...updates };
      // Monotonic: once we've connected successfully, never let a later
      // failure downgrade this back to false. Callers only need to pass
      // hasConnectedOnce:true on a success; failures are ignored here.
      next.hasConnectedOnce = previous.hasConnectedOnce || next.hasConnectedOnce === true;
      onlineRef.current = next.online;
      return next;
    });
  };

  // showSpinner=true also means "trust this result immediately" (used for the
  // initial mount check and user-initiated Retry clicks). Passive/background
  // checks go through the same streak-counting as event-driven signals.
  const runHealthCheck = async (showSpinner = false) => {
    if (showSpinner) {
      updateStatus({
        known: true,
        checking: true,
        actionMessage: ''
      });
    }

    const online = await checkBackendHealth();
    if (!mountedRef.current) {
      return online;
    }

    if (online) {
      failStreakRef.current = 0;
      updateStatus({
        known: true,
        online: true,
        checking: false,
        reason: 'healthy',
        hasConnectedOnce: true
      });
      return true;
    }

    failStreakRef.current += 1;

    if (showSpinner || failStreakRef.current >= FAILURE_THRESHOLD) {
      updateStatus({
        known: true,
        online: false,
        checking: false,
        reason: 'unreachable'
      });
    } else {
      // First blip — don't block anything yet, just quietly re-check.
      updateStatus({ known: true, checking: false });
      window.setTimeout(() => {
        if (mountedRef.current) runHealthCheck(false);
      }, REVERIFY_DELAY_MS);
    }

    return false;
  };

  useEffect(() => {
    mountedRef.current = true;

    const handleStatusEvent = (event) => {
      const detail = event?.detail || {};
      const eventOnline = detail.online !== false;

      if (eventOnline) {
        failStreakRef.current = 0;
        updateStatus({
          known: true,
          online: true,
          checking: false,
          reason: detail.reason || 'healthy',
          hasConnectedOnce: true
        });
        return;
      }

      // An ordinary request failing (timeout, dropped connection, etc.) is a
      // hint, not confirmation. Re-verify against the dedicated health
      // endpoint — with its own streak-counting — instead of trusting a
      // single incidental failure enough to block the whole UI.
      runHealthCheck(false);
    };

    window.addEventListener(BACKEND_STATUS_EVENT, handleStatusEvent);
    runHealthCheck(true);

    const poller = window.setInterval(() => {
      if (!onlineRef.current) {
        runHealthCheck(false);
      }
    }, 5000);

    return () => {
      mountedRef.current = false;
      window.clearInterval(poller);
      window.removeEventListener(BACKEND_STATUS_EVENT, handleStatusEvent);
    };
  }, []);

  const handleRestartBackend = async () => {
    if (!window.electronAPI?.restartBackend) {
      return;
    }

    updateStatus({
      restartingBackend: true,
      actionMessage: 'Restarting backend...'
    });

    try {
      const result = await window.electronAPI.restartBackend();
      updateStatus({
        restartingBackend: false,
        actionMessage: result?.message || ''
      });
      await runHealthCheck(true);
    } catch (error) {
      console.error('Failed to restart backend:', error);
      updateStatus({
        restartingBackend: false,
        actionMessage: 'Backend restart failed.'
      });
    }
  };

  const handleRestartApp = async () => {
    updateStatus({
      restartingApp: true,
      actionMessage: 'Restarting app...'
    });

    if (!window.electronAPI?.reloadUI) {
      window.location.reload();
      return;
    }

    try {
      await window.electronAPI.reloadUI();
    } catch (error) {
      console.error('Failed to restart app:', error);
      updateStatus({
        restartingApp: false,
        actionMessage: 'App restart failed.'
      });
    }
  };

  const shouldBlockUi = !status.hasConnectedOnce && (!status.known || status.checking || !status.online);

  if (!shouldBlockUi && status.online && !status.checking) {
    return null;
  }

  const title = status.online
    ? 'Starting local services...'
    : 'Backend is still starting or unavailable';
  const description = status.online
    ? 'SMMS is waiting for Java, Spring Boot, and the local database to finish booting.'
    : 'This usually happens on low-configuration systems when the bundled Java backend needs more time.';

  if (!shouldBlockUi) {
    return (
      <div className={`backend-status-banner ${status.online ? 'warming' : 'offline'}`}>
        <div className="backend-status-banner-copy">
          <strong>{status.online ? 'Checking local services...' : 'Working with limited connectivity.'}</strong>
          <span>
            {status.online
              ? 'The app is verifying the local backend in the background.'
              : 'The backend looks temporarily unavailable, but the screen stays usable while we retry.'}
          </span>
        </div>

        <button
          type="button"
          className="backend-status-banner-btn"
          onClick={() => runHealthCheck(true)}
          disabled={status.checking || status.restartingBackend || status.restartingApp}
        >
          {status.checking ? <Loader2 size={15} className="spin" /> : <RefreshCw size={15} />}
          <span>{status.checking ? 'Checking...' : 'Retry'}</span>
        </button>
      </div>
    );
  }

  return (
    <div className="backend-status-gate">
      <div className="backend-status-card">
        <div className="backend-status-icon">
          {status.online ? <Loader2 size={26} className="spin" /> : <ServerCrash size={26} />}
        </div>

        <div className="backend-status-copy">
          <h3>{title}</h3>
          <p>{description}</p>
          <span className="backend-status-tip">
            Keep the app open for a moment. If the service stays stuck, use the recovery buttons below.
          </span>
        </div>

        {status.actionMessage && (
          <div className="backend-status-message">{status.actionMessage}</div>
        )}

        <div className="backend-status-actions">
          <button
            type="button"
            className="backend-status-btn secondary"
            onClick={() => runHealthCheck(true)}
            disabled={status.checking || status.restartingBackend || status.restartingApp}
          >
            {status.checking ? <Loader2 size={16} className="spin" /> : <RefreshCw size={16} />}
            <span>Retry Connection</span>
          </button>

          {window.electronAPI?.restartBackend && (
            <button
              type="button"
              className="backend-status-btn primary"
              onClick={handleRestartBackend}
              disabled={status.checking || status.restartingBackend || status.restartingApp}
            >
              {status.restartingBackend ? <Loader2 size={16} className="spin" /> : <RotateCcw size={16} />}
              <span>Restart Backend</span>
            </button>
          )}

          <button
            type="button"
            className="backend-status-btn ghost"
            onClick={handleRestartApp}
            disabled={status.restartingApp}
          >
            {status.restartingApp ? <Loader2 size={16} className="spin" /> : <RotateCcw size={16} />}
            <span>Restart App</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default BackendStatusGate;
