// Camera barcode/QR scanning (mobile only) — matches the reference
// billing app's scan-to-add button that sits next to the hardware
// RFID/barcode scanner input. Uses @capacitor-mlkit/barcode-scanning,
// which opens the device camera and decodes with ML Kit; this is
// separate from (and doesn't replace) the existing hardware-scanner
// text input, which keeps working as before on both desktop and mobile.
//
// All calls are safe to make even when the plugin isn't installed yet
// or the app isn't running natively — they just resolve to a "not
// available" result, so the rest of the app doesn't need to guard
// every call with isNativeApp() checks.

import { isNativeApp } from './api';

let pluginPromise = null;

// Lazily imported so desktop/web builds never need this dependency
// resolved, and so a missing/failed native plugin doesn't break startup.
const getPlugin = async () => {
    if (!isNativeApp()) return null;
    if (!pluginPromise) {
        pluginPromise = import('@capacitor-mlkit/barcode-scanning')
            .then((mod) => mod.BarcodeScanner)
            .catch((error) => {
                console.error('@capacitor-mlkit/barcode-scanning not available:', error);
                return null;
            });
    }
    return pluginPromise;
};

export const isCameraScanningSupported = () => isNativeApp();

// Opens the device camera, lets the user frame a single barcode/QR
// code, and resolves with the decoded text (or null if nothing was
// found/the scan was cancelled). Throws a plain, user-facing Error on
// permission denial or if the plugin/module isn't usable, so callers
// can show it directly in a toast.
export const scanBarcodeWithCamera = async () => {
    const plugin = await getPlugin();
    if (!plugin) throw new Error('Camera scanning is only available in the mobile app.');

    let permission;
    try {
        permission = await plugin.checkPermissions();
    } catch (error) {
        throw new Error('Could not access the camera on this device.');
    }

    if (permission.camera !== 'granted' && permission.camera !== 'limited') {
        const requested = await plugin.requestPermissions();
        if (requested.camera !== 'granted' && requested.camera !== 'limited') {
            throw new Error('Camera permission was denied. Enable it in phone Settings to scan.');
        }
    }

    // Android needs Google's barcode-scanner module downloaded once
    // on-device; iOS always reports it as available. Installing it
    // the first time can take a few seconds over WiFi/mobile data.
    try {
        const moduleStatus = await plugin.isGoogleBarcodeScannerModuleAvailable();
        if (!moduleStatus?.available) {
            await plugin.installGoogleBarcodeScannerModule();
        }
    } catch (error) {
        console.warn('Could not verify/install the barcode scanner module:', error);
    }

    const { barcodes } = await plugin.scan();
    if (!barcodes || barcodes.length === 0) return null;
    return barcodes[0].rawValue || barcodes[0].displayValue || null;
};
