import React from 'react';
import { 
  Store, Phone, Clock, CreditCard,
  ArrowRight, ShieldCheck, Activity, CheckCircle2
} from 'lucide-react';
import './ProfileSettings.css';

const OverviewSection = ({ 
  storeData, 
  contactInfo, 
  businessHours, 
  onNavigate,
  onOpenStoreProfile
}) => {
  const quickActions = [
    {
      id: 'store-overview',
      icon: Store,
      color: '#f97316',
      title: 'Store Overview',
      description: 'Manage your store information...',
      tags: ['Shop Name', 'Categories', 'Tagline'],
      onClick: () => onOpenStoreProfile && onOpenStoreProfile()
    },
    {
      id: 'contact-details',
      icon: Phone,
      color: '#10b981',
      title: 'Contact Details',
      description: 'Update your store address, phone, ema...',
      tags: ['Address', 'Phone', 'Email'],
      onClick: () => onNavigate('contact')
    },
    {
      id: 'business-hours',
      icon: Clock,
      color: '#eab308',
      title: 'Business Hours',
      description: 'Set your operating hours and working...',
      tags: ['Open/Close', 'Working Days'],
      onClick: () => onNavigate('business-hours')
    },
    {
      id: 'payment',
      icon: CreditCard,
      color: '#0ea5e9',
      title: 'Payment Setup',
      description: 'Review bank details and payment meth...',
      tags: ['Banking', 'UPI', 'Billing'],
      onClick: () => onNavigate('payment')
    },
  ];

  return (
    <div className="overview-section">
      {/* Welcome Header */}
      <div className="welcome-header">
        <div className="welcome-content">
          <h1>
            <CheckCircle2 size={28} className="welcome-icon" />
            Welcome to Profile Settings
          </h1>
          <p>
            Manage your store information, configure AI features, set up payment
            methods, and customize your business settings all in one place.
          </p>
          
          <div className="profile-stats">
            <div className="stat-item">
              <div className="stat-icon blue">
                <Activity size={18} />
              </div>
              <div className="stat-info">
                <span className="stat-label">Profile Completion</span>
                <span className="stat-value">85%</span>
              </div>
            </div>
            <div className="stat-item">
              <div className="stat-icon green">
                <CheckCircle2 size={18} />
              </div>
              <div className="stat-info">
                <span className="stat-label">Active Features</span>
                <span className="stat-value">12</span>
              </div>
            </div>
            <div className="stat-item">
              <div className="stat-icon purple">
                <ShieldCheck size={18} />
              </div>
              <div className="stat-info">
                <span className="stat-label">Security Score</span>
                <span className="stat-value">High</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Quick Action Cards Grid */}
      <div className="quick-actions-grid">
        {quickActions.map((action) => (
          <div 
            key={action.id} 
            className="quick-action-card"
            onClick={action.onClick}
          >
            <div className="action-card-header">
              <div 
                className="action-icon" 
                style={{ backgroundColor: `${action.color}15`, color: action.color }}
              >
                <action.icon size={20} />
              </div>
              <ArrowRight size={18} className="action-arrow" />
            </div>
            <h3>{action.title}</h3>
            <p>{action.description}</p>
            <div className="action-tags">
              {action.tags.map((tag, index) => (
                <span key={index} className="action-tag">{tag}</span>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default OverviewSection;
