import React, { useState, useEffect } from 'react';
import { 
  CreditCard, Building2, User, Hash, QrCode, Edit, Save, 
  Info, CheckCircle, Banknote, Smartphone
} from 'lucide-react';
import './ProfileSettings.css';

const PaymentSection = ({ paymentInfo, onSave }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState(paymentInfo);
  const [saving, setSaving] = useState(false);
  const [acceptedMethods, setAcceptedMethods] = useState({
    cash: true,
    upi: true,
    creditCard: true,
    debitCard: true,
    netBanking: true
  });

  // Sync form data when paymentInfo changes
  useEffect(() => {
    setFormData(paymentInfo);
  }, [paymentInfo]);

  const handleSave = async () => {
    setSaving(true);
    try {
      await onSave({ ...formData, acceptedMethods });
      setIsEditing(false);
    } catch (error) {
      console.error('Failed to save payment info:', error);
    } finally {
      setSaving(false);
    }
  };

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const togglePaymentMethod = (method) => {
    setAcceptedMethods(prev => ({ ...prev, [method]: !prev[method] }));
  };

  const paymentMethods = [
    { id: 'cash', label: 'Cash', icon: Banknote },
    { id: 'upi', label: 'UPI', icon: Smartphone },
    { id: 'creditCard', label: 'Credit Card', icon: CreditCard },
    { id: 'debitCard', label: 'Debit Card', icon: CreditCard },
    { id: 'netBanking', label: 'Net Banking', icon: Building2 },
  ];

  return (
    <div className="section-container">
      {/* Section Header */}
      <div className="section-header pink">
        <div className="section-header-content">
          <div className="section-title-group">
            <CreditCard size={24} />
            <div>
              <h2>Payment Information</h2>
              <p>Manage your bank details and accepted payment methods</p>
            </div>
          </div>
          <button 
            className="edit-details-btn"
            onClick={() => setIsEditing(!isEditing)}
          >
            <Edit size={16} />
            {isEditing ? 'Cancel' : 'Edit Details'}
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="section-content">
        {isEditing ? (
          <div className="edit-form">
            <div className="form-row">
              <div className="form-group">
                <label>Bank Name</label>
                <input
                  type="text"
                  value={formData.bankName}
                  onChange={(e) => handleChange('bankName', e.target.value)}
                  placeholder="Enter bank name"
                />
              </div>
              <div className="form-group">
                <label>Account Holder</label>
                <input
                  type="text"
                  value={formData.accountHolder}
                  onChange={(e) => handleChange('accountHolder', e.target.value)}
                  placeholder="Enter account holder name"
                />
              </div>
            </div>
            <div className="form-row">
              <div className="form-group">
                <label>Account Number</label>
                <input
                  type="text"
                  value={formData.accountNumber}
                  onChange={(e) => handleChange('accountNumber', e.target.value)}
                  placeholder="Enter account number"
                />
              </div>
              <div className="form-group">
                <label>IFSC Code</label>
                <input
                  type="text"
                  value={formData.ifscCode}
                  onChange={(e) => handleChange('ifscCode', e.target.value)}
                  placeholder="Enter IFSC code"
                />
              </div>
            </div>
            <div className="form-group">
              <label>UPI ID</label>
              <input
                type="text"
                value={formData.upiId}
                onChange={(e) => handleChange('upiId', e.target.value)}
                placeholder="Enter UPI ID"
              />
            </div>

            <div className="form-group">
              <label>Accepted Payment Methods</label>
              <div className="payment-methods-edit">
                {paymentMethods.map((method) => (
                  <button
                    key={method.id}
                    type="button"
                    className={`payment-method-toggle ${acceptedMethods[method.id] ? 'active' : ''}`}
                    onClick={() => togglePaymentMethod(method.id)}
                  >
                    <method.icon size={16} />
                    {method.label}
                  </button>
                ))}
              </div>
            </div>

            <div className="form-actions">
              <button className="cancel-btn" onClick={() => setIsEditing(false)} disabled={saving}>
                Cancel
              </button>
              <button className="save-btn" onClick={handleSave} disabled={saving}>
                <Save size={16} />
                {saving ? 'Saving...' : 'Save Changes'}
              </button>
            </div>
          </div>
        ) : (
          <div className="payment-display">
            {/* Bank Details Grid */}
            <div className="payment-cards-grid">
              <div className="payment-card">
                <div className="payment-card-icon red">
                  <Building2 size={20} />
                </div>
                <div className="payment-card-details">
                  <span className="payment-label">Bank Name</span>
                  <span className="payment-value">{paymentInfo.bankName || 'Not provided'}</span>
                </div>
              </div>

              <div className="payment-card">
                <div className="payment-card-icon blue">
                  <User size={20} />
                </div>
                <div className="payment-card-details">
                  <span className="payment-label">Account Holder</span>
                  <span className="payment-value">{paymentInfo.accountHolder || 'Not provided'}</span>
                </div>
              </div>

              <div className="payment-card">
                <div className="payment-card-icon green">
                  <Hash size={20} />
                </div>
                <div className="payment-card-details">
                  <span className="payment-label">Account Number</span>
                  <span className="payment-value">{paymentInfo.accountNumber || 'Not provided'}</span>
                </div>
              </div>

              <div className="payment-card">
                <div className="payment-card-icon purple">
                  <Hash size={20} />
                </div>
                <div className="payment-card-details">
                  <span className="payment-label">IFSC Code</span>
                  <span className="payment-value">{paymentInfo.ifscCode || 'Not provided'}</span>
                </div>
              </div>

              <div className="payment-card full-width">
                <div className="payment-card-icon teal">
                  <QrCode size={20} />
                </div>
                <div className="payment-card-details">
                  <span className="payment-label">UPI ID</span>
                  <span className="payment-value">{paymentInfo.upiId || 'Not provided'}</span>
                </div>
              </div>
            </div>

            {/* Accepted Payment Methods */}
            <div className="accepted-methods-section">
              <h3>Accepted Payment Methods</h3>
              <div className="methods-list">
                {paymentMethods.filter(m => acceptedMethods[m.id]).map((method) => (
                  <span key={method.id} className="method-badge">
                    <CheckCircle size={14} />
                    {method.label}
                  </span>
                ))}
              </div>
            </div>

            {/* Info Banner */}
            <div className="info-banner warning">
              <Info size={18} />
              <div>
                <strong>Payment Security</strong>
                <p>Your payment information is encrypted and securely stored. Only essential banking details are required for transactions. UPI ID enables quick and easy payments from customers.</p>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default PaymentSection;
