import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import './index.css'
import App from './App.jsx'

if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.getRegistrations()
      .then((registrations) => Promise.all(registrations.map((registration) => registration.unregister())))
      .catch((error) => {
        console.error('Service worker cleanup failed:', error)
      })
  })
}

// On the mobile app (built with Capacitor), there is no bundled backend —
// the app needs to know which server to talk to. Rather than blocking
// startup with a native prompt, it boots straight in (same as the
// reference billing app) and falls back to a default address until the
// person sets the real one from Profile > Server Connection. If that
// default is unreachable, BackendStatusGate shows an offline state with
// a direct link to that settings screen — so first-run setup happens
// inside the app's own UI, not a native OS popup.
createRoot(document.getElementById('root')).render(
  <StrictMode>
    <App />
  </StrictMode>,
)
