import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const InventoryStatusChart = ({ data = [] }) => {
  if (!data.length) {
    return (
      <div className="text-center py-5 text-muted">
        <p>No inventory data available</p>
      </div>
    );
  }
  return (
    <ResponsiveContainer width="100%" height={280}>
      <BarChart data={data} margin={{ top: 5, right: 20, left: 0, bottom: 5 }}>
        <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
        <XAxis dataKey="category" stroke="#6b7280" />
        <YAxis stroke="#6b7280" />
        <Tooltip />
        <Legend />
        <Bar dataKey="inStock"    name="In Stock"     fill="#16a34a" radius={[4,4,0,0]} />
        <Bar dataKey="lowStock"   name="Low Stock"    fill="#d97706" radius={[4,4,0,0]} />
        <Bar dataKey="outOfStock" name="Out of Stock" fill="#dc2626" radius={[4,4,0,0]} />
      </BarChart>
    </ResponsiveContainer>
  );
};

export default InventoryStatusChart;
