import { useEffect, useState } from 'react';
import { Loader2, RefreshCw, Server } from 'lucide-react';
import './AppControlsPanel.css';

const BUILD_TIME = typeof __APP_BUILD_TIME__ !== 'undefined' ? __APP_BUILD_TIME__ : null;
const BUILD_VERSION = typeof __APP_BUILD_VERSION__ !== 'undefined' ? __APP_BUILD_VERSION__ : null;

const INITIAL_APP_INFO = {
  version: 'Web',
  isDev: false,
  backendRunning: false,
  backendHealthy: false,
  backendStatusMessage: '',
  startupLogPath: '',
  isBackendRestarting: false
};

const INITIAL_ACTION_STATE = {
  reloading: false,
  restartingBackend: false,
  message: ''
};

const formatBuildTime = (value) => {
  if (!value) return 'Unknown';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString('en-IN', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
};

const AppControlsPanel = ({ embedded = false }) => {
  const [appInfo, setAppInfo] = useState(INITIAL_APP_INFO);
  const [appActionState, setAppActionState] = useState(INITIAL_ACTION_STATE);

  const refreshAppInfo = async () => {
    if (!window.electronAPI?.getAppInfo) return;

    try {
      const info = await window.electronAPI.getAppInfo();
      setAppInfo({
        version: info?.version || 'Unknown',
        isDev: Boolean(info?.isDev),
        backendRunning: Boolean(info?.backendRunning),
        backendHealthy: Boolean(info?.backendHealthy),
        backendStatusMessage: info?.backendStatusMessage || '',
        startupLogPath: info?.startupLogPath || '',
        isBackendRestarting: Boolean(info?.isBackendRestarting)
      });
    } catch (error) {
      console.error('Failed to refresh app info:', error);
    }
  };

  useEffect(() => {
    refreshAppInfo();
  }, []);

  const handleReloadUI = async () => {
    if (!window.electronAPI?.reloadUI) {
      setAppActionState({
        reloading: false,
        restartingBackend: false,
        message: 'Reload UI refreshes the current app only. New source changes still need a new build.'
      });
      window.location.reload();
      return;
    }

    setAppActionState({
      reloading: true,
      restartingBackend: false,
      message: window.electronAPI?.reloadUI
        ? 'Restarting app to load the latest installed build...'
        : 'Reloading current app...'
    });
    await window.electronAPI.reloadUI();
  };

  const handleRestartBackend = async () => {
    if (!window.electronAPI?.restartBackend) {
      setAppActionState({
        reloading: false,
        restartingBackend: false,
        message: 'Backend restart is only available inside the desktop app.'
      });
      return;
    }

    setAppActionState({
      reloading: false,
      restartingBackend: true,
      message: 'Restarting backend...'
    });

    try {
      const result = await window.electronAPI.restartBackend();
      setAppActionState({
        reloading: false,
        restartingBackend: false,
        message: result?.message || (result?.success ? 'Backend restarted successfully.' : 'Backend restart failed.')
      });
      await refreshAppInfo();
      if (result?.success) {
        setTimeout(() => {
          window.location.reload();
        }, 400);
      }
    } catch (error) {
      console.error('Failed to restart backend:', error);
      setAppActionState({
        reloading: false,
        restartingBackend: false,
        message: 'Backend restart failed.'
      });
    }
  };

  return (
    <div className={`app-controls-card ${embedded ? 'embedded' : ''}`}>
      <div className="app-controls-header">
        <div>
          <h4>App Controls</h4>
          <p>Version {appInfo.version || BUILD_VERSION || 'Unknown'}{appInfo.isDev ? ' · Dev' : ''}</p>
          <p className="app-controls-build-time">Built {formatBuildTime(BUILD_TIME)}</p>
        </div>
      </div>

      <div className="app-controls-status">
        <span className={`status-dot ${appInfo.backendHealthy ? 'online' : 'offline'}`}></span>
        <span>
          {appInfo.backendHealthy
            ? 'Backend ready'
            : appInfo.backendRunning
              ? 'Backend starting...'
              : 'Backend not detected'}
        </span>
      </div>

      {appInfo.backendStatusMessage && (
        <div className="app-controls-message">
          {appInfo.backendStatusMessage}
        </div>
      )}

      {appActionState.message && (
        <div className="app-controls-message">
          {appActionState.message}
        </div>
      )}

      <div className="app-controls-actions">
        <button
          className="app-control-action"
          onClick={handleReloadUI}
          disabled={appActionState.reloading || appActionState.restartingBackend}
        >
          {appActionState.reloading ? <Loader2 size={16} className="spin" /> : <RefreshCw size={16} />}
          <span>Restart App</span>
        </button>

        <button
          className="app-control-action"
          onClick={handleRestartBackend}
          disabled={appActionState.reloading || appActionState.restartingBackend}
        >
          {appActionState.restartingBackend ? <Loader2 size={16} className="spin" /> : <Server size={16} />}
          <span>Restart Backend</span>
        </button>
      </div>

      <div className="app-controls-footnote">
        Source code edits only appear after you create a new desktop build. These buttons refresh the currently installed build.
      </div>

      {appInfo.startupLogPath && !appInfo.backendHealthy && (
        <div className="app-controls-footnote">
          Startup log: {appInfo.startupLogPath}
        </div>
      )}
    </div>
  );
};

export default AppControlsPanel;
