// Offline sale queue — matches the billing app's offline-first pattern:
// when a sale can't reach the backend (WiFi drop, PC asleep, out of
// range), it's saved locally instead of lost, and synced automatically
// the next time the backend becomes reachable.
//
// Only sales are queued (SMMS, unlike the billing app, doesn't have
// separate invoice/expense/payment entities — a POS sale is the one
// action that must never silently fail at checkout).

import { saleService, isBackendUnavailableError, BACKEND_STATUS_EVENT } from './api';

const QUEUE_KEY = 'smms_offline_sales_queue';
export const QUEUE_CHANGED_EVENT = 'smms:offline-queue-changed';

const genId = () => {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
    return `offline-${Date.now()}-${Math.random().toString(16).slice(2)}`;
};

const read = () => {
    if (typeof window === 'undefined') return [];
    try {
        return JSON.parse(window.localStorage.getItem(QUEUE_KEY) || '[]');
    } catch {
        return [];
    }
};

const write = (items) => {
    if (typeof window === 'undefined') return;
    window.localStorage.setItem(QUEUE_KEY, JSON.stringify(items));
    window.dispatchEvent(new CustomEvent(QUEUE_CHANGED_EVENT, { detail: { count: items.length } }));
};

export const getPendingQueue = () => read();
export const getPendingCount = () => read().length;

// Attaches a stable clientRequestId (used by every attempt, online or
// queued) so a retried sync can never create a duplicate sale server-side.
export const prepareSalePayload = (payload) => ({
    ...payload,
    clientRequestId: payload.clientRequestId || genId(),
});

// Saves a sale locally after a failed online attempt. The payload should
// already carry the clientRequestId used on that failed attempt, so the
// eventual sync is the SAME request, not a new one.
export const queueSale = (payload) => {
    const items = read();
    items.push({
        id: payload.clientRequestId || genId(),
        entityType: 'SALE',
        payload: prepareSalePayload(payload),
        queuedAt: new Date().toISOString(),
        attempts: 0,
        lastError: null,
    });
    write(items);
    return items[items.length - 1];
};

const removeById = (id) => {
    write(read().filter((item) => item.id !== id));
};

const bumpAttempt = (id, errorMessage) => {
    write(read().map((item) =>
        item.id === id
            ? { ...item, attempts: (item.attempts || 0) + 1, lastError: errorMessage }
            : item
    ));
};

let syncing = false;

// Pushes every queued sale to the backend, oldest first. Stops immediately
// on a connectivity failure (nothing left to try right now); a real
// server-side rejection (bad data) is logged and left in the queue rather
// than silently discarded, so a person can review it instead of losing it.
export const syncQueue = async () => {
    if (syncing) return { synced: 0, remaining: getPendingCount() };
    syncing = true;
    let synced = 0;

    try {
        const items = read();
        for (const item of items) {
            if (item.entityType !== 'SALE') continue;
            try {
                await saleService.create(item.payload);
                removeById(item.id);
                synced += 1;
            } catch (error) {
                if (isBackendUnavailableError(error)) {
                    // Backend went away again mid-sync — stop here, the
                    // rest stay queued for the next reconnect.
                    break;
                }
                // Server responded but rejected it (validation error etc.) —
                // keep it queued and visible rather than losing the sale.
                const message = error.response?.data || error.message || 'Sync failed';
                bumpAttempt(item.id, typeof message === 'string' ? message : JSON.stringify(message));
            }
        }
    } finally {
        syncing = false;
    }

    return { synced, remaining: getPendingCount() };
};

// Auto-sync whenever the app transitions from offline to online. Runs on
// every platform (desktop benefits from the same safety net), but the
// queue only ever fills up when a checkout genuinely can't reach the
// backend, which in practice is mobile's WiFi/LAN scenario.
let wasOnline = true;
if (typeof window !== 'undefined') {
    window.addEventListener(BACKEND_STATUS_EVENT, (event) => {
        const online = event?.detail?.online !== false;
        if (online && !wasOnline && getPendingCount() > 0) {
            syncQueue();
        }
        wasOnline = online;
    });
}
