import { useState, useEffect, useRef } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { ShoppingCart, Package, ShoppingBag, User, Bell, LogOut, AlertTriangle, X, Keyboard, CloudOff, Loader2 } from 'lucide-react';
import { productService } from '../../services/api';
import { getPendingCount, syncQueue, QUEUE_CHANGED_EVENT } from '../../services/offlineQueue';
import appIcon from '../../assets/icon.png';
import './Header.css';

const Header = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [notifications, setNotifications] = useState([]);
  const [showNotifications, setShowNotifications] = useState(false);
  const notificationRef = useRef(null);
  const isPosPage = location.pathname === '/shop';
  const [pendingSyncCount, setPendingSyncCount] = useState(getPendingCount());
  const [syncing, setSyncing] = useState(false);

  const userStr = localStorage.getItem('user');
  const user = userStr ? JSON.parse(userStr) : null;

  const navItems = [
    { path: '/dashboard', label: 'Dashboard', icon: ShoppingCart },
    { path: '/inventory', label: 'Inventory', icon: Package },
    { path: '/shop', label: 'POS', icon: ShoppingBag },
    { path: '/profile', label: 'Profile', icon: User },
  ];

  useEffect(() => {
    const fetchLowStockProducts = async () => {
      try {
        const response = await productService.getAll();
        const products = response.data || [];
        const alerts = [];

        products.forEach(product => {
          if (product.quantity > 0 && product.quantity <= 10) {
            alerts.push({
              id: `low-${product.id}`,
              type: 'warning',
              title: 'Low Stock Alert',
              message: `${product.itemName} has only ${product.quantity} units left`,
              productId: product.id,
              timestamp: new Date()
            });
          }

          if (product.quantity === 0) {
            alerts.push({
              id: `out-${product.id}`,
              type: 'danger',
              title: 'Out of Stock',
              message: `${product.itemName} is out of stock`,
              productId: product.id,
              timestamp: new Date()
            });
          }

          if (product.expiryDate) {
            const expiry = new Date(product.expiryDate);
            const today = new Date();
            const diffDays = Math.ceil((expiry - today) / (1000 * 60 * 60 * 24));

            if (diffDays <= 0) {
              alerts.push({
                id: `expired-${product.id}`,
                type: 'danger',
                title: 'Product Expired',
                message: `${product.itemName} has expired`,
                productId: product.id,
                timestamp: new Date()
              });
            } else if (diffDays <= 7) {
              alerts.push({
                id: `expiring-${product.id}`,
                type: 'warning',
                title: 'Expiring Soon',
                message: `${product.itemName} expires in ${diffDays} day${diffDays > 1 ? 's' : ''}`,
                productId: product.id,
                timestamp: new Date()
              });
            }
          }
        });

        setNotifications(alerts);
      } catch (error) {
        console.error('Error fetching notifications:', error);
      }
    };

    if (user && !isPosPage) {
      fetchLowStockProducts();
      const interval = setInterval(fetchLowStockProducts, 30000);
      return () => clearInterval(interval);
    }
  }, [isPosPage, user]);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (notificationRef.current && !notificationRef.current.contains(event.target)) {
        setShowNotifications(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    const handleQueueChanged = (event) => {
      setPendingSyncCount(event?.detail?.count ?? getPendingCount());
    };
    window.addEventListener(QUEUE_CHANGED_EVENT, handleQueueChanged);
    return () => window.removeEventListener(QUEUE_CHANGED_EVENT, handleQueueChanged);
  }, []);

  const handleManualSync = async () => {
    if (syncing || pendingSyncCount === 0) return;
    setSyncing(true);
    try {
      await syncQueue();
    } finally {
      setSyncing(false);
    }
  };

  const isActive = (path) => location.pathname === path;

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("adminToken");
    localStorage.removeItem("user");
    localStorage.removeItem("admin");
    navigate('/login');
  };

  const dismissNotification = (id) => {
    setNotifications(notifications.filter(n => n.id !== id));
  };

  const togglePosShortcuts = () => {
    window.dispatchEvent(new CustomEvent('smms:toggle-shortcuts'));
  };

  return (
    <header className="header">
      <div className="header-container">
        <div className="header-left">
          <div className="logo" style={{ cursor: 'pointer' }} onClick={() => navigate('/dashboard')}>
            <ShoppingCart className="logo-icon" />
            <span className="logo-text">SuperMart</span>
          </div>

          <nav className="nav">
            {navItems.map((item) => {
              const Icon = item.icon;
              return (
                <Link
                  key={item.path}
                  to={item.path}
                  className={`nav-item ${isActive(item.path) ? 'active' : ''}`}
                >
                  <Icon size={18} />
                  <span>{item.label}</span>
                </Link>
              );
            })}
          </nav>
        </div>

        <div className="header-right">
          {isPosPage && (
            <button
              type="button"
              className="shortcut-nav-btn"
              onClick={togglePosShortcuts}
              title="Keyboard Shortcuts (?)"
            >
              <Keyboard size={16} />
              <span>Shortcuts</span>
            </button>
          )}

          {pendingSyncCount > 0 && (
            <button
              className="icon-button notification-btn"
              onClick={handleManualSync}
              disabled={syncing}
              title={syncing ? 'Syncing offline sales...' : `${pendingSyncCount} sale(s) saved offline — tap to sync now`}
            >
              {syncing ? <Loader2 size={20} className="spin" /> : <CloudOff size={20} />}
              <span className="notification-badge">{pendingSyncCount}</span>
            </button>
          )}

          <div className="notification-wrapper" ref={notificationRef}>
            <button
              className="icon-button notification-btn"
              onClick={() => setShowNotifications(!showNotifications)}
            >
              <Bell size={20} />
              {notifications.length > 0 && (
                <span className="notification-badge">{notifications.length}</span>
              )}
            </button>

            {showNotifications && (
              <div className="notification-dropdown">
                <div className="notification-header">
                  <h4>Notifications</h4>
                  <span className="notification-count">{notifications.length} alerts</span>
                </div>

                <div className="notification-list">
                  {notifications.length === 0 ? (
                    <div className="no-notifications">
                      <Bell size={32} />
                      <p>No alerts at this time</p>
                    </div>
                  ) : (
                    notifications.map(notification => (
                      <div
                        key={notification.id}
                        className={`notification-item ${notification.type}`}
                        onClick={() => navigate('/inventory')}
                      >
                        <div className="notification-icon">
                          <AlertTriangle size={18} />
                        </div>
                        <div className="notification-content">
                          <span className="notification-title">{notification.title}</span>
                          <p className="notification-message">{notification.message}</p>
                        </div>
                        <button
                          className="dismiss-btn"
                          onClick={(e) => {
                            e.stopPropagation();
                            dismissNotification(notification.id);
                          }}
                        >
                          <X size={14} />
                        </button>
                      </div>
                    ))
                  )}
                </div>

                {notifications.length > 0 && (
                  <div className="notification-footer">
                    <button onClick={() => navigate('/inventory')}>View Inventory</button>
                  </div>
                )}
              </div>
            )}
          </div>

          <div className="user-info">
            <div className="user-avatar">
              <img src={appIcon} alt="User Avatar" style={{ width: '100%', height: '100%', objectFit: 'contain' }} />
            </div>
            <span className="user-email">{user?.email || 'Guest User'}</span>
          </div>

          <button className="logout-button" onClick={handleLogout}>
            <LogOut size={18} />
            <span>Logout</span>
          </button>
        </div>
      </div>
    </header>
  );
};

export default Header;
