import { useState, useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { Settings } from 'lucide-react';
import AppControlsPanel from '../components/common/AppControlsPanel';
import MobileServerSettings from '../components/common/MobileServerSettings';
import BluetoothPrinterSettings from '../components/common/BluetoothPrinterSettings';
import ProfileSidebar from '../components/profile/ProfileSidebar';
import OverviewSection from '../components/profile/OverviewSection';
import ContactSection from '../components/profile/ContactSection';
import BusinessHoursSection from '../components/profile/BusinessHoursSection';
import PaymentSection from '../components/profile/PaymentSection';
import DevicesSection from '../components/profile/DevicesSection';
import StoreProfileModal from '../components/profile/StoreProfileModal';
import EditProfileModal from '../components/profile/EditProfileModal';
import SupportCenter from '../components/profile/SupportCenter';
import { profileService, isNativeApp } from '../services/api';
import storage from '../utils/storage';
import '../components/profile/ProfileSettings.css';
import './Profile.css';

const Profile = () => {
  const location = useLocation();
  const [activeSection, setActiveSection] = useState(location.state?.profileSection || 'overview');
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isStoreProfileModalOpen, setIsStoreProfileModalOpen] = useState(false);
  const logoInputRef = useRef(null);
  const [uploading, setUploading] = useState(false);
  const [devices, setDevices] = useState([]);

  const getUserData = () => {
    const user = storage.get('user') || {};
    return {
      name: user.fullName || user.name || user.username || 'User',
      email: user.email || 'user@email.com',
      phone: user.phone || '',
      shopName: user.shopName || '',
      role: user.role || 'User'
    };
  };

  const [userData, setUserData] = useState(getUserData());

  const handleLogoUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setUploading(true);
    try {
      const uploadRes = await profileService.uploadFile(file);
      const logoUrl = 'http://localhost:8080' + uploadRes.data;
      setStoreData(prev => ({ ...prev, logo: logoUrl }));
      const currentProfile = await profileService.getProfile();
      await profileService.updateProfile({ ...currentProfile.data, logoUrl });
    } catch (err) {
      console.error('Logo upload failed:', err);
      alert('Failed to upload photo. Please try again.');
    } finally {
      setUploading(false);
    }
  };

  const [storeData, setStoreData] = useState({
    name: '',
    tagline: '',
    address: '',
    logo: null,
    accountId: '',
    since: '',
    area: '',
    category: '',
    categories: []
  });

  const [contactInfo, setContactInfo] = useState({
    address: '',
    phone: '',
    email: '',
    website: '',
    instagram: '',
    twitter: ''
  });

  const [businessHours, setBusinessHours] = useState({
    opening: '',
    closing: '',
    workingDays: ''
  });

  const [paymentInfo, setPaymentInfo] = useState({
    bankName: '',
    accountHolder: '',
    accountNumber: '',
    ifscCode: '',
    upiId: ''
  });

  const [aiConfig, setAiConfig] = useState({
    mode: 'Manual AI',
    voiceAI: true,
    autoInventory: false,
    autoOrders: false,
    billingMode: 'Manual',
    autoConfirm: 'Manual',
    paperSize: '80mm'
  });

  const [businessReg, setBusinessReg] = useState({
    gstin: '29ABCDE1234F1Z5',
    pan: 'ABCDE1234F',
    regNo: '12345678901',
    cin: 'U74999MH2021PTC123456'
  });

  const [paymentGateways, setPaymentGateways] = useState({
    paytm: { merchantId: '', merchantKey: '', webhookUrl: '', enabled: false },
    phonePe: { merchantId: '', saltKey: '', saltIndex: '', enabled: false },
    razorpay: { keyId: '', keySecret: '', webhookSecret: '', enabled: false },
    payu: { merchantKey: '', salt: '', enabled: false }
  });

  const [storeFeatures, setStoreFeatures] = useState({
    homeDelivery: false,
    parkingAvailable: false,
    onlineOrders: false,
    parkingCapacity: '15'
  });

  const [taxConfig, setTaxConfig] = useState({
    enabled: true,
    gstin: '29ABCDE1234F1Z5',
    pan: 'ABCDE1234F',
    taxRate: 10
  });

  const fetchProfile = async () => {
    try {
      const storedUser = getUserData();
      setUserData(storedUser);

      const profileRes = await profileService.getProfile();
      const data = profileRes.data;
      if (!data) {
        return;
      }

      setStoreData({
        name: data.storeName || storedUser.shopName || 'FreshMart Superstore',
        tagline: data.description || 'Your Daily Needs, Delivered Fresh',
        address: data.address || '',
        logo: data.logoUrl,
        accountId: data.storeId || '5',
        since: '2018',
        area: '2500 sq ft',
        category: data.storeType || 'Supermarket',
        categories: ['Groceries', 'Fresh Produce', 'Dairy', 'Beverages', 'Snacks', 'Household']
      });

      setContactInfo({
        address: data.address || '',
        phone: data.phone || storedUser.phone || '',
        email: data.email || storedUser.email || '',
        website: data.website || '',
        instagram: data.instagramUrl || '',
        twitter: data.twitterUrl || ''
      });

      setPaymentInfo({
        bankName: data.bankName || '',
        accountHolder: data.accountHolder || '',
        accountNumber: data.accountNumber || '',
        ifscCode: data.ifscCode || '',
        upiId: data.upiId || ''
      });

      setBusinessReg({
        gstin: data.gstin || '',
        pan: data.pan || '',
        regNo: data.regNo || '',
        cin: data.cin || ''
      });

      setPaymentGateways({
        paytm: { merchantId: data.paytmMid || '', merchantKey: data.paytmKey || '', enabled: data.paytmEnabled || false },
        phonePe: { merchantId: data.phonePeMerchantId || '', saltKey: data.phonePeSaltKey || '', saltIndex: data.phonePeSaltIndex || '', enabled: data.phonePeEnabled || false },
        razorpay: { keyId: data.razorpayKeyId || '', keySecret: data.razorpayKeySecret || '', enabled: data.razorpayEnabled || false },
        payu: { merchantKey: data.payuMerchantKey || '', salt: data.payuSalt || '', enabled: data.payuEnabled || false }
      });

      setStoreFeatures({
        homeDelivery: data.homeDelivery || false,
        parkingAvailable: data.parkingAvailable || false,
        onlineOrders: data.onlineOrders || false,
        parkingCapacity: data.parkingCapacity?.toString() || ''
      });

      setTaxConfig({
        enabled: data.enableTax || false,
        gstin: data.gstin || '',
        pan: data.pan || '',
        taxRate: data.taxRate || 0
      });

      setBusinessHours({
        opening: data.openingTime || '7:00 AM',
        closing: data.closingTime || '10:00 PM',
        workingDays: data.workingDays || 'Monday to Sunday'
      });
    } catch (error) {
      console.error("Failed to fetch profile data:", error);
    }
  };

  useEffect(() => {
    fetchProfile();
  }, []);

  const handleSaveProfile = async (updatedData) => {
    setStoreData(updatedData.storeData);
    setContactInfo(updatedData.contactInfo);
    setPaymentInfo(updatedData.paymentInfo);
    setAiConfig(updatedData.aiConfig);
    setBusinessReg(updatedData.businessReg);
    setPaymentGateways(updatedData.paymentGateways);
    setStoreFeatures(updatedData.storeFeatures);
    setTaxConfig(updatedData.taxConfig);

    const payload = {
      storeName: updatedData.storeData.name,
      description: updatedData.storeData.tagline,
      storeType: updatedData.storeData.category,
      logoUrl: updatedData.storeData.logo,
      address: updatedData.contactInfo.address,
      phone: updatedData.contactInfo.phone,
      email: updatedData.contactInfo.email,
      website: updatedData.contactInfo.website,
      instagramUrl: updatedData.contactInfo.instagram,
      twitterUrl: updatedData.contactInfo.twitter,
      bankName: updatedData.paymentInfo.bankName,
      accountHolder: updatedData.paymentInfo.accountHolder,
      accountNumber: updatedData.paymentInfo.accountNumber,
      ifscCode: updatedData.paymentInfo.ifscCode,
      upiId: updatedData.paymentInfo.upiId,
      gstin: updatedData.businessReg.gstin || updatedData.taxConfig.gstin,
      pan: updatedData.businessReg.pan || updatedData.taxConfig.pan,
      regNo: updatedData.businessReg.regNo,
      cin: updatedData.businessReg.cin,
      paytmMid: updatedData.paymentGateways.paytm.merchantId,
      paytmKey: updatedData.paymentGateways.paytm.merchantKey,
      paytmEnabled: updatedData.paymentGateways.paytm.enabled,
      phonePeMerchantId: updatedData.paymentGateways.phonePe.merchantId,
      phonePeSaltKey: updatedData.paymentGateways.phonePe.saltKey,
      phonePeSaltIndex: parseInt(updatedData.paymentGateways.phonePe.saltIndex) || 0,
      phonePeEnabled: updatedData.paymentGateways.phonePe.enabled,
      razorpayKeyId: updatedData.paymentGateways.razorpay.keyId,
      razorpayKeySecret: updatedData.paymentGateways.razorpay.keySecret,
      razorpayEnabled: updatedData.paymentGateways.razorpay.enabled,
      payuMerchantKey: updatedData.paymentGateways.payu.merchantKey,
      payuSalt: updatedData.paymentGateways.payu.salt,
      payuEnabled: updatedData.paymentGateways.payu.enabled,
      homeDelivery: updatedData.storeFeatures.homeDelivery,
      parkingAvailable: updatedData.storeFeatures.parkingAvailable,
      onlineOrders: updatedData.storeFeatures.onlineOrders,
      parkingCapacity: parseInt(updatedData.storeFeatures.parkingCapacity) || 0,
      enableTax: updatedData.taxConfig.enabled,
      taxRate: parseFloat(updatedData.taxConfig.taxRate) || 0,
      openingTime: businessHours.opening,
      closingTime: businessHours.closing,
      workingDays: businessHours.workingDays
    };
    try {
      await profileService.updateProfile(payload);
    } catch (error) {
      console.error("Failed to update profile:", error);
    }
  };

  const handleSaveStoreProfile = async (updatedStoreData) => {
    setStoreData(updatedStoreData);

    const payload = {
      storeName: updatedStoreData.name,
      description: updatedStoreData.tagline,
      address: updatedStoreData.address,
      storeType: updatedStoreData.category,
      logoUrl: updatedStoreData.logo,
    };

    try {
      const currentProfile = await profileService.getProfile();
      await profileService.updateProfile({ ...currentProfile.data, ...payload });
    } catch (error) {
      console.error("Failed to update store profile:", error);
    }
  };

  const handleSaveContact = async (updatedContactInfo) => {
    setContactInfo(updatedContactInfo);

    const payload = {
      address: updatedContactInfo.address,
      phone: updatedContactInfo.phone,
      email: updatedContactInfo.email,
      website: updatedContactInfo.website,
    };

    try {
      const currentProfile = await profileService.getProfile();
      await profileService.updateProfile({ ...currentProfile.data, ...payload });
    } catch (error) {
      console.error("Failed to update contact info:", error);
    }
  };

  const handleSaveBusinessHours = async (updatedBusinessHours) => {
    setBusinessHours(updatedBusinessHours);

    const payload = {
      openingTime: updatedBusinessHours.opening,
      closingTime: updatedBusinessHours.closing,
      workingDays: updatedBusinessHours.workingDays,
    };

    try {
      const currentProfile = await profileService.getProfile();
      await profileService.updateProfile({ ...currentProfile.data, ...payload });
    } catch (error) {
      console.error("Failed to update business hours:", error);
    }
  };

  const handleSavePayment = async (updatedPaymentInfo) => {
    setPaymentInfo(updatedPaymentInfo);

    const payload = {
      bankName: updatedPaymentInfo.bankName,
      accountHolder: updatedPaymentInfo.accountHolder,
      accountNumber: updatedPaymentInfo.accountNumber,
      ifscCode: updatedPaymentInfo.ifscCode,
      upiId: updatedPaymentInfo.upiId,
    };

    try {
      const currentProfile = await profileService.getProfile();
      await profileService.updateProfile({ ...currentProfile.data, ...payload });
    } catch (error) {
      console.error("Failed to update payment info:", error);
    }
  };

  const handleAddDevice = (device) => {
    setDevices(prev => [...prev, device]);
  };

  const handleDeleteDevice = (deviceId) => {
    setDevices(prev => prev.filter(d => d.id !== deviceId));
  };

  const fullProfileData = {
    storeData,
    contactInfo,
    paymentInfo,
    aiConfig,
    businessReg,
    businessHours,
    paymentGateways,
    storeFeatures,
    taxConfig
  };

  const renderContent = () => {
    switch (activeSection) {
      case 'overview':
        return (
          <OverviewSection
            storeData={storeData}
            contactInfo={contactInfo}
            businessHours={businessHours}
            onNavigate={setActiveSection}
            onOpenStoreProfile={() => setIsStoreProfileModalOpen(true)}
          />
        );
      case 'contact':
        return (
          <ContactSection
            contactInfo={contactInfo}
            onSave={handleSaveContact}
          />
        );
      case 'business-hours':
        return (
          <BusinessHoursSection
            businessHours={businessHours}
            onSave={handleSaveBusinessHours}
          />
        );
      case 'payment':
        return (
          <PaymentSection
            paymentInfo={paymentInfo}
            onSave={handleSavePayment}
          />
        );
      case 'devices':
        return (
          <DevicesSection
            devices={devices}
            onAddDevice={handleAddDevice}
            onDeleteDevice={handleDeleteDevice}
          />
        );
      case 'support':
        return <SupportCenter onBack={() => setActiveSection('overview')} />;
      case 'app-controls':
        return (
          <div className="app-controls-section">
            <div className="app-controls-section-header">
              <div>
                <h2>{isNativeApp() ? 'Server Connection' : 'App Controls'}</h2>
                <p>
                  {isNativeApp()
                    ? 'Tell the app which PC on your WiFi network is running SMMS.'
                    : 'Use desktop tools here to refresh the installed UI or restart the local backend service.'}
                </p>
              </div>
            </div>

            <div className="app-controls-section-grid">
              {isNativeApp() ? (
                <>
                  <MobileServerSettings embedded={true} />

                  <BluetoothPrinterSettings embedded={true} />

                  <div className="app-controls-help-card">
                    <h3>How It Works</h3>
                    <p>
                      SMMS on your phone connects to the same backend that runs on your PC — your products,
                      sales and data all stay on that PC.
                    </p>
                    <p>
                      Both devices need to be on the same WiFi network, and the SMMS desktop app needs to be
                      open on the PC for this phone app to work.
                    </p>
                    <p>
                      Find your PC's IP with <code>ipconfig</code> (Windows) under the WiFi adapter's
                      "IPv4 Address".
                    </p>
                  </div>
                </>
              ) : (
                <>
                  <AppControlsPanel embedded={true} />

                  <div className="app-controls-help-card">
                    <h3>How It Works</h3>
                    <p>
                      `Reload UI` refreshes the currently installed desktop build and clears cached renderer files.
                    </p>
                    <p>
                      `Restart Backend` stops and starts the bundled Spring Boot service, then refreshes the app.
                    </p>
                    <p>
                      New source-code changes still need a fresh desktop build before they can appear in the installed app.
                    </p>
                  </div>
                </>
              )}
            </div>
          </div>
        );
      case 'onboarding':
      default:
        return (
          <div className="section-container">
            <div className="section-header blue">
              <div className="section-header-content">
                <div className="section-title-group">
                  <Settings size={24} />
                  <div>
                    <h2>{activeSection.replace('-', ' ').replace(/\b\w/g, l => l.toUpperCase())}</h2>
                    <p>This section is under development</p>
                  </div>
                </div>
              </div>
            </div>
            <div className="section-content">
              <div className="empty-state">
                <div className="empty-icon">
                  <Settings size={48} />
                </div>
                <h3>Coming Soon</h3>
                <p>This feature is currently being developed and will be available soon.</p>
              </div>
            </div>
          </div>
        );
    }
  };

  return (
    <div className="profile-settings-page">
      <ProfileSidebar
        activeSection={activeSection}
        setActiveSection={setActiveSection}
        userData={userData}
      />

      <div className="profile-content">
        <div className="profile-page-header">
          <h1>
            <Settings size={28} />
            Profile Settings
          </h1>
          <p>Manage your store settings and preferences</p>
        </div>

        {renderContent()}
      </div>

      <StoreProfileModal
        isOpen={isStoreProfileModalOpen}
        onClose={() => setIsStoreProfileModalOpen(false)}
        storeData={storeData}
        onSave={handleSaveStoreProfile}
      />

      <EditProfileModal
        isOpen={isEditModalOpen}
        onClose={() => setIsEditModalOpen(false)}
        initialData={fullProfileData}
        onSave={handleSaveProfile}
      />
    </div>
  );
};

export default Profile;
