import React from "react";
import { useNavigate } from "react-router-dom";
import { ArrowLeft, Shield, Lock, Eye, Database } from "lucide-react";
import "bootstrap/dist/css/bootstrap.min.css";
import "./PolicyPages.css";

const PrivacyPolicy = () => {
  const navigate = useNavigate();

  return (
    <div className="pp-root">

      {/* ── Header ── */}
      <div className="bg-white border-bottom shadow-sm">
        <div className="pp-container py-4">
          <button
            onClick={() => navigate("/")}
            className="pp-back-btn d-flex align-items-center gap-2 mb-3"
          >
            <ArrowLeft size={18} /> Back to Home
          </button>
          <div className="d-flex align-items-center gap-3">
            <div className="pp-icon-box pp-icon-indigo d-flex align-items-center justify-content-center rounded-3">
              <Shield size={30} />
            </div>
            <div>
              <h1 className="pp-title mb-0">Privacy Policy</h1>
              <p className="text-muted small mb-0 mt-1">Last updated: January 1, 2024</p>
            </div>
          </div>
        </div>
      </div>

      {/* ── Content ── */}
      <div className="pp-container py-5">
        <div className="pp-card bg-white rounded-4 shadow-sm p-4 p-md-5">

          {/* Trust badges */}
          <div className="row g-3 mb-5">
            <div className="col-md-4">
              <div className="pp-badge-card pp-badge-indigo d-flex align-items-center gap-3 rounded-3 p-3">
                <Lock size={22} />
                <span className="fw-semibold">Data Security</span>
              </div>
            </div>
            <div className="col-md-4">
              <div className="pp-badge-card pp-badge-purple d-flex align-items-center gap-3 rounded-3 p-3">
                <Eye size={22} />
                <span className="fw-semibold">Transparency</span>
              </div>
            </div>
            <div className="col-md-4">
              <div className="pp-badge-card pp-badge-blue d-flex align-items-center gap-3 rounded-3 p-3">
                <Database size={22} />
                <span className="fw-semibold">Your Rights</span>
              </div>
            </div>
          </div>

          {/* Section 1 */}
          <section className="pp-section">
            <h2 className="pp-section-title d-flex align-items-center gap-3">
              <span className="pp-num-badge">1</span>
              Information We Collect
            </h2>
            <p className="text-muted">
              We collect information you provide directly to us, such as when you create an account,
              make a purchase, or contact us for support. This may include:
            </p>
            <ul className="pp-list text-muted">
              <li>Name, email address, and contact information</li>
              <li>Business information for store registration</li>
              <li>Payment information for subscription services</li>
              <li>Usage data and analytics from our platform</li>
            </ul>
          </section>

          {/* Section 2 */}
          <section className="pp-section">
            <h2 className="pp-section-title d-flex align-items-center gap-3">
              <span className="pp-num-badge">2</span>
              How We Use Your Information
            </h2>
            <p className="text-muted">We use the information we collect to:</p>
            <ul className="pp-list text-muted">
              <li>Provide, maintain, and improve our services</li>
              <li>Process transactions and send related information</li>
              <li>Send technical notices and support messages</li>
              <li>Communicate with you about products, services, and promotions</li>
            </ul>
          </section>

          {/* Section 3 */}
          <section className="pp-section">
            <h2 className="pp-section-title d-flex align-items-center gap-3">
              <span className="pp-num-badge">3</span>
              Information Sharing
            </h2>
            <p className="text-muted">
              We do not sell, trade, or otherwise transfer your personal information to third parties
              without your consent, except as described in this policy.
            </p>
          </section>

          {/* Section 4 */}
          <section className="pp-section">
            <h2 className="pp-section-title d-flex align-items-center gap-3">
              <span className="pp-num-badge">4</span>
              Data Security
            </h2>
            <p className="text-muted">
              We implement appropriate security measures to protect your personal information against
              unauthorized access, alteration, disclosure, or destruction.
            </p>
          </section>

          {/* Section 5 */}
          <section className="pp-section mb-0">
            <h2 className="pp-section-title d-flex align-items-center gap-3">
              <span className="pp-num-badge">5</span>
              Contact Us
            </h2>
            <p className="text-muted">
              If you have questions about this Privacy Policy, please contact us at{" "}
              <a href="mailto:info@tsaritservices.com" className="pp-link">
                info@tsaritservices.com
              </a>{" "}
              or call{" "}
              <a href="tel:+919491301258" className="pp-link">
                +91 9491301258
              </a>.
            </p>
          </section>

        </div>
      </div>
    </div>
  );
};

export default PrivacyPolicy;
