import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import {
  User, Mail, Phone, Store, MapPin, CheckCircle,
  ChevronRight, ChevronLeft, Lock, Users, Loader2, ArrowLeft, Eye, EyeOff,
} from "lucide-react";
import toast, { Toaster } from "react-hot-toast";
import "bootstrap/dist/css/bootstrap.min.css";
import "./Register.css";

export default function Register() {
  const navigate = useNavigate();
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [formData, setFormData] = useState({
    full_name: "",
    email: "",
    phone: "",
    password: "",
    shop_name: "",
    shop_address: "",
    referred_by: "",
  });

  const handleChange = (e) =>
    setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleNext = () => {
    if (!formData.full_name || !formData.email || !formData.phone || !formData.password) {
      toast.error("Please fill out all personal details.");
      return;
    }
    setStep(2);
  };

  const handleSubmit = async () => {
    if (!formData.shop_name || !formData.shop_address) {
      toast.error("Please fill out all shop details.");
      return;
    }

    setLoading(true);
    try {
      const api = (await import("../utils/api")).default;
      const res = await api.post("/register", {
        fullName: formData.full_name,
        email: formData.email,
        phone: formData.phone,
        password: formData.password,
        shopName: formData.shop_name,
        shopAddress: formData.shop_address,
        referredBy: formData.referred_by || null,
      });

      const { token, user } = res.data;
      localStorage.removeItem("token");
      localStorage.removeItem("adminToken");
      localStorage.removeItem("user");
      localStorage.removeItem("admin");
      if (token) localStorage.setItem("token", token);
      if (user) localStorage.setItem("user", JSON.stringify(user));

      setSubmitted(true);
      toast.success("Registration successful! Welcome aboard");
      setTimeout(() => navigate("/dashboard"), 1500);
    } catch (err) {
      const msg = err?.response?.data?.error || err?.response?.data?.message || err?.message || "Registration failed";
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  const fillWidth = step === 1 ? "50%" : "100%";

  return (
    <div className="rg-root">
      <Toaster position="top-right" />

      <div className="rg-card">
        <button className="rg-back-btn" onClick={() => navigate("/")}>
          <ArrowLeft size={14} /> Back to Home
        </button>

        <h2 className="rg-title d-flex align-items-center justify-content-center gap-2 mb-0">
          <Store size={24} color="#16a34a" />
          SuperMarket Registration
        </h2>

        {!submitted && (
          <div className="rg-progress-wrap">
            <div className="rg-progress-track" />
            <div className="rg-progress-fill" style={{ width: fillWidth }} />
            <div className={`rg-step-circle ${step >= 1 ? "rg-step-active" : "rg-step-inactive"}`}>
              <User size={16} color="#fff" />
            </div>
            <div className={`rg-step-circle ${step === 2 ? "rg-step-active" : "rg-step-inactive"}`}>
              <Store size={16} color="#fff" />
            </div>
          </div>
        )}

        {step === 1 && !submitted && (
          <div className="rg-step d-flex flex-column gap-3">
            <div>
              <label className="rg-label"><User size={15} color="#16a34a" /> Full Name</label>
              <input name="full_name" value={formData.full_name} onChange={handleChange}
                placeholder="Enter full name" className="rg-input" />
            </div>
            <div>
              <label className="rg-label"><Mail size={15} color="#16a34a" /> Email</label>
              <input name="email" type="email" value={formData.email} onChange={handleChange}
                placeholder="Enter email" className="rg-input" />
            </div>
            <div>
              <label className="rg-label"><Phone size={15} color="#16a34a" /> Phone</label>
              <input name="phone" type="tel" value={formData.phone} onChange={handleChange}
                placeholder="Enter phone number" className="rg-input" />
            </div>
            <div>
              <label className="rg-label"><Lock size={15} color="#16a34a" /> Password</label>
              <div style={{ position: "relative", display: "flex", alignItems: "center" }}>
                <input
                  name="password"
                  type={showPassword ? "text" : "password"}
                  value={formData.password}
                  onChange={handleChange}
                  placeholder="Set a password"
                  className="rg-input"
                  autoComplete="new-password"
                  style={{ paddingRight: "40px" }}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  style={{
                    position: "absolute",
                    right: "12px",
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    padding: "4px",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    color: "#666"
                  }}
                  title={showPassword ? "Hide password" : "Show password"}
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>
            <div className="d-flex justify-content-end pt-2">
              <button className="rg-btn-primary" onClick={handleNext}>
                Next <ChevronRight size={16} />
              </button>
            </div>
          </div>
        )}

        {step === 2 && !submitted && (
          <div className="rg-step d-flex flex-column gap-3">
            <div>
              <label className="rg-label"><Store size={15} color="#16a34a" /> Shop Name</label>
              <input name="shop_name" value={formData.shop_name} onChange={handleChange}
                placeholder="Enter shop name" className="rg-input" />
            </div>
            <div>
              <label className="rg-label"><MapPin size={15} color="#16a34a" /> Shop Address</label>
              <textarea name="shop_address" value={formData.shop_address} onChange={handleChange}
                placeholder="Enter shop address" className="rg-input" />
            </div>
            <div>
              <label className="rg-label">
                <Users size={15} color="#16a34a" /> Referred By
                <span className="text-muted fw-normal ms-1">(Optional)</span>
              </label>
              <input name="referred_by" value={formData.referred_by} onChange={handleChange}
                placeholder="Referrer name or code (optional)" className="rg-input" />
            </div>

            <div className="d-flex justify-content-between pt-2">
              <button className="rg-btn-secondary" onClick={() => setStep(1)}>
                <ChevronLeft size={16} /> Back
              </button>
              <button
                className="rg-btn-primary"
                onClick={handleSubmit}
                disabled={loading}
              >
                {loading ? (
                  <><Loader2 size={15} className="rg-spin" /> Registering...</>
                ) : (
                  "Register"
                )}
              </button>
            </div>
          </div>
        )}

        {submitted && (
          <div className="rg-success">
            <CheckCircle size={64} color="#16a34a" className="rg-bounce mb-3" />
            <h5 className="fw-bold text-dark">Registration Successful!</h5>
            <p className="text-muted mb-0">Welcome, <strong>{formData.full_name}</strong></p>
            <p className="text-muted small">
              Your supermarket <strong>{formData.shop_name}</strong> is now registered.
            </p>
            <p className="text-muted small mt-2">Redirecting to your dashboard...</p>
          </div>
        )}

        {!submitted && (
          <p className="rg-login-link mt-3 mb-0">
            Already have an account? <Link to="/login">Sign in here</Link>
          </p>
        )}
      </div>
    </div>
  );
}
