import axios from 'axios';

const API_URL = '/api';
export const BACKEND_STATUS_EVENT = 'smms:backend-status';

// ── Mobile (Capacitor) server URL support ──────────────────────────
// On desktop, the frontend is served BY the Spring Boot backend itself,
// so relative "/api" calls work automatically. On a mobile app built
// with Capacitor, the app runs from its own origin (capacitor://localhost)
// and has no built-in backend, so it must know where the backend is.
//
// Set this to your deployed backend's URL once you have it (e.g. the
// URL Render gives you, such as "https://smms-backend.onrender.com").
// Leaving it blank falls back to asking the person for a local PC IP
// on first launch — useful for WiFi-only testing before you deploy.
const DEFAULT_CLOUD_SERVER_URL = ''; // e.g. 'https://smms-backend.onrender.com'

const SERVER_URL_KEY = 'smms_server_url';

export const isNativeApp = () =>
    typeof window !== 'undefined' && Boolean(window.Capacitor?.isNativePlatform?.());

export const getServerUrl = () => {
    if (typeof window === 'undefined') return null;
    return window.localStorage.getItem(SERVER_URL_KEY);
};

// Saves the backend address and applies it immediately so subsequent
// requests use it without a reload. Accepts a bare IP ("192.168.1.5"),
// an IP with port ("192.168.1.5:9090"), or a full URL
// ("https://smms-backend.onrender.com"). A bare host with no scheme and
// no port is assumed to be a LAN PC and gets ":8080" appended, matching
// the desktop backend's port — a host with its own scheme (https://...)
// is left exactly as typed, since cloud hosts use standard 443/80.
export const setServerUrl = (url) => {
    if (typeof window === 'undefined' || !url) return;
    let clean = url.trim().replace(/\/+$/, '');

    if (!/^https?:\/\//i.test(clean)) {
        if (!/:\d+$/.test(clean)) {
            clean = `${clean}:8080`;
        }
        clean = `http://${clean}`;
    }

    window.localStorage.setItem(SERVER_URL_KEY, clean);
    api.defaults.baseURL = `${clean}/api`;
};

export const clearServerUrl = () => {
    if (typeof window === 'undefined') return;
    window.localStorage.removeItem(SERVER_URL_KEY);
};

// For the Settings screen input — shows just the host[:port] the person
// typed, without the http:// scheme we add internally.
export const getServerHost = () => {
    const saved = getServerUrl();
    if (!saved) return '';
    return saved.replace(/^https?:\/\//i, '');
};

const resolveApiBaseUrl = () => {
    if (isNativeApp()) {
        const saved = getServerUrl();
        if (saved) return `${saved}/api`;
        if (DEFAULT_CLOUD_SERVER_URL) return `${DEFAULT_CLOUD_SERVER_URL}/api`;
        // No server configured yet. Fall back to the Android emulator's
        // host-loopback address so local testing works out of the box;
        // on a real phone this simply fails the health check and
        // BackendStatusGate guides the person to Profile > Server
        // Connection to enter their PC's address.
        return 'http://10.0.2.2:8080/api';
    }
    return API_URL;
};

export const hasDefaultCloudServer = () => Boolean(DEFAULT_CLOUD_SERVER_URL);

let lastBackendOnlineState = null;

const emitBackendStatus = (online, reason = '') => {
    if (typeof window === 'undefined') {
        return;
    }

    if (lastBackendOnlineState === online && !reason) {
        return;
    }

    lastBackendOnlineState = online;
    window.dispatchEvent(new CustomEvent(BACKEND_STATUS_EVENT, {
        detail: {
            online,
            reason,
            timestamp: Date.now()
        }
    }));
};

export const markBackendHealthy = () => emitBackendStatus(true);
export const markBackendUnavailable = (reason = 'unreachable') => emitBackendStatus(false, reason);

export const isBackendUnavailableError = (error) => {
    if (!error) {
        return false;
    }

    if (error.response) {
        return false;
    }

    return Boolean(
        error.code === 'ECONNABORTED' ||
        error.message?.includes('Network Error') ||
        error.message?.toLowerCase().includes('timeout') ||
        error.request
    );
};

export const checkBackendHealth = async () => {
    try {
        await api.get('/health', {
            timeout: 5000,
            headers: {
                'Cache-Control': 'no-cache'
            }
        });
        markBackendHealthy();
        return true;
    } catch (error) {
        if (isBackendUnavailableError(error)) {
            markBackendUnavailable(error.code || error.message || 'health-check-failed');
        }
        return false;
    }
};

const redirectToLogin = () => {
    if (typeof window === 'undefined') {
        return;
    }

    const loginPath = '/login';
    if (window.location.pathname === loginPath) {
        return;
    }

    const baseUrl = `${window.location.origin}${loginPath}`;
    window.location.replace(baseUrl);
};

const api = axios.create({
    baseURL: resolveApiBaseUrl(),
    headers: {
        'Content-Type': 'application/json',
    },
    timeout: 30000, // 30 second timeout
});

const withParams = (config = {}, params = {}) => ({
    ...config,
    params: {
        ...(config.params || {}),
        ...params,
    },
});

// Add a request interceptor to attach token
api.interceptors.request.use(
    (config) => {
        // Check both 'token' (user login) and 'adminToken' (admin login)
        const token = localStorage.getItem('token') || localStorage.getItem('adminToken');
        if (token) {
            config.headers.Authorization = `Bearer ${token}`;
        }
        return config;
    },
    (error) => {
        return Promise.reject(error);
    }
);

// Add a response interceptor for 401 error handling
api.interceptors.response.use(
    (response) => {
        markBackendHealthy();
        return response;
    },
    (error) => {
        if (error.response) {
            markBackendHealthy();
        } else if (isBackendUnavailableError(error)) {
            markBackendUnavailable(error.code || error.message || 'request-failed');
        }

        if (error.response && error.response.status === 401) {
            // Token expired or invalid - clear storage and redirect to login
            localStorage.removeItem('token');
            localStorage.removeItem('adminToken');
            localStorage.removeItem('user');
            redirectToLogin();
        }
        return Promise.reject(error);
    }
);

export const productService = {
    getAll: (config = {}) => api.get('/products', config),
    search: (query, limit = 8, config = {}) => api.get('/products/search', withParams(config, { q: query, limit })),
    initializeDefaults: (config = {}) => api.post('/products/initialize-defaults', undefined, config),
    getById: (id, config = {}) => api.get(`/products/${id}`, config),
    getByCode: (code, config = {}) => api.get(`/products/code/${code}`, config),
    create: (data, config = {}) => api.post('/products', data, config),
    createBulk: (data, config = {}) => api.post('/products/bulk', data, config),
    update: (id, data, config = {}) => api.put(`/products/${id}`, data, config),
    delete: (id, config = {}) => api.delete(`/products/${id}`, config),
};

export const saleService = {
    getAll: (config = {}) => api.get('/sales', config),
    create: (data, config = {}) => api.post('/sales', data, config),
    getDailySales: (config = {}) => api.get('/sales/daily', config),
    getNextTransactionId: (config = {}) => api.get('/sales/next-transaction-id', config),
};

export const dashboardService = {
    getStats: () => api.get('/dashboard/stats'),
};

export const profileService = {
    getProfile: (config = {}) => api.get('/profile', config),
    updateProfile: (data, config = {}) => api.put('/profile', data, config),
    uploadFile: (file) => {
        const formData = new FormData();
        formData.append('file', file);
        return api.post('/profile/upload', formData, {
            headers: { 'Content-Type': 'multipart/form-data' }
        });
    }
};

export default api;
