// Bluetooth receipt printing (mobile only) — matches the reference
// billing app's Bluetooth thermal-printer support. Uses
// capacitor-thermal-printer, which talks directly to ESC/POS thermal
// printers over classic Bluetooth; this is separate from (and doesn't
// replace) the existing browser print() flow used on desktop, since a
// phone's WebView has no OS print dialog a thermal printer would show
// up in anyway.
//
// All calls are safe to make even when the plugin isn't installed yet
// or the app isn't running natively — they just resolve to a "not
// available" result, so the rest of the app doesn't need to guard
// every call with isNativeApp() checks.

import { isNativeApp } from './api';

const SAVED_PRINTER_KEY = 'smms_bt_printer_address';
const SAVED_PRINTER_NAME_KEY = 'smms_bt_printer_name';

let pluginPromise = null;

// Lazily imported so desktop/web builds never need this dependency
// resolved, and so a missing/failed native plugin doesn't break startup.
const getPlugin = async () => {
    if (!isNativeApp()) return null;
    if (!pluginPromise) {
        pluginPromise = import('capacitor-thermal-printer')
            .then((mod) => mod.CapacitorThermalPrinter)
            .catch((error) => {
                console.error('capacitor-thermal-printer not available:', error);
                return null;
            });
    }
    return pluginPromise;
};

export const isBluetoothPrintingSupported = () => isNativeApp();

export const getSavedPrinter = () => {
    if (typeof window === 'undefined') return null;
    const address = window.localStorage.getItem(SAVED_PRINTER_KEY);
    if (!address) return null;
    return { address, name: window.localStorage.getItem(SAVED_PRINTER_NAME_KEY) || address };
};

const saveSelectedPrinter = (device) => {
    if (typeof window === 'undefined' || !device) return;
    window.localStorage.setItem(SAVED_PRINTER_KEY, device.address);
    window.localStorage.setItem(SAVED_PRINTER_NAME_KEY, device.name || device.address);
};

export const clearSavedPrinter = () => {
    if (typeof window === 'undefined') return;
    window.localStorage.removeItem(SAVED_PRINTER_KEY);
    window.localStorage.removeItem(SAVED_PRINTER_NAME_KEY);
};

export const isPrinterConnected = async () => {
    const plugin = await getPlugin();
    if (!plugin) return false;
    try {
        return await plugin.isConnected();
    } catch {
        return false;
    }
};

// Scans for nearby printers for `durationMs`, then resolves with the
// list found. onDevice(device) is called as each one is discovered, so
// the UI can show them appearing live rather than waiting for the whole
// scan to finish.
export const scanForPrinters = async (onDevice, durationMs = 6000) => {
    const plugin = await getPlugin();
    if (!plugin) return [];

    const found = [];
    const listener = await plugin.addListener('discoverDevices', (data) => {
        (data?.devices || []).forEach((device) => {
            if (!found.some((d) => d.address === device.address)) {
                found.push(device);
                onDevice?.(device);
            }
        });
    });

    try {
        await plugin.startScan();
        await new Promise((resolve) => setTimeout(resolve, durationMs));
        await plugin.stopScan();
    } finally {
        listener.remove();
    }

    return found;
};

export const connectToPrinter = async (device) => {
    const plugin = await getPlugin();
    if (!plugin) throw new Error('Bluetooth printing is only available in the mobile app.');

    const connected = await plugin.connect({ address: device.address });
    if (!connected) {
        throw new Error(`Could not connect to ${device.name || device.address}.`);
    }
    saveSelectedPrinter(connected);
    return connected;
};

export const disconnectPrinter = async () => {
    const plugin = await getPlugin();
    if (!plugin) return;
    try {
        await plugin.disconnect();
    } catch (error) {
        console.error('Failed to disconnect printer:', error);
    }
};

const formatCurrency = (value) => `Rs.${Number(value || 0).toFixed(2)}`;

// Renders a sale receipt as ESC/POS commands and sends it to the
// currently connected printer. Deliberately plain-text/formatting only
// (no HTML) — thermal printers render this directly, far more reliably
// than trying to rasterize the existing HTML receipt into an image.
export const printSaleReceipt = async (saleData, storeProfile = {}) => {
    const plugin = await getPlugin();
    if (!plugin) throw new Error('Bluetooth printing is only available in the mobile app.');

    const connected = await plugin.isConnected();
    if (!connected) throw new Error('No Bluetooth printer connected. Pair one from Profile > Bluetooth Printer.');

    let builder = plugin.begin()
        .align('center')
        .bold(true)
        .text(`${storeProfile?.storeName || 'SMMS Store'}\n`)
        .bold(false)
        .clearFormatting();

    if (storeProfile?.address) {
        builder = builder.align('center').text(`${storeProfile.address}\n`);
    }
    if (storeProfile?.phone) {
        builder = builder.text(`Ph: ${storeProfile.phone}\n`);
    }

    builder = builder
        .text('--------------------------------\n')
        .align('left')
        .text(`Bill No: ${saleData.transactionId}\n`)
        .text(`Date: ${new Date(saleData.date).toLocaleString('en-IN')}\n`);

    if (saleData.customerName && saleData.customerName !== 'Walk-in Customer') {
        builder = builder.text(`Customer: ${saleData.customerName}\n`);
    }

    builder = builder.text('--------------------------------\n');

    (saleData.items || []).forEach((item) => {
        const lineTotal = formatCurrency(item.subtotal);
        builder = builder
            .text(`${item.itemName}\n`)
            .text(`  ${item.quantity} x ${formatCurrency(item.unitPrice)}`.padEnd(24) + lineTotal + '\n');
    });

    builder = builder
        .text('--------------------------------\n')
        .align('right')
        .text(`Subtotal: ${formatCurrency(saleData.subtotal)}\n`);

    if (saleData.discount > 0) {
        builder = builder.text(`Discount: -${formatCurrency(saleData.discount)}\n`);
    }
    if (saleData.tax > 0) {
        builder = builder.text(`Tax: ${formatCurrency(saleData.tax)}\n`);
    }

    builder = builder
        .bold(true)
        .text(`Total: ${formatCurrency(saleData.grandTotal)}\n`)
        .bold(false)
        .text(`Paid via: ${saleData.paymentMethod || 'CASH'}\n`);

    if (saleData.paymentMethod === 'CASH') {
        builder = builder
            .text(`Cash: ${formatCurrency(saleData.cashTendered)}\n`)
            .text(`Change: ${formatCurrency(saleData.changeAmount)}\n`);
    }

    builder = builder
        .align('center')
        .clearFormatting()
        .text('\nThank you for shopping with us!\n')
        .feedCutPaper();

    await builder.write();
};
