import React, { useState } from 'react';
import { ArrowLeft, MessageSquare, CheckCircle, RefreshCcw, Clock, Plus, X, Upload, Send } from 'lucide-react';
import './SupportCenter.css';

const SupportCenter = ({ onBack }) => {
  const [tickets, setTickets] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  
  const [newTicket, setNewTicket] = useState({
    subject: '',
    description: '',
    priority: 'Medium',
    category: 'General',
    attachment: null
  });

  const stats = {
    total: tickets.length,
    resolved: tickets.filter(t => t.status === 'Resolved').length,
    inProgress: tickets.filter(t => t.status === 'In Progress').length,
    open: tickets.filter(t => t.status === 'Open').length
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewTicket(prev => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e) => {
    setNewTicket(prev => ({ ...prev, attachment: e.target.files[0] }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!newTicket.subject || !newTicket.description) return;

    const ticket = {
        id: Date.now(),
        subject: newTicket.subject,
        description: newTicket.description,
        priority: newTicket.priority,
        category: newTicket.category,
        status: 'Open',
        date: new Date().toLocaleDateString(),
        time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };

    setTickets([ticket, ...tickets]);
    setIsModalOpen(false);
    setNewTicket({
        subject: '',
        description: '',
        priority: 'Medium',
        category: 'General',
        aiQuery: '',
        attachment: null
    });
  };

  return (
    <div className="support-center fade-in">
      {/* Modal Overlay */}
      {isModalOpen && (
        <div className="ticket-modal-overlay">
            <div className="ticket-modal fade-in-up">
                <div className="ticket-modal-header">
                    <h2><Plus size={20} /> Create Support Ticket</h2>
                    <button className="close-btn" onClick={() => setIsModalOpen(false)}>
                        <X size={24} />
                    </button>
                </div>
                
                <div className="ticket-modal-body">
                    <form onSubmit={handleSubmit}>
                        <div className="form-group">
                            <label>Subject *</label>
                            <input 
                                type="text" 
                                name="subject"
                                value={newTicket.subject}
                                onChange={handleInputChange}
                                placeholder="Brief description of your issue" 
                                required
                            />
                        </div>

                        <div className="form-group">
                            <label>Description *</label>
                            <textarea 
                                name="description"
                                value={newTicket.description}
                                onChange={handleInputChange}
                                placeholder="Please provide detailed information about your issue..." 
                                rows="5"
                                required
                            ></textarea>
                        </div>

                        <div className="form-row">
                            <div className="form-group">
                                <label>Priority</label>
                                <select name="priority" value={newTicket.priority} onChange={handleInputChange}>
                                    <option value="Low">Low</option>
                                    <option value="Medium">Medium</option>
                                    <option value="High">High</option>
                                    <option value="Urgent">Urgent</option>
                                </select>
                            </div>
                            <div className="form-group">
                                <label>Category</label>
                                <select name="category" value={newTicket.category} onChange={handleInputChange}>
                                    <option value="General">General</option>
                                    <option value="Technical">Technical</option>
                                    <option value="Billing">Billing</option>
                                    <option value="Feature Request">Feature Request</option>
                                </select>
                            </div>
                        </div>

                        <div className="form-group">
                            <label>Attachments (optional)</label>
                            <div className="file-upload-wrapper">
                                <label htmlFor="file-upload" className="file-upload-label">
                                    <Upload size={16} />
                                    {newTicket.attachment ? newTicket.attachment.name : 'Choose Files'}
                                </label>
                                <input id="file-upload" type="file" onChange={handleFileChange} hidden />
                                {!newTicket.attachment && <span className="file-name">No file chosen</span>}
                            </div>
                        </div>
                        
                        <div className="ticket-modal-footer">
                            <button type="button" className="ticket-cancel-btn" onClick={() => setIsModalOpen(false)}>Cancel</button>
                            <button type="submit" className="ticket-create-btn">
                                <Send size={16} /> Create Ticket
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </div>
      )}

      <button className="back-btn" onClick={onBack}>
        <ArrowLeft size={18} />
        Back to Profile
      </button>

      <div className="support-header">
        <div className="header-content">
            <h1>Support Center</h1>
            <p>Get help and support for your supermarket operations</p>
        </div>
        <button className="create-ticket-btn" onClick={() => setIsModalOpen(true)}>
            <Plus size={18} /> Create New Ticket
        </button>
      </div>

      <div className="stats-grid">
        <div className="stat-card blue">
            <div className="stat-header">
                <div className="icon-wrapper">
                    <MessageSquare size={20} />
                </div>
            </div>
            <div>
                <h3 className="stat-value">{stats.total}</h3>
                <p className="stat-label">Total Tickets</p>
            </div>
        </div>
        <div className="stat-card green">
            <div className="stat-header">
                <div className="icon-wrapper">
                    <CheckCircle size={20} />
                </div>
            </div>
            <div>
                <h3 className="stat-value">{stats.resolved}</h3>
                <p className="stat-label">Resolved</p>
            </div>
        </div>
        <div className="stat-card orange">
            <div className="stat-header">
                <div className="icon-wrapper">
                    <RefreshCcw size={20} />
                </div>
            </div>
            <div>
                <h3 className="stat-value">{stats.inProgress}</h3>
                <p className="stat-label">In Progress</p>
            </div>
        </div>
        <div className="stat-card purple">
             <div className="stat-header">
                <div className="icon-wrapper">
                    <Clock size={20} />
                </div>
            </div>
            <div>
                <h3 className="stat-value">{stats.open}</h3>
                <p className="stat-label">Open</p>
            </div>
        </div>
      </div>



      <div className="tickets-section">
        <h2>Your Support Tickets</h2>
        <div className="tickets-container">
            {tickets.length === 0 ? (
                <div className="empty-state">
                    <MessageSquare size={48} />
                    <h3>No support tickets yet</h3>
                    <p>Create a new ticket if you need assistance with anything.</p>
                </div>
            ) : (
                <div className="tickets-list">
                    {tickets.map(ticket => (
                        <div key={ticket.id} className="ticket-item">
                            <div className="ticket-main">
                                <div className="ticket-subject-row">
                                    <span className="ticket-subject">{ticket.subject}</span>
                                    <span className={`status-badge ${ticket.status.toLowerCase().replace(' ', '-')}`}>
                                        {ticket.status}
                                    </span>
                                </div>
                                <p className="ticket-desc">{ticket.description}</p>
                                <div className="ticket-meta">
                                    <span className="meta-item">#{ticket.id}</span>
                                    <span className="meta-item">{ticket.date} • {ticket.time}</span>
                                    <span className="meta-item">{ticket.category}</span>
                                    <span className="meta-item">Priority: {ticket.priority}</span>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

export default SupportCenter;
