import React, { useState, useRef, useEffect } from 'react';
import { X, Upload, Save, Store, Loader2 } from 'lucide-react';
import { profileService } from '../../services/api';
import './StoreProfileModal.css';

const StoreProfileModal = ({ isOpen, onClose, storeData, onSave }) => {
  const [formData, setFormData] = useState({
    logo: storeData?.logo || null,
    shopName: storeData?.name || '',
    shopType: storeData?.category || 'Supermarket',
    tagline: storeData?.tagline || '',
    establishedYear: storeData?.since || '',
    storeArea: storeData?.area?.replace(' sq ft', '') || '',
    address: storeData?.address || '',
    categories: storeData?.categories?.join(', ') || '',
    facebook: storeData?.facebook || '',
    instagram: storeData?.instagram || '',
  });
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (isOpen && storeData) {
      setFormData({
        logo: storeData.logo || null,
        shopName: storeData.name || '',
        shopType: storeData.category || 'Supermarket',
        tagline: storeData.tagline || '',
        establishedYear: storeData.since || '',
        storeArea: storeData.area?.replace(' sq ft', '') || '',
        address: storeData.address || '',
        categories: storeData.categories?.join(', ') || '',
        facebook: storeData.facebook || '',
        instagram: storeData.instagram || '',
      });
    }
  }, [isOpen, storeData]);

  const fileInputRef = useRef(null);

  const handleLogoChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    
    const reader = new FileReader();
    reader.onload = (ev) => {
      setFormData(prev => ({ ...prev, logo: ev.target.result }));
    };
    reader.readAsDataURL(file);
  };

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    
    try {
      const profileUpdate = {
        storeName: formData.shopName,
        storeType: formData.shopType,
        description: formData.tagline,
        address: formData.address,
        facebookUrl: formData.facebook,
        instagramUrl: formData.instagram,
      };

      await profileService.updateProfile(profileUpdate);

      onSave({
        ...storeData,
        name: formData.shopName,
        category: formData.shopType,
        tagline: formData.tagline,
        since: formData.establishedYear,
        area: formData.storeArea ? `${formData.storeArea} sq ft` : '',
        address: formData.address,
        categories: formData.categories.split(',').map(c => c.trim()).filter(Boolean),
        logo: formData.logo,
        facebook: formData.facebook,
        instagram: formData.instagram,
      });
      
      onClose();
    } catch (error) {
      console.error('Failed to save store profile:', error);
      alert('Failed to save store profile. Please try again.');
    } finally {
      setSaving(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="spm-overlay">
      <div className="spm-modal">
        <div className="spm-header">
          <h2>
            <Store size={20} />
            Edit Store Profile
          </h2>
          <button className="spm-close-btn" onClick={onClose}>
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="spm-body">
          {/* Store Logo */}
          <div className="spm-section">
            <h3 className="spm-section-title">
              <Upload size={16} />
              STORE LOGO
            </h3>
            <div className="spm-logo-area">
              <div className="spm-logo-preview">
                {formData.logo ? (
                  <img src={formData.logo} alt="Store Logo" />
                ) : (
                  <span>Logo</span>
                )}
              </div>
              <div className="spm-logo-info">
                <button 
                  type="button" 
                  className="spm-choose-btn"
                  onClick={() => fileInputRef.current?.click()}
                >
                  Choose File
                </button>
                <span className="spm-file-status">
                  {formData.logo ? 'File selected' : 'No file chosen'}
                </span>
              </div>
              <p className="spm-logo-hint">JPG, PNG or GIF. Max 10MB. This logo will appear on bills.</p>
              <input
                ref={fileInputRef}
                type="file"
                accept="image/*"
                onChange={handleLogoChange}
                style={{ display: 'none' }}
              />
            </div>
          </div>

          {/* Basic Information */}
          <div className="spm-section">
            <h3 className="spm-section-title">
              <Store size={16} />
              BASIC INFORMATION
            </h3>
            <div className="spm-grid">
              <div className="spm-field">
                <label>Shop Name</label>
                <input
                  type="text"
                  value={formData.shopName}
                  onChange={(e) => handleChange('shopName', e.target.value)}
                  placeholder="Enter shop name"
                />
              </div>
              <div className="spm-field">
                <label>Shop Type</label>
                <select
                  value={formData.shopType}
                  onChange={(e) => handleChange('shopType', e.target.value)}
                >
                  <option value="Supermarket">Supermarket</option>
                  <option value="Grocery">Grocery</option>
                  <option value="General Store">General Store</option>
                  <option value="Convenience Store">Convenience Store</option>
                  <option value="Departmental Store">Departmental Store</option>
                </select>
              </div>
            </div>
            <div className="spm-field">
              <label>Tagline</label>
              <input
                type="text"
                value={formData.tagline}
                onChange={(e) => handleChange('tagline', e.target.value)}
                placeholder="Your Daily Needs, Delivered Fresh"
              />
            </div>
            <div className="spm-field">
              <label>Address</label>
              <textarea
                value={formData.address}
                onChange={(e) => handleChange('address', e.target.value)}
                placeholder="Enter store full address"
                rows="3"
                style={{
                  width: '100%',
                  padding: '10px 12px',
                  border: '1px solid #e2e8f0',
                  borderRadius: '6px',
                  fontSize: '0.9rem',
                  resize: 'vertical',
                  fontFamily: 'inherit'
                }}
              />
            </div>
            <div className="spm-grid">
              <div className="spm-field">
                <label>Established Year</label>
                <input
                  type="text"
                  value={formData.establishedYear}
                  onChange={(e) => handleChange('establishedYear', e.target.value)}
                  placeholder="e.g., 2018"
                />
              </div>
              <div className="spm-field">
                <label>Store Area (sq.ft)</label>
                <input
                  type="text"
                  value={formData.storeArea}
                  onChange={(e) => handleChange('storeArea', e.target.value)}
                  placeholder="e.g., 2500"
                />
              </div>
            </div>
          </div>

          {/* Product Categories */}
          <div className="spm-section">
            <h3 className="spm-section-title">
              <Store size={16} />
              PRODUCT CATEGORIES
            </h3>
            <div className="spm-field">
              <label>Categories (comma separated)</label>
              <input
                type="text"
                value={formData.categories}
                onChange={(e) => handleChange('categories', e.target.value)}
                placeholder="Groceries, Fresh Produce, Dairy, Beverages"
              />
              <span className="spm-hint">Separate categories with commas</span>
            </div>
          </div>

          {/* Social Links */}
          <div className="spm-section">
            <h3 className="spm-section-title">
              <Store size={16} />
              SOCIAL LINKS
            </h3>
            <div className="spm-grid">
              <div className="spm-field">
                <label>Facebook</label>
                <input
                  type="text"
                  value={formData.facebook}
                  onChange={(e) => handleChange('facebook', e.target.value)}
                  placeholder="Facebook URL"
                />
              </div>
              <div className="spm-field">
                <label>Instagram</label>
                <input
                  type="text"
                  value={formData.instagram}
                  onChange={(e) => handleChange('instagram', e.target.value)}
                  placeholder="Instagram URL"
                />
              </div>
            </div>
          </div>

          {/* Actions */}
          <div className="spm-actions">
            <button type="button" className="spm-cancel-btn" onClick={onClose} disabled={saving}>
              Cancel
            </button>
            <button type="submit" className="spm-save-btn" disabled={saving}>
              {saving ? (
                <>
                  <Loader2 size={16} className="spinning" />
                  Saving...
                </>
              ) : (
                <>
                  <Save size={16} />
                  Save Changes
                </>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default StoreProfileModal;
