import { useState, useEffect, useRef } from 'react';
import { Search, Upload, Plus, Edit, Trash2, Eye, Loader2, Keyboard } from 'lucide-react';
import AddProductModal from '../components/inventory/AddProductModal';
import ViewProductModal from '../components/inventory/ViewProductModal';
import EditProductModal from '../components/inventory/EditProductModal';
import BulkAddModal from '../components/inventory/BulkAddModal';
import { productService } from '../services/api'; // Import API service
import './Inventory.css';

const Inventory = () => {
  const optionalText = (value) => {
    const normalized = (value ?? '').toString().trim();
    return normalized === '' ? null : normalized;
  };

  const optionalNumber = (value) => {
    if (value === null || value === undefined || value === '') return null;
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  };

  const [searchQuery, setSearchQuery] = useState('');
  const [filterCategory, setFilterCategory] = useState('All');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isBulkModalOpen, setIsBulkModalOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [products, setProducts] = useState([]); // Initialize empty array
  const [isLoading, setIsLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('DEFAULT'); // 'DEFAULT' or 'REGULAR'
  const searchInputRef = useRef(null);

  // Keyboard Shortcuts
  useEffect(() => {
    const handleKeyDown = (e) => {
      // Check if Alt key is pressed (and not just the Alt key itself)
      if (e.altKey && e.key) {
        switch (e.key.toLowerCase()) {
          case 'n':
            e.preventDefault();
            handleAddProduct();
            break;
          case 'b':
            e.preventDefault();
            handleBulkUpload();
            break;
          case 's':
            e.preventDefault();
            searchInputRef.current?.focus();
            break;
          case 't':
            e.preventDefault();
            setActiveTab(prev => (prev === 'DEFAULT' ? 'REGULAR' : 'DEFAULT'));
            break;
          default:
            break;
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [products]); // Re-bind on products change if necessary

  // Fetch products on mount
  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    setIsLoading(true);
    try {
      const response = await productService.getAll();
      setProducts(response.data);
    } catch (error) {
      console.error('Error fetching products:', error);
      // Show more detailed error message
      let errorMessage = 'Failed to fetch products. ';
      if (error.response) {
        // Server responded with error status
        errorMessage += `Server error: ${error.response.status} - ${error.response.data?.message || error.response.statusText}`;
      } else if (error.request) {
        // Request made but no response received
        errorMessage += 'No response from server. Is the backend server running?';
      } else {
        // Error in setting up request
        errorMessage += error.message;
      }
      alert(errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleBulkUpload = () => {
    setIsBulkModalOpen(true);
  };

  const handleBulkSubmit = async (productsData) => {
    try {
        const response = await productService.createBulk(productsData);
        if (Array.isArray(response.data)) {
            setProducts([...products, ...response.data]);
            alert(`✅ Successfully added ${response.data.length} products!`);
        } else {
            // Re-fetch to be sure
            fetchProducts();
            alert('✅ Products added successfully!');
        }
    } catch (error) {
        console.error('Error adding bulk products:', error);
        let errorMsg = 'Failed to add bulk products';
        
        // Handle different error response formats
        if (error.response?.data) {
            if (typeof error.response.data === 'string') {
                errorMsg = error.response.data;
            } else if (error.response.data.message) {
                errorMsg = error.response.data.message;
            } else if (error.response.data.error) {
                errorMsg = error.response.data.error;
            }
        } else if (error.message) {
            errorMsg = error.message;
        }
        
        alert(`❌ ${errorMsg}`);
    }
  };

  const handleAddProduct = () => {
    setIsAddModalOpen(true);
  };

  const handleProductSubmit = async (productData) => {
    try {
      const newProduct = {
        itemName: optionalText(productData.itemName),
        itemCode: optionalText(productData.itemCode),
        category: optionalText(productData.category),
        subcategory: productData.subcategory || '-',
        mrp: parseFloat(productData.mrp),
        saleRate: parseFloat(productData.saleRate),
        quantity: optionalNumber(productData.bulkQuantity),
        expiryDate: optionalText(productData.expiryDate)
      };

      const response = await productService.create(newProduct);
      setProducts([...products, response.data]);
      console.log('Product added:', response.data);
      alert('Product added successfully!');
      setActiveTab('REGULAR'); // Switch to regular tab after adding
    } catch (error) {
      console.error('Error adding product:', error);
      const errorMessage = error.response?.data?.message || 'Failed to add product. Please check all fields are filled correctly.';
      alert(errorMessage);
    }
  };

  const handleView = (productId) => {
    const product = products.find(p => p.id === productId);
    setSelectedProduct(product);
    setIsViewModalOpen(true);
  };

  const handleEdit = (productId) => {
    const product = products.find(p => p.id === productId);
    setSelectedProduct(product);
    setIsEditModalOpen(true);
  };

  const handleProductUpdate = async (updatedData) => {
    try {
      const productToUpdate = {
        itemName: optionalText(updatedData.itemName),
        itemCode: optionalText(updatedData.itemCode),
        category: optionalText(updatedData.category),
        subcategory: updatedData.subcategory || '-',
        mrp: parseFloat(updatedData.mrp),
        saleRate: parseFloat(updatedData.saleRate),
        quantity: optionalNumber(updatedData.bulkQuantity),
        expiryDate: optionalText(updatedData.expiryDate)
      };

      const response = await productService.update(updatedData.id, productToUpdate);
      
      setProducts(products.map(product =>
        product.id === updatedData.id ? response.data : product
      ));
      console.log('Product updated:', response.data);
      alert('Product updated successfully!');
    } catch (error) {
      console.error('Error updating product:', error);
      const errorMessage = error.response?.data?.message || 'Failed to update product. Please check all fields are filled correctly.';
      alert(errorMessage);
    }
  };

  const handleDelete = async (productId) => {
    if (window.confirm('Are you sure you want to delete this product?')) {
      try {
        await productService.delete(productId);
        setProducts(products.filter(product => product.id !== productId));
        console.log('Product deleted:', productId);
        alert('Product deleted successfully!');
      } catch (error) {
        console.error('Error deleting product:', error);
        alert('Failed to delete product.');
      }
    }
  };

  const filteredProducts = products.filter(product => {
    // Robust check for default status (backend might send 'default' or 'isDefault')
    const isDef = product.default === true || product.isDefault === true || product.default === 1 || product.isDefault === 1;
    const isTabMatch = activeTab === 'DEFAULT' ? isDef : !isDef;
    if (!isTabMatch) return false;

    const name     = (product.itemName     || '').toLowerCase();
    const code     = (product.itemCode     || '').toLowerCase();
    const q        = searchQuery.toLowerCase();
    const matchesSearch   = !q || name.includes(q) || code.includes(q);
    const matchesCategory = filterCategory === 'All' || product.category === filterCategory;
    return matchesSearch && matchesCategory;
  });

  // Build unique category list dynamically from loaded products
  const uniqueCategories = ['All', ...new Set(products
    .filter(p => {
      const isDef = p.default === true || p.isDefault === true;
      return activeTab === 'DEFAULT' ? isDef : !isDef;
    })
    .map(p => p.category)
    .filter(Boolean)
  )];

  return (
    <div className="inventory-page">
      <div className="inventory-header">
        <h1>Inventory Management</h1>
        <div className="header-actions">
          <div className="shortcut-guide" style={{ fontSize: '0.75rem', color: '#666', display: 'flex', gap: '15px', marginRight: '20px', borderRight: '1px solid #ddd', paddingRight: '20px' }}>
            <span title="Alt + N"><Keyboard size={14} style={{ marginRight: '4px' }} /> Add (Alt+N)</span>
            <span title="Alt + B"><Keyboard size={14} style={{ marginRight: '4px' }} /> Bulk (Alt+B)</span>
            <span title="Alt + S"><Keyboard size={14} style={{ marginRight: '4px' }} /> Search (Alt+S)</span>
            <span title="Alt + T"><Keyboard size={14} style={{ marginRight: '4px' }} /> Toggle (Alt+T)</span>
          </div>
          <button className="bulk-upload-btn" onClick={() => fetchProducts()} title="Refresh Data">
            <Loader2 size={18} className={isLoading ? 'animate-spin' : ''} />
            Refresh
          </button>
          <button className="bulk-upload-btn" onClick={handleBulkUpload}>
            <Upload size={18} />
            Bulk Upload
          </button>
          <button className="add-product-btn" onClick={handleAddProduct}>
            <Plus size={18} />
            Add Product
          </button>
        </div>
      </div>

      <div className="inventory-tabs">
        <button 
          className={`tab-btn ${activeTab === 'DEFAULT' ? 'active' : ''}`}
          onClick={() => setActiveTab('DEFAULT')}
        >
          Default Products
        </button>
        <button 
          className={`tab-btn ${activeTab === 'REGULAR' ? 'active' : ''}`}
          onClick={() => setActiveTab('REGULAR')}
        >
          Regular Products
        </button>
      </div>

      <div className="inventory-controls">
        <div className="search-bar">
          <Search className="search-icon" size={20} />
          <input
            type="text"
            ref={searchInputRef}
            placeholder="Search products..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
        <select 
          className="category-filter"
          value={filterCategory}
          onChange={(e) => setFilterCategory(e.target.value)}
        >
          {uniqueCategories.map(cat => (
            <option key={cat} value={cat}>{cat}</option>
          ))}
        </select>
      </div>

      <div className="inventory-table-container">
        <div className="inventory-table-wrapper">
          <table className="inventory-table">
            <thead>
              <tr>
                <th style={{ width: '50px' }}>No</th>
                <th style={{ width: '200px' }}>ITEM NAME</th>
                <th style={{ width: '120px' }}>ITEM CODE</th>
                <th style={{ width: '120px' }}>CATEGORY</th>
                <th style={{ width: '120px' }}>SUBCATEGORY</th>
                <th style={{ width: '100px' }}>MRP</th>
                <th style={{ width: '100px' }}>SALE RATE</th>
                <th style={{ width: '150px' }}>ACTIONS</th>
              </tr>
            </thead>
            <tbody>
              {isLoading ? (
                <tr>
                  <td colSpan="8" className="empty-state">
                    <div className="empty-message">
                      <Loader2 size={48} className="animate-spin" />
                      <p>Loading products...</p>
                    </div>
                  </td>
                </tr>
              ) : filteredProducts.length > 0 ? (
                filteredProducts.map((product, index) => (
                  <tr key={product.id}>
                    <td className="text-center">{index + 1}</td>
                    <td className="product-name">{product.itemName || '-'}</td>
                    <td>{product.itemCode || '-'}</td>
                    <td>{product.category || '-'}</td>
                    <td>{product.subcategory}</td>
                    <td>₹{product.mrp.toFixed(2)}</td>
                    <td>₹{product.saleRate.toFixed(2)}</td>
                    <td>
                      <div className="action-buttons">
                        <button className="action-btn view-btn" onClick={() => handleView(product.id)} title="View">
                          <Eye size={16} />
                        </button>
                        <button className="action-btn edit-btn" onClick={() => handleEdit(product.id)} title="Edit">
                          <Edit size={16} />
                        </button>
                        <button className="action-btn delete-btn" onClick={() => handleDelete(product.id)} title="Delete">
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="8" className="empty-state">
                    <div className="empty-message">
                      <Search size={48} />
                      <p>No products found in {activeTab.toLowerCase()} tab</p>
                      <span style={{ maxWidth: '400px', textAlign: 'center' }}>
                        {products.length === 0 
                          ? 'The database is completely empty. Please ensure the backend seeded the default products.' 
                          : `Total products found: ${products.length}. However, none matched the current tab and search filters.`}
                      </span>
                      <div style={{ marginTop: '20px', display: 'flex', gap: '10px' }}>
                        <button className="refresh-btn" onClick={() => fetchProducts()} style={{ padding: '8px 16px', borderRadius: '8px', border: '1px solid #cbd5e1', background: '#f8fafc', cursor: 'pointer' }}>
                          Retry Fetch
                        </button>
                        <button onClick={() => console.table(products)} style={{ padding: '8px 16px', borderRadius: '8px', border: '1px solid #cbd5e1', background: '#f8fafc', cursor: 'pointer' }}>
                          Log All Data to Console
                        </button>
                      </div>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add Product Modal */}
      <AddProductModal
        isOpen={isAddModalOpen}
        onClose={() => setIsAddModalOpen(false)}
        onSubmit={handleProductSubmit}
      />

      {/* View Product Modal */}
      <ViewProductModal
        isOpen={isViewModalOpen}
        onClose={() => setIsViewModalOpen(false)}
        product={selectedProduct}
      />

      {/* Edit Product Modal */}
      <EditProductModal
        isOpen={isEditModalOpen}
        onClose={() => setIsEditModalOpen(false)}
        onSubmit={handleProductUpdate}
        product={selectedProduct}
      />

      <BulkAddModal
        isOpen={isBulkModalOpen}
        onClose={() => setIsBulkModalOpen(false)}
        onSubmit={handleBulkSubmit}
        existingProducts={products}
      />

    </div>
  );
};

export default Inventory;
