import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import {
  ShoppingCart,
  CreditCard,
  Server,
  BarChart2,
  Truck,
  Users,
  FileText,
  Mail,
  Phone,
  MapPin,
  CheckCircle2,
  X,
  Cpu,
  Zap,
  Award,
  Search,
  Store,
  Package,
  Shield,
  TrendingUp,
  Star,
  ChevronRight,
  Play,
  LogIn,
} from "lucide-react";
import { useNavigate } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";
import "./HomePage.css";
import LocalUsersDemo from "../components/common/LocalUsersDemo";

const HERO_IMAGE = "/offline-hero.svg";
const COUNTER_IMAGE = "/offline-counter.svg";
const STORE_INTERIOR = "/offline-store.svg";
const DASHBOARD_IMAGE = "/offline-dashboard.svg";

/* ─── Navbar ─── */
function Navbar() {
  const [open, setOpen] = useState(false);
  const navigate = useNavigate();

  return (
    <nav className="navbar navbar-expand-md navbar-light bg-white shadow-sm sticky-top hp-navbar">
      <div className="container">
        {/* Brand */}
        <a className="navbar-brand d-flex align-items-center gap-2" href="#main">
          <div className="hp-logo-icon d-flex align-items-center justify-content-center rounded-3">
            <Store color="white" size={22} />
          </div>
          <div>
            <div className="hp-brand-text fw-bold">TSAR IT SMMS</div>
            <div className="hp-brand-sub text-muted" style={{ fontSize: "0.65rem", marginTop: "-2px" }}>
              Super Market Management System
            </div>
          </div>
        </a>

        {/* Mobile toggler */}
        <button
          className="navbar-toggler border-0"
          onClick={() => setOpen((s) => !s)}
        >
          {open ? <X size={20} /> : <span className="navbar-toggler-icon" />}
        </button>

        {/* Links */}
        <div className={`collapse navbar-collapse ${open ? "show" : ""}`}>
          <ul className="navbar-nav ms-auto align-items-md-center gap-md-3">
            {["main", "about", "features", "pricing", "testimonials", "contact"].map((id) => (
              <li className="nav-item" key={id}>
                <a className="nav-link hp-nav-link text-capitalize" href={`#${id}`}>
                  {id}
                </a>
              </li>
            ))}
            <li className="nav-item mt-2 mt-md-0">
              <button
                onClick={() => navigate("/login")}
                className="btn hp-btn-primary d-flex align-items-center gap-2 px-4"
              >
                <LogIn size={16} />
                Login
              </button>
            </li>
          </ul>
        </div>
      </div>
    </nav>
  );
}

/* ─── Badge ─── */
function Badge({ children }) {
  return (
    <span className="hp-badge d-inline-flex align-items-center gap-2 px-3 py-2 rounded-pill">
      <Zap size={14} className="hp-badge-icon" />
      {children}
    </span>
  );
}

/* ─── Feature Card ─── */
const COLOR_MAP = {
  indigo: { bg: "#d1fae5", text: "#059669" },  /* emerald */
  purple: { bg: "#cffafe", text: "#0891b2" },  /* cyan    */
  blue:   { bg: "#e0f2fe", text: "#0284c7" },  /* sky     */
  teal:   { bg: "#f0fdf4", text: "#10b981" },  /* teal    */
};

function FeatureCard({ icon: Icon, title, desc, color = "indigo" }) {
  const c = COLOR_MAP[color] || COLOR_MAP.indigo;
  return (
    <div className="card h-100 border-0 shadow-sm hp-feature-card">
      <div className="card-body p-4">
        <div
          className="hp-feature-icon d-inline-flex align-items-center justify-content-center rounded-3 mb-3"
          style={{ background: c.bg, color: c.text }}
        >
          <Icon size={22} />
        </div>
        <h5 className="card-title fw-bold">{title}</h5>
        <p className="card-text text-muted">{desc}</p>
      </div>
    </div>
  );
}

/* ─── HomePage ─── */
export default function HomePage() {
  const navigate = useNavigate();
  const [showDemo, setShowDemo] = useState(false);
  const [showPricingCustomContact, setShowPricingCustomContact] = useState(false);
  const [contactForm, setContactForm] = useState({
    name: "", email: "", phone: "", message: "", storeName: "",
  });
  const [landing, setLanding] = useState(null);
  const [demoStats, setDemoStats] = useState({ todaySales: 0, pendingOrders: 0, activeStores: 0 });
  const demoSourceRef = useRef(null);

  /* Demo SSE */
  useEffect(() => {
    if (!showDemo) {
      demoSourceRef.current?.close();
      demoSourceRef.current = null;
      return;
    }
    const src = new EventSource("/api/demo/stream");
    demoSourceRef.current = src;
    src.addEventListener("demo-stats", (e) => {
      try { setDemoStats(JSON.parse(e.data)); } catch (_) {}
    });
    src.onerror = () => src.close();
    return () => { demoSourceRef.current?.close(); demoSourceRef.current = null; };
  }, [showDemo]);

  /* Landing content */
  useEffect(() => {
    let cancelled = false;
    axios.get("/api/landing")
      .then((r) => { if (!cancelled && r?.data) setLanding(r.data); })
      .catch(() => {});
    return () => { cancelled = true; };
  }, []);

  const submitContact = async (e) => {
    e.preventDefault();
    try {
      await axios.post("/api/leads", {
        name: contactForm.name,
        email: contactForm.email,
        phone: contactForm.phone,
        message: contactForm.message,
        storeName: contactForm.storeName || null,
      });
      toast.success(`Thanks ${contactForm.name}! We'll contact you shortly.`);
      setContactForm({ name: "", email: "", phone: "", message: "", storeName: "" });
    } catch {
      toast.error("Failed to submit. Please try again later.");
    }
  };

  return (
    <div className="hp-root">
      <Navbar />
      <Toaster position="top-right" />

      {/* ══════════════════════════════════════════
          HERO
      ══════════════════════════════════════════ */}
      <section id="main" className="hp-hero py-5">
        <div className="container py-4">
          <div className="row align-items-center g-5">
            {/* Left text */}
            <div className="col-lg-6">
              <Badge>{landing?.heroSubtitle || "Complete Retail Management Solution"}</Badge>
              <h1 className="hp-hero-title mt-3 mb-3">
                {landing?.heroTitle ? (
                  <span dangerouslySetInnerHTML={{ __html: landing.heroTitle }} />
                ) : (
                  <>
                    Transform Your Retail Business with{" "}
                    <span className="hp-gradient-text">TSAR IT SMMS</span>
                  </>
                )}
              </h1>
              <p className="text-muted fs-5 mb-4">
                {landing?.heroDescription ||
                  "Advanced billing, inventory management, and analytics platform designed for modern retailers."}
              </p>
              <div className="d-flex flex-wrap gap-3">
                <button
                  className="btn hp-btn-primary d-flex align-items-center gap-2 px-4 py-3"
                  onClick={() => {
                    if (landing?.ctaPrimaryUrl && landing.ctaPrimaryUrl !== "/contact") {
                      window.location.href = landing.ctaPrimaryUrl;
                    } else {
                      setShowDemo(true);
                    }
                  }}
                >
                  <Play size={18} fill="white" />
                  {landing?.ctaPrimaryText || "Watch Demo"}
                </button>
                <a
                  href={landing?.ctaSecondaryUrl || "#pricing"}
                  className="btn hp-btn-outline d-flex align-items-center gap-2 px-4 py-3"
                >
                  <CreditCard size={18} />
                  {landing?.ctaSecondaryText || "View Pricing"}
                </a>
              </div>

              {/* Trust badges */}
              <div className="row g-3 mt-3">
                <div className="col-6">
                  <div className="d-flex align-items-center gap-3 hp-trust-item p-3 rounded-3 bg-white shadow-sm">
                    <div className="hp-trust-icon text-indigo">
                      <CheckCircle2 size={22} />
                    </div>
                    <div>
                      <div className="fw-bold small">99.9% Uptime</div>
                      <div className="text-muted" style={{ fontSize: "0.75rem" }}>Reliable cloud infrastructure</div>
                    </div>
                  </div>
                </div>
                <div className="col-6">
                  <div className="d-flex align-items-center gap-3 hp-trust-item p-3 rounded-3 bg-white shadow-sm">
                    <div className="hp-trust-icon text-purple">
                      <Award size={22} />
                    </div>
                    <div>
                      <div className="fw-bold small">GST Ready</div>
                      <div className="text-muted" style={{ fontSize: "0.75rem" }}>Compliant billing system</div>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Right image */}
            <div className="col-lg-6">
              <div className="hp-hero-img-wrap position-relative rounded-4 overflow-hidden shadow hp-img-border">
                <img
                  src={landing?.heroImageUrl || HERO_IMAGE}
                  alt="Supermarket billing"
                  className="img-fluid w-100 hp-hero-img"
                />
                {/* Floating stats card */}
                <div className="hp-floating-card position-absolute bottom-0 start-0 end-0 m-3 bg-white rounded-3 p-3 shadow">
                  <div className="row g-2">
                    <div className="col-6">
                      <div className="hp-stat-card hp-stat-indigo rounded-3 p-3">
                        <div className="d-flex align-items-center justify-content-between">
                          <div>
                            <div className="hp-stat-label">Today Sales</div>
                            <div className="hp-stat-value">₹1,25,400</div>
                          </div>
                          <BarChart2 size={24} className="hp-stat-icon-indigo" />
                        </div>
                      </div>
                    </div>
                    <div className="col-6">
                      <div className="hp-stat-card hp-stat-green rounded-3 p-3">
                        <div className="d-flex align-items-center justify-content-between">
                          <div>
                            <div className="hp-stat-label">Pending Orders</div>
                            <div className="hp-stat-value">12</div>
                          </div>
                          <Truck size={24} className="hp-stat-icon-green" />
                        </div>
                      </div>
                    </div>
                    <div className="col-12">
                      <div className="hp-stat-card hp-stat-blue rounded-3 p-3">
                        <div className="d-flex align-items-center justify-content-between">
                          <div>
                            <div className="hp-stat-label">Active Stores</div>
                            <div className="hp-stat-value">4 Locations</div>
                          </div>
                          <Users size={24} className="hp-stat-icon-blue" />
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* ══════════════════════════════════════════
          ABOUT
      ══════════════════════════════════════════ */}
      <section id="about" className="py-5 bg-white">
        <div className="container py-3">
          <div className="row align-items-center g-5">
            <div className="col-lg-6">
              <Badge>About TSAR IT SMMS</Badge>
              <h2 className="hp-section-title mt-3 mb-3">Revolutionizing Retail Management</h2>
              <p className="text-muted fs-5 mb-4">
                TSAR IT SMMS is built for modern supermarkets and retail chains. Our platform
                combines intuitive point-of-sale, intelligent inventory tracking, supplier
                management, customer loyalty programs, and powerful analytics.
              </p>
              <div className="d-flex flex-column gap-4 mb-4">
                <div className="d-flex gap-3">
                  <div className="hp-about-icon hp-about-indigo flex-shrink-0">
                    <Cpu size={20} />
                  </div>
                  <div>
                    <div className="fw-bold">Lightning Fast Performance</div>
                    <div className="text-muted small">Optimized to run smoothly on any device, from tablets to desktop.</div>
                  </div>
                </div>
                <div className="d-flex gap-3">
                  <div className="hp-about-icon hp-about-purple flex-shrink-0">
                    <Server size={20} />
                  </div>
                  <div>
                    <div className="fw-bold">Cloud Powered</div>
                    <div className="text-muted small">Real-time sync across all your stores with automatic cloud backups.</div>
                  </div>
                </div>
              </div>
              <div className="d-flex gap-3">
                <a href="#features" className="btn hp-btn-primary px-4">Explore Features</a>
                <a href="#contact" className="btn hp-btn-secondary px-4">Contact Sales</a>
              </div>
            </div>
            <div className="col-lg-6">
              <div className="rounded-4 overflow-hidden shadow-lg">
                <img src={STORE_INTERIOR} alt="Store interior" className="img-fluid w-100 hp-store-img" />
              </div>
            </div>
          </div>

        </div>
      </section>

      {/* ══════════════════════════════════════════
          FEATURES
      ══════════════════════════════════════════ */}
      <section id="features" className="py-5 hp-section-light">
        <div className="container py-3">
          <div className="text-center mb-5">
            <Badge>Powerful Features</Badge>
            <h2 className="hp-section-title mt-3 mb-2">Everything You Need to Succeed</h2>
            <p className="text-muted mx-auto" style={{ maxWidth: 560 }}>
              Comprehensive tools designed to streamline your retail operations and drive growth.
            </p>
          </div>
          <div className="row g-4">
            {landing?.featuresJson ? (
              (() => {
                try {
                  return JSON.parse(landing.featuresJson).map((f, i) => (
                    <div key={i} className="col-md-6 col-lg-4">
                      <FeatureCard icon={Package} title={f.title} desc={f.desc} color={f.color} />
                    </div>
                  ));
                } catch { return null; }
              })()
            ) : (
              [
                { icon: CreditCard, title: "Smart Billing", desc: "Fast barcode scanning, quick product search, and multi-payment handling with split payment support.", color: "indigo" },
                { icon: BarChart2,  title: "Advanced Analytics", desc: "Real-time dashboards for sales trends, margin reports, and easy export to multiple formats.", color: "purple" },
                { icon: Package,    title: "Inventory Management", desc: "Track stock levels, manage suppliers, auto-generate reorder suggestions and expiry alerts.", color: "blue" },
                { icon: Truck,      title: "Multi-Store Sync", desc: "Centralized inventory and sales management across all your locations in real-time.", color: "teal" },
                { icon: Users,      title: "Role Management", desc: "Create cashier/admin roles with granular permissions and complete audit trails.", color: "indigo" },
                { icon: FileText,   title: "GST Compliance", desc: "Automated invoice formats, tax computation, and e-invoice support for full compliance.", color: "purple" },
              ].map((f, i) => (
                <div key={i} className="col-md-6 col-lg-4">
                  <FeatureCard {...f} />
                </div>
              ))
            )}
          </div>
        </div>
      </section>

      {/* ══════════════════════════════════════════
          WHY CHOOSE
      ══════════════════════════════════════════ */}
      {/* ══════════════════════════════════════════
          PRICING
      ══════════════════════════════════════════ */}
      <section id="pricing" className="py-5 hp-section-light">
        <div className="container py-3 text-center">
          <Badge>Simple Pricing</Badge>
          <h2 className="hp-section-title mt-3 mb-2">Plans for Every Business Size</h2>
          <p className="text-muted mx-auto mb-3" style={{ maxWidth: 520 }}>
            No hidden fees. Start small and scale as you grow.
          </p>
          <button onClick={() => navigate("/plans")} className="btn hp-btn-primary d-inline-flex align-items-center gap-2 mb-5">
            View all plans <ChevronRight size={16} />
          </button>

          <div className="row g-4 justify-content-center">
            {/* Free */}
            <div className="col-sm-6 col-lg">
              <div className="card h-100 border-2 hp-price-card shadow-sm">
                <div className="card-body p-4">
                  <div className="fw-bold fs-5 mb-2">Free</div>
                  <div className="hp-price-amount">Rs 0 <span className="hp-price-period">/5 days</span></div>
                  <ul className="list-unstyled mt-3 text-start hp-price-list">
                    <li><CheckCircle2 size={14} className="text-success me-2" />5 Days Trial</li>
                    <li><CheckCircle2 size={14} className="text-success me-2" />Basic Features</li>
                    <li><CheckCircle2 size={14} className="text-success me-2" />Limited Support</li>
                  </ul>
                  <button
                    className="btn btn-light w-100 mt-4 fw-semibold"
                    onClick={() => navigate("/register?plan=Free&price=Rs%200&period=5+days")}
                  >
                    Start Free Trial
                  </button>
                </div>
              </div>
            </div>

            {/* 12 Months */}
            <div className="col-sm-6 col-lg">
              <div className="card h-100 border-2 hp-price-card hp-price-popular shadow-sm position-relative">
                <div className="hp-popular-badge">Most Popular</div>
                <div className="card-body p-4">
                  <div className="fw-bold fs-5 mb-2">12 Months</div>
                  <div className="hp-price-amount">Rs 5,000 <span className="hp-price-period">/12 months</span></div>
                  <ul className="list-unstyled mt-3 text-start hp-price-list">
                    <li><CheckCircle2 size={14} className="text-success me-2" />365 Days</li>
                    <li><CheckCircle2 size={14} className="text-success me-2" />Unlimited Features</li>
                    <li><CheckCircle2 size={14} className="text-success me-2" />Priority Support</li>
                  </ul>
                  <button
                    className="btn hp-btn-primary w-100 mt-4 fw-semibold"
                    onClick={() => navigate("/register?plan=12%20Months&price=Rs%205%2C000&period=12+months")}
                  >
                    Choose 12 Months
                  </button>
                </div>
              </div>
            </div>

            {/* Custom */}
            <div className="col-sm-6 col-lg">
              <div className="card h-100 hp-price-card hp-price-custom shadow-sm">
                <div className="card-body p-4">
                  <div className="fw-bold fs-5 mb-2">Custom</div>
                  <div className="hp-price-amount" style={{ fontSize: "1.4rem" }}>Contact Us</div>
                  <ul className="list-unstyled mt-3 text-start hp-price-list">
                    <li><CheckCircle2 size={14} className="text-success me-2" />Custom Duration</li>
                    <li><CheckCircle2 size={14} className="text-success me-2" />Custom Features</li>
                    <li><CheckCircle2 size={14} className="text-success me-2" />Dedicated Support</li>
                  </ul>
                  <button
                    className="btn hp-btn-purple w-100 mt-4 fw-semibold"
                    onClick={() => setShowPricingCustomContact((current) => !current)}
                  >
                    Contact Sales
                  </button>
                </div>
              </div>
            </div>
          </div>

          {showPricingCustomContact && (
            <div className="row justify-content-center mt-4">
              <div className="col-lg-8">
                <div className="card border-0 shadow-sm">
                  <div className="card-body p-4 text-start">
                    <h5 className="fw-bold mb-3">Contact Here For Custom Plan</h5>
                    <div className="row g-3">
                      <div className="col-md-4">
                        <div className="d-flex align-items-start gap-3">
                          <div className="hp-contact-icon hp-contact-indigo d-flex align-items-center justify-content-center">
                            <Mail size={20} />
                          </div>
                          <div>
                            <div className="fw-semibold">Email</div>
                            <div className="text-muted">info@tsaritservices.com</div>
                          </div>
                        </div>
                      </div>
                      <div className="col-md-4">
                        <div className="d-flex align-items-start gap-3">
                          <div className="hp-contact-icon hp-contact-purple d-flex align-items-center justify-content-center">
                            <Phone size={20} />
                          </div>
                          <div>
                            <div className="fw-semibold">Support Phone</div>
                            <div className="text-muted">+91 9491301258</div>
                          </div>
                        </div>
                      </div>
                      <div className="col-md-4">
                        <div className="d-flex align-items-start gap-3">
                          <div className="hp-contact-icon hp-contact-blue d-flex align-items-center justify-content-center">
                            <Phone size={20} />
                          </div>
                          <div>
                            <div className="fw-semibold">Support Phone (Alt)</div>
                            <div className="text-muted">+91 8142616767</div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </section>

      {/* ══════════════════════════════════════════
          DASHBOARD PREVIEW
      ══════════════════════════════════════════ */}
      <section className="py-5 bg-white">
        <div className="container py-3">
          <div className="row align-items-center g-5">
            <div className="col-lg-6">
              <Badge>Beautiful Interface</Badge>
              <h2 className="hp-section-title mt-3 mb-3">Designed for Efficiency</h2>
              <p className="text-muted mb-4">
                Clean, intuitive interfaces for cashiers and managers with responsive design and keyboard shortcuts.
              </p>
              <div className="d-flex flex-column gap-3">
                <div className="d-flex align-items-start gap-3">
                  <div className="hp-trust-icon text-indigo flex-shrink-0"><FileText size={20} /></div>
                  <div>
                    <div className="fw-bold">Custom Invoice Designer</div>
                    <div className="text-muted small">Create professional GST-compliant invoices with your branding.</div>
                  </div>
                </div>
                <div className="d-flex align-items-start gap-3">
                  <div className="hp-trust-icon text-indigo flex-shrink-0"><Search size={20} /></div>
                  <div>
                    <div className="fw-bold">Smart Search</div>
                    <div className="text-muted small">Instant lookup by barcode, name, SKU, or category.</div>
                  </div>
                </div>
              </div>
            </div>
            <div className="col-lg-6">
              <div className="rounded-4 overflow-hidden shadow-lg hp-img-border">
                <img src={DASHBOARD_IMAGE} alt="Dashboard" className="img-fluid w-100 hp-dash-img" />
              </div>
            </div>
          </div>
        </div>
      </section>

      <LocalUsersDemo />

      {/* ══════════════════════════════════════════
          TESTIMONIALS
      ══════════════════════════════════════════ */}
      <section id="testimonials" className="py-5 hp-section-light">
        <div className="container py-3 text-center">
          <Badge>Success Stories</Badge>
          <h2 className="hp-section-title mt-3 mb-5">Trusted by Retailers Nationwide</h2>
          <div className="row g-4">
            {[
              { text: '"TSAR IT SMMS reduced our billing time by 40%. The support team was incredibly helpful during our transition."', name: "Ramesh Kumar, Grocery Owner" },
              { text: '"Inventory tracking and expiry alerts have saved us thousands in food wastage. Game changer!"', name: "Priya Sharma, Chain Manager" },
              { text: '"Integration with our payment partners was seamless. Customers love the QR checkout experience."', name: "Ahmed Khan, Superstore Owner" },
            ].map(({ text, name }) => (
              <div key={name} className="col-md-4">
                <div className="card h-100 border-0 shadow-sm p-4 hp-testimonial-card">
                  <p className="text-muted fst-italic mb-3">{text}</p>
                  <div className="fw-bold small mb-2">— {name}</div>
                  <div className="d-flex justify-content-center gap-1">
                    {[...Array(5)].map((_, i) => <Star key={i} size={14} className="hp-star" fill="#facc15" color="#facc15" />)}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* ══════════════════════════════════════════
          CONTACT
      ══════════════════════════════════════════ */}
      <section id="contact" className="py-5 bg-white">
        <div className="container py-3">
          <div className="row g-5">
            {/* Info */}
            <div className="col-lg-5">
              <Badge>Get In Touch</Badge>
              <h2 className="hp-section-title mt-3 mb-3">Let's Transform Your Business</h2>
              <p className="text-muted mb-4">Request a demo, ask about pricing, or get support from our expert team.</p>
              <div className="d-flex flex-column gap-4">
                {[
                  { icon: Mail,  label: "Email",               value: "info@tsaritservices.com", color: "indigo" },
                  { icon: Phone, label: "Support Phone",        value: "+91 9491301258",           color: "purple" },
                  { icon: Phone, label: "Support Phone (Alt)",  value: "+91 8142616767",           color: "purple" },
                  { icon: MapPin,label: "Office",               value: "Chennai, India",            color: "blue"   },
                ].map(({ icon: Icon, label, value, color }) => (
                  <div key={label} className="d-flex align-items-center gap-3">
                    <div className={`hp-contact-icon hp-contact-${color} d-flex align-items-center justify-content-center rounded-3`}>
                      <Icon size={20} />
                    </div>
                    <div>
                      <div className="fw-bold small">{label}</div>
                      <div className="text-muted small">{value}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Form */}
            <div className="col-lg-7">
              <form onSubmit={submitContact} className="hp-contact-form rounded-4 p-4 p-md-5">
                <div className="row g-4">
                  <div className="col-md-6">
                    <label className="form-label fw-semibold small">Full Name</label>
                    <input
                      className="form-control hp-input"
                      placeholder="Your full name"
                      value={contactForm.name}
                      onChange={(e) => setContactForm({ ...contactForm, name: e.target.value })}
                      required
                    />
                  </div>
                  <div className="col-md-6">
                    <label className="form-label fw-semibold small">Email Address</label>
                    <input
                      type="email"
                      className="form-control hp-input"
                      placeholder="your@email.com"
                      value={contactForm.email}
                      onChange={(e) => setContactForm({ ...contactForm, email: e.target.value })}
                      required
                    />
                  </div>
                  <div className="col-12">
                    <label className="form-label fw-semibold small">Phone Number</label>
                    <input
                      className="form-control hp-input"
                      placeholder="+91 9491301258"
                      value={contactForm.phone}
                      onChange={(e) => setContactForm({ ...contactForm, phone: e.target.value })}
                    />
                  </div>
                  <div className="col-12">
                    <label className="form-label fw-semibold small">Message</label>
                    <textarea
                      className="form-control hp-input"
                      rows={4}
                      placeholder="How can we help your business?"
                      value={contactForm.message}
                      onChange={(e) => setContactForm({ ...contactForm, message: e.target.value })}
                    />
                  </div>
                  <div className="col-12 d-flex gap-3">
                    <button type="submit" className="btn hp-btn-primary flex-fill fw-semibold">
                      Send Message
                    </button>
                    <button
                      type="button"
                      className="btn hp-btn-outline fw-semibold"
                      onClick={() => alert("We'll call you at +91 9491301258")}
                    >
                      Request Callback
                    </button>
                  </div>
                </div>
              </form>
            </div>
          </div>
        </div>
      </section>

      {/* ══════════════════════════════════════════
          CTA BANNER
      ══════════════════════════════════════════ */}
      <section className="hp-cta py-5">
        <div className="container">
          <div className="row align-items-center g-4">
            <div className="col-md-7">
              <div className="text-white-50 small mb-1">Ready to Get Started?</div>
              <h3 className="text-white fw-bold mb-0">Transform Your Retail Business Today</h3>
            </div>
            <div className="col-md-5 d-flex gap-3 flex-wrap justify-content-md-end">
              <a href="#pricing" className="btn btn-light text-indigo fw-semibold px-4">Start Free Trial</a>
              <a href="#contact" className="btn btn-outline-light fw-semibold px-4">Contact Sales</a>
            </div>
          </div>
        </div>
      </section>

      {/* ══════════════════════════════════════════
          FOOTER
      ══════════════════════════════════════════ */}
      <footer className="hp-footer py-5">
        <div className="container">
          <div className="row g-4">
            {/* Brand */}
            <div className="col-lg-3 col-md-6">
              <div className="d-flex align-items-center gap-2 mb-3">
                <div className="hp-footer-logo d-flex align-items-center justify-content-center rounded-3">
                  <Store color="white" size={20} />
                </div>
                <div>
                  <div className="fw-bold text-white">TSAR-IT</div>
                  <div className="text-secondary" style={{ fontSize: "0.65rem" }}>Smart Retail Solutions</div>
                </div>
              </div>
              <p className="text-secondary small">
                Advanced retail management platform helping businesses streamline operations and drive growth.
              </p>
            </div>

            {/* Product */}
            <div className="col-lg-2 col-md-3 col-6">
              <div className="fw-semibold text-white mb-3">Product</div>
              <ul className="list-unstyled hp-footer-links">
                <li><a href="#features">Features</a></li>
                <li><a href="#pricing">Pricing</a></li>
                <li><a href="#testimonials">Testimonials</a></li>
              </ul>
            </div>

            {/* Company */}
            <div className="col-lg-2 col-md-3 col-6">
              <div className="fw-semibold text-white mb-3">Company</div>
              <ul className="list-unstyled hp-footer-links">
                <li><a href="#about">About</a></li>
                <li><a href="#contact">Contact</a></li>
                <li><a href="/careers">Careers</a></li>
              </ul>
            </div>

            {/* Policies */}
            <div className="col-lg-2 col-md-6">
              <div className="fw-semibold text-white mb-3">Policies</div>
              <ul className="list-unstyled hp-footer-links">
                <li><a href="/privacy-policy">Privacy Policy</a></li>
                <li><a href="/terms-of-service">Terms of Service</a></li>
                <li><a href="/refund-policy">Refund Policy</a></li>
                <li><a href="/cookie-policy">Cookie Policy</a></li>
                <li><a href="/security-policy">Security Policy</a></li>
              </ul>
            </div>

            {/* Support */}
            <div className="col-lg-3 col-md-6">
              <div className="fw-semibold text-white mb-3">Contact Support</div>
              <div className="text-secondary small mb-1">info@tsaritservices.com</div>
              <div className="text-secondary small mb-3">+91 9491301258 / +91 8142616767</div>
              <button
                onClick={() => navigate("/admin/login")}
                className="btn hp-btn-primary d-flex align-items-center gap-2 mb-3"
              >
                <Shield size={14} /> Admin Login
              </button>
              <div className="d-flex gap-2">
                {["FB", "LI", "TW"].map((s) => (
                  <button key={s} className="hp-social-btn">{s}</button>
                ))}
              </div>
            </div>
          </div>

          <hr className="border-secondary mt-5 mb-4" />
          <div className="text-center text-secondary small">
            © {new Date().getFullYear()} TSAR IT SMMS — Super Market Management System. All rights reserved.
          </div>
        </div>
      </footer>

      {/* ══════════════════════════════════════════
          DEMO MODAL
      ══════════════════════════════════════════ */}
      {showDemo && (
        <div className="modal d-flex align-items-center justify-content-center hp-modal-backdrop" style={{ display: "flex !important" }}>
          <div className="hp-modal-box rounded-4 bg-white shadow-lg w-100" style={{ maxWidth: 860 }}>
            {/* Header */}
            <div className="d-flex align-items-center justify-content-between p-4 border-bottom">
              <div className="d-flex align-items-center gap-3">
                <div className="hp-about-icon hp-about-indigo">
                  <Play size={20} />
                </div>
                <div>
                  <div className="fw-bold fs-5">Request Demo</div>
                  <div className="text-muted small">See TSAR IT SMMS in action</div>
                </div>
              </div>
              <button className="btn btn-light rounded-circle p-2" onClick={() => setShowDemo(false)}>
                <X size={18} />
              </button>
            </div>

            {/* Body */}
            <div className="p-4">
              <div className="row g-4">
                <div className="col-md-6">
                  <h6 className="fw-bold mb-3">What You'll See</h6>
                  <ul className="list-unstyled d-flex flex-column gap-2 text-muted small">
                    {["POS checkout flow & keyboard shortcuts", "Inventory management & expiry alerts", "Reporting dashboard & GST invoices", "Payment QR integration"].map((t) => (
                      <li key={t} className="d-flex align-items-center gap-2">
                        <CheckCircle2 size={15} className="text-success flex-shrink-0" /> {t}
                      </li>
                    ))}
                  </ul>
                  <div className="d-flex gap-3 mt-4">
                    <button className="btn hp-btn-primary px-4">Book Demo</button>
                    <button className="btn hp-btn-secondary px-4" onClick={() => alert("Starting instant demo...")}>Instant Demo</button>
                  </div>
                </div>
                <div className="col-md-6">
                  <div className="rounded-3 border p-4 shadow-sm">
                    <div className="row text-center g-2">
                      {[
                        { label: "Today Sales",    value: `₹ ${demoStats.todaySales.toLocaleString()}` },
                        { label: "Pending Orders", value: demoStats.pendingOrders },
                        { label: "Active Stores",  value: demoStats.activeStores },
                      ].map(({ label, value }) => (
                        <div key={label} className="col-4">
                          <div className="text-muted" style={{ fontSize: "0.7rem" }}>{label}</div>
                          <div className="fw-bold">{value}</div>
                        </div>
                      ))}
                    </div>
                  </div>
                  <div className="rounded-3 overflow-hidden border mt-3 shadow-sm">
                    <img src={COUNTER_IMAGE} alt="demo" className="img-fluid w-100" style={{ height: 140, objectFit: "cover" }} />
                  </div>
                  <div className="text-center text-muted mt-2" style={{ fontSize: "0.75rem" }}>
                    Live demo preview (updates every 2s)
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
