import { useMemo, useState } from 'react';
import { X, FileSpreadsheet, Download, AlertCircle, CheckCircle, AlertTriangle } from 'lucide-react';
import { read, utils, writeFile } from 'xlsx';
import './AddProductModal.css';
import './BulkAddModal.css';

const SUPPORTED_EXCEL_EXTENSIONS = ['.xlsx', '.xls', '.csv'];

const COLUMN_ALIASES = {
  itemName: ['item name', 'product name', 'name', 'itemname', 'productname', 'item'],
  itemCode: ['item code', 'product code', 'code', 'sku', 'itemcode', 'productcode'],
  category: ['category', 'product category'],
  subcategory: ['subcategory', 'sub category', 'sub-category', 'subcat', 'sub cat'],
  mrp: ['mrp', 'm r p', 'maximum retail price'],
  saleRate: ['sale rate', 'selling rate', 'sale price', 'selling price', 'rate', 'price', 'salerate', 'sellingrate'],
  quantity: ['quantity', 'qty', 'stock', 'opening stock', 'opening qty', 'available quantity'],
  expiryDate: ['expiry date', 'expire date', 'expiry', 'exp date', 'expirydate', 'expdate']
};

const REQUIRED_COLUMNS = ['itemName', 'category', 'mrp', 'saleRate'];

const normalizeHeader = (value) => String(value ?? '')
  .replace(/^\uFEFF/, '')
  .replace(/([a-z])([A-Z])/g, '$1 $2')
  .replace(/[._-]+/g, ' ')
  .replace(/[()%:*[\]/\\]+/g, ' ')
  .replace(/[^\w\s]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();

const compactHeader = (value) => normalizeHeader(value).replace(/\s+/g, '');

const buildAliasLookup = () => {
  const aliasLookup = new Map();

  Object.entries(COLUMN_ALIASES).forEach(([canonicalName, aliases]) => {
    [canonicalName, ...aliases].forEach((alias) => {
      const normalized = normalizeHeader(alias);
      const compact = compactHeader(alias);

      if (normalized) {
        aliasLookup.set(normalized, canonicalName);
      }

      if (compact) {
        aliasLookup.set(compact, canonicalName);
      }
    });
  });

  return aliasLookup;
};

const ALIAS_LOOKUP = buildAliasLookup();

const getCanonicalColumn = (value) => {
  const normalizedValue = normalizeHeader(value);
  return ALIAS_LOOKUP.get(normalizedValue) || ALIAS_LOOKUP.get(compactHeader(value)) || null;
};

const isRowEmpty = (row = []) => row.every((value) => String(value ?? '').trim() === '');

const findHeaderRow = (rows = []) => {
  let bestMatch = null;

  rows.slice(0, 25).forEach((row, rowIndex) => {
    const columnMap = new Map();

    row.forEach((cellValue, columnIndex) => {
      const canonicalColumn = getCanonicalColumn(cellValue);
      if (canonicalColumn && !columnMap.has(canonicalColumn)) {
        columnMap.set(canonicalColumn, columnIndex);
      }
    });

    const matchCount = columnMap.size;
    const hasRequiredColumns = REQUIRED_COLUMNS.every((column) => columnMap.has(column));

    if (
      !bestMatch ||
      (hasRequiredColumns && !bestMatch.hasRequiredColumns) ||
      (hasRequiredColumns === bestMatch.hasRequiredColumns && matchCount > bestMatch.matchCount)
    ) {
      bestMatch = { rowIndex, columnMap, matchCount, hasRequiredColumns };
    }
  });

  if (!bestMatch?.hasRequiredColumns) {
    return null;
  }

  return bestMatch;
};

const getCellValue = (row, columnMap, columnName) => {
  const columnIndex = columnMap.get(columnName);
  return columnIndex === undefined ? '' : row[columnIndex];
};

const parseNumber = (value) => {
  if (value === null || value === undefined || value === '') return 0;
  const normalizedValue = String(value).replace(/,/g, '').replace(/[^\d.-]/g, '');
  const parsedValue = parseFloat(normalizedValue);
  return Number.isFinite(parsedValue) ? parsedValue : 0;
};

const parseInteger = (value) => {
  const parsedValue = parseNumber(value);
  return Number.isFinite(parsedValue) ? Math.trunc(parsedValue) : 0;
};

const BulkAddModal = ({ isOpen, onClose, onSubmit, existingProducts = [] }) => {
  const [file, setFile] = useState(null);
  const [previewData, setPreviewData] = useState([]);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [duplicateWarnings, setDuplicateWarnings] = useState([]);
  const supportedFormatLabel = useMemo(
    () => 'Item Name, Item Code, Category, Subcategory, MRP, Sale Rate, Quantity, Expiry Date',
    []
  );

  const handleClose = () => {
    setFile(null);
    setPreviewData([]);
    setError('');
    setSuccess('');
    setDuplicateWarnings([]);
    onClose();
  };

  const downloadTemplate = (e) => {
    e.preventDefault();
    const headers = [{
      'Item Name': 'Sample Item', 'Item Code': 'ITEM001', 'Category': 'Snacks',
      'Subcategory': 'Chips', 'MRP': 20, 'Sale Rate': 18, 'Quantity': 100,
      'Expiry Date': '2025-12-31'
    }];
    const ws = utils.json_to_sheet(headers);
    const wb = utils.book_new();
    utils.book_append_sheet(wb, ws, 'Template');
    writeFile(wb, 'bulk_add_template.xlsx');
  };

const toIsoDate = (date) => {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
  return date.toISOString().split('T')[0];
};

const formatDate = (inputValue) => {
  if (inputValue === null || inputValue === undefined) return null;

  const rawValue = String(inputValue).trim();
  if (!rawValue) return null;

  if (inputValue instanceof Date) {
    return toIsoDate(inputValue);
  }

  if (typeof inputValue === 'number') {
    // Excel serial date (days since 1899-12-30)
    const date = new Date(Math.round((inputValue - 25569) * 86400 * 1000));
    return toIsoDate(date);
  }

  // Already ISO format
  if (/^\d{4}-\d{2}-\d{2}$/.test(rawValue)) {
    return rawValue;
  }

  // dd/mm/yyyy or dd-mm-yyyy support (common in client Excel files)
  const dmyMatch = rawValue.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);
  if (dmyMatch) {
    const day = Number(dmyMatch[1]);
    const month = Number(dmyMatch[2]);
    const year = Number(dmyMatch[3]);
    const date = new Date(Date.UTC(year, month - 1, day));
    if (
      date.getUTCFullYear() === year &&
      date.getUTCMonth() === month - 1 &&
      date.getUTCDate() === day
    ) {
      return date.toISOString().split('T')[0];
    }
    return null;
  }

  const parsedDate = new Date(rawValue);
  return toIsoDate(parsedDate);
};

  const handleFileUpload = async (e) => {
    const selectedFile = e.target.files[0];
    if (!selectedFile) return;

    setError('');
    setSuccess('');
    setPreviewData([]);
    setDuplicateWarnings([]);
    setIsProcessing(true);

    try {
      const lowerCaseName = selectedFile.name.toLowerCase();
      const hasSupportedExtension = SUPPORTED_EXCEL_EXTENSIONS.some((extension) => lowerCaseName.endsWith(extension));

      if (!hasSupportedExtension) {
        setFile(null);
        setError('Please upload a valid spreadsheet file (.xlsx, .xls, or .csv).');
        return;
      }

      setFile(selectedFile);
      const data = await selectedFile.arrayBuffer();
      const workbook = read(data, { cellDates: true });
      const worksheet = workbook.Sheets[workbook.SheetNames[0]];
      const rows = utils.sheet_to_json(worksheet, { header: 1, defval: '', blankrows: false, raw: false });

      if (rows.length === 0) {
        setError('The uploaded file is empty.');
        return;
      }

      const headerMatch = findHeaderRow(rows);
      if (!headerMatch) {
        const detectedHeaders = rows
          .slice(0, 25)
          .find((row) => row.some((value) => String(value ?? '').trim() !== ''))
          ?.filter((value) => String(value ?? '').trim() !== '')
          .slice(0, 12)
          .join(', ');

        setError(
          `File format did not match the template. Expected headers like: ${supportedFormatLabel}.` +
          (detectedHeaders ? ` Detected: ${detectedHeaders}` : '')
        );
        return;
      }

      const dataRows = rows.slice(headerMatch.rowIndex + 1).filter((row) => !isRowEmpty(row));
      if (dataRows.length === 0) {
        setError('The uploaded file does not contain any product rows.');
        return;
      }

      // Map rows to product shape using normalized headers so small column-name changes do not break upload.
      const formattedData = dataRows.map((row) => ({
        itemName: String(getCellValue(row, headerMatch.columnMap, 'itemName') || '').trim(),
        itemCode: String(getCellValue(row, headerMatch.columnMap, 'itemCode') || '').trim(),
        category: String(getCellValue(row, headerMatch.columnMap, 'category') || '').trim(),
        subcategory: String(getCellValue(row, headerMatch.columnMap, 'subcategory') || '').trim() || '-',
        mrp: parseNumber(getCellValue(row, headerMatch.columnMap, 'mrp')),
        saleRate: parseNumber(getCellValue(row, headerMatch.columnMap, 'saleRate')),
        quantity: parseInteger(getCellValue(row, headerMatch.columnMap, 'quantity')),
        expiryDate: formatDate(getCellValue(row, headerMatch.columnMap, 'expiryDate')),
      }));

      // ── Duplicate detection ──────────────────────────────────────────
      const warnings = [];

      // 1. Rows with missing/invalid required numeric fields
      const invalidRows = [];
      formattedData.forEach((item, idx) => {
        const reasons = [];
        if (!(item.mrp > 0)) reasons.push('MRP must be greater than 0');
        if (!(item.saleRate > 0)) reasons.push('Sale Rate must be greater than 0');
        if (reasons.length > 0) {
          item.invalidRow = true;
          item.invalidReason = reasons.join(', ');
          invalidRows.push({ row: idx + 1, reason: item.invalidReason });
        }
      });

      // 2. Duplicates WITHIN the uploaded file
      const seenInFile = new Map();
      formattedData.forEach((item, idx) => {
        const code = item.itemCode.toLowerCase();
        if (!code) return;
        if (seenInFile.has(code)) {
          item.isDuplicateInFile = true;
          formattedData[seenInFile.get(code)].isDuplicateInFile = true;
        } else {
          seenInFile.set(code, idx);
        }
      });

      // 3. Duplicates against existing inventory
      const existingCodes = new Set(
        (existingProducts || []).map(p => (p.itemCode || '').toLowerCase())
      );
      formattedData.forEach(item => {
        const code = item.itemCode.toLowerCase();
        if (code && existingCodes.has(code)) item.isDuplicateInInventory = true;
      });

      // Build warning messages
      const fileConflicts = [...new Set(
        formattedData.filter(i => i.isDuplicateInFile).map(i => i.itemCode)
      )];
      const invConflicts = [...new Set(
        formattedData.filter(i => i.isDuplicateInInventory).map(i => i.itemCode)
      )];

      if (invalidRows.length > 0) {
        const previewRows = invalidRows.slice(0, 5).map(r => `Row ${r.row} (${r.reason})`).join(', ');
        const suffix = invalidRows.length > 5 ? ` and ${invalidRows.length - 5} more` : '';
        warnings.push(`Invalid pricing rows (will be skipped): ${previewRows}${suffix}`);
      }

      if (fileConflicts.length > 0)
        warnings.push(`Duplicate codes within file (will be skipped): ${fileConflicts.join(', ')}`);
      if (invConflicts.length > 0)
        warnings.push(`Already exist in inventory (will be skipped): ${invConflicts.join(', ')}`);

      setDuplicateWarnings(warnings);
      setPreviewData(formattedData);

      const validCount = formattedData.filter(i => !i.isDuplicateInFile && !i.isDuplicateInInventory && !i.invalidRow).length;
      if (warnings.length > 0) {
        setSuccess(`Parsed ${formattedData.length} rows — ${validCount} valid, ${formattedData.length - validCount} row(s) will be skipped.`);
      } else {
        setSuccess(`Successfully parsed ${formattedData.length} products. All ready to upload.`);
      }
    } catch (err) {
      console.error('Error parsing file:', err);
      setError('Failed to parse Excel file. Please ensure it follows the template.');
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (previewData.length === 0) { setError('No data to save.'); return; }
    const validData = previewData.filter(i => !i.isDuplicateInFile && !i.isDuplicateInInventory && !i.invalidRow);
    if (validData.length === 0) { setError('All rows are duplicates. Nothing to upload.'); return; }
    onSubmit(validData);
    handleClose();
  };

  const validCount = previewData.filter(i => !i.isDuplicateInFile && !i.isDuplicateInInventory && !i.invalidRow).length;
  const hasDuplicates = duplicateWarnings.length > 0;

  if (!isOpen) return null;

  return (
    <div className="modal-overlay" onClick={handleClose}>
      <div className="modal-container bulk-upload-modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Bulk Add Products (Excel)</h2>
          <button className="close-btn" onClick={handleClose}><X size={24} /></button>
        </div>

        <div className="modal-content">
          <div className="upload-section">
            <div className="template-info">
              <p>1. Download the template file.</p>
              <button type="button" className="template-btn" onClick={downloadTemplate}>
                <Download size={16} /> Download Template
              </button>
            </div>
            <div className="file-drop-area">
              <input type="file" id="excel-upload" accept=".xlsx, .xls, .csv"
                onChange={handleFileUpload} className="file-input" />
              <label htmlFor="excel-upload" className="file-label">
                <FileSpreadsheet size={48} />
                <span>{file ? file.name : 'Click to Upload Excel File'}</span>
                <span className="sub-text">Supported formats: .xlsx, .xls, .csv</span>
              </label>
            </div>
          </div>

          {error && <div className="message error"><AlertCircle size={16} /> {error}</div>}
          {success && <div className="message success"><CheckCircle size={16} /> {success}</div>}

          {/* ── Duplicate warnings banner ── */}
          {hasDuplicates && (
            <div style={{
              background: '#fffbeb', border: '1.5px solid #f59e0b', borderRadius: 10,
              padding: '12px 16px', marginTop: 10
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontWeight: 700, color: '#92400e', marginBottom: 6 }}>
                <AlertTriangle size={16} color="#f59e0b" />
                Duplicate Item Codes Detected — these rows will be skipped
              </div>
              {duplicateWarnings.map((w, i) => (
                <div key={i} style={{ fontSize: '0.83rem', color: '#78350f', marginLeft: 24, marginBottom: 2 }}>• {w}</div>
              ))}
            </div>
          )}

          {previewData.length > 0 && (
            <div className="preview-section">
              <h3>
                Preview ({previewData.length} rows
                {hasDuplicates ? ` — ${validCount} valid, ${previewData.length - validCount} skipped` : ''})
              </h3>
              <div className="preview-table-container">
                <table className="preview-table">
                  <thead>
                    <tr>
                      <th>Item Name</th><th>Code</th><th>Category</th>
                      <th>MRP</th><th>Qty</th><th>Status</th>
                    </tr>
                  </thead>
                  <tbody>
                    {previewData.slice(0, 8).map((item, idx) => {
                      const isDup = item.isDuplicateInFile || item.isDuplicateInInventory || item.invalidRow;
                      const statusLabel = item.invalidRow
                        ? `⚠ ${item.invalidReason}`
                        : item.isDuplicateInInventory
                        ? '⚠ Already in inventory'
                        : item.isDuplicateInFile
                        ? '⚠ Duplicate in file'
                        : '✓ OK';
                      return (
                        <tr key={idx} style={{ background: isDup ? '#fef3c7' : 'inherit', opacity: isDup ? 0.75 : 1 }}>
                          <td style={{ textDecoration: isDup ? 'line-through' : 'none' }}>{item.itemName}</td>
                          <td style={{ fontWeight: 700, color: isDup ? '#b45309' : '#1e40af' }}>{item.itemCode}</td>
                          <td>{item.category}</td>
                          <td>{item.mrp}</td>
                          <td>{item.quantity}</td>
                          <td style={{ fontWeight: 700, color: isDup ? '#b45309' : '#16a34a', whiteSpace: 'nowrap' }}>
                            {statusLabel}
                          </td>
                        </tr>
                      );
                    })}
                    {previewData.length > 8 && (
                      <tr><td colSpan="6" className="more-rows">...and {previewData.length - 8} more rows</td></tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>

        <div className="modal-actions">
          <button type="button" className="cancel-btn" onClick={handleClose}>Cancel</button>
          <button
            type="button"
            className="submit-btn"
            onClick={handleSubmit}
            disabled={previewData.length === 0 || isProcessing || validCount === 0}
          >
            {isProcessing ? 'Processing...' : `Upload & Save${validCount > 0 ? ` (${validCount} items)` : ''}`}
          </button>
        </div>
      </div>
    </div>
  );
};

export default BulkAddModal;
