import React, { useState, useEffect } from "react";
import {
  Mail,
  Phone,
  Lock,
  Store,
  LogIn,
  Eye,
  EyeOff,
  Loader2,
  CheckCircle2,
  ShieldCheck,
} from "lucide-react";
import { useNavigate } from "react-router-dom";
import api from "../utils/api";
import storage from "../utils/storage";
import toast, { Toaster } from "react-hot-toast";
import "bootstrap/dist/css/bootstrap.min.css";
import "./AdminLogin.css";

export default function AdminLogin() {
  const [formData, setFormData] = useState({ emailOrPhone: "", password: "" });
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [loggedIn, setLoggedIn] = useState(false);
  const [backendUp, setBackendUp] = useState(true);
  const [checkingBackend, setCheckingBackend] = useState(false);

  const navigate = useNavigate();

  /* ── Backend health check ── */
  const checkBackend = async () => {
    setCheckingBackend(true);
    try {
      await api.get("/health");
      setBackendUp(true);
    } catch {
      setBackendUp(false);
    } finally {
      setCheckingBackend(false);
    }
  };

  useEffect(() => { checkBackend(); }, []);

  const handleChange = (e) =>
    setFormData({ ...formData, [e.target.name]: e.target.value });

  /* ── Submit ── */
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!backendUp) {
      toast.error("Backend unreachable. Please start the server on http://localhost:8080 and retry.");
      return;
    }
    if (!formData.emailOrPhone || !formData.password) {
      toast.error("Please fill all fields");
      return;
    }

    setLoading(true);
    try {
      const res = await api.post("/admin/login", {
        email: formData.emailOrPhone,
        password: formData.password,
      });

      const token      = res?.data?.token;
      const userId     = res?.data?.userId || res?.data?.id;
      const email      = res?.data?.email  || formData.emailOrPhone;
      const fullName   = res?.data?.fullName || res?.data?.name || "Super Admin";
      const roleFromRes = res?.data?.role;
      const role       = roleFromRes === "ADMIN" ? "SUPER_ADMIN" : roleFromRes || "SUPER_ADMIN";

      if (token) localStorage.setItem("adminToken", token);
      storage.set("admin", { id: userId, email, fullName, role });

      setLoggedIn(true);
      setTimeout(() => navigate("/superadmindashboard"), 700);
    } catch (err) {
      console.error("Admin login failed", err);
      const isNetwork = err?.message === "Network Error" || err?.code === "ERR_NETWORK";
      if (isNetwork) {
        toast.error("Cannot reach backend. Make sure the server is running on http://localhost:8080");
      } else {
        const msg = err?.response?.data?.message || err?.message || "Login failed. Please try again.";
        toast.error(msg);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="al-root">
      <Toaster position="top-right" />

      <div className="al-card p-4 p-md-5">

        {/* ── Brand header ── */}
        <div className="text-center mb-4">
          <div className="al-brand d-flex align-items-center justify-content-center gap-2">
            <ShieldCheck size={28} />
            Super Admin Portal
          </div>
          <p className="text-muted small mt-2">
            Login to access the super admin dashboard
          </p>
        </div>

        {/* ── Backend warning ── */}
        {!backendUp && (
          <div className="al-warn-box mb-4 d-flex align-items-center gap-2 flex-wrap">
            <span>⚠️ Backend unreachable. <strong>Start the backend at http://localhost:8080</strong></span>
            <button
              onClick={checkBackend}
              disabled={checkingBackend}
              className="al-warn-retry ms-auto"
            >
              {checkingBackend ? "Checking…" : "Retry"}
            </button>
          </div>
        )}

        {/* ── Success view ── */}
        {loggedIn ? (
          <div className="al-success">
            <CheckCircle2 size={64} className="al-success-icon al-pulse" />
            <h5 className="fw-semibold text-dark mb-2">Welcome Super Admin 👋</h5>
            <p className="text-muted small">Redirecting to super admin dashboard…</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} noValidate>

            {/* ── Email / Phone ── */}
            <div className="mb-3">
              <label className="al-label">
                <Mail size={16} color="#2563eb" />
                Email or Phone
              </label>
              <div className="position-relative">
                <input
                  name="emailOrPhone"
                  type="text"
                  value={formData.emailOrPhone}
                  onChange={handleChange}
                  placeholder="Enter admin email or phone"
                  className="al-input"
                  autoComplete="username"
                  required
                />
                <span className="al-input-icon">
                  <Phone size={16} />
                </span>
              </div>
            </div>

            {/* ── Password ── */}
            <div className="mb-4">
              <label className="al-label">
                <Lock size={16} color="#2563eb" />
                Password
              </label>
              <div className="position-relative">
                <input
                  name="password"
                  type={showPassword ? "text" : "password"}
                  value={formData.password}
                  onChange={handleChange}
                  placeholder="Enter password"
                  className="al-input"
                  autoComplete="current-password"
                  required
                />
                <button
                  type="button"
                  className="al-input-btn"
                  onClick={() => setShowPassword(!showPassword)}
                  aria-label={showPassword ? "Hide password" : "Show password"}
                >
                  {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
            </div>

            {/* ── Submit ── */}
            <button
              type="submit"
              className="al-btn-primary"
              disabled={loading}
            >
              {loading ? (
                <>
                  <Loader2 size={17} className="al-spin" /> Logging in…
                </>
              ) : (
                <>
                  <LogIn size={17} /> Super Admin Login
                </>
              )}
            </button>

          </form>
        )}
      </div>
    </div>
  );
}
