import React from 'react';
import {
  User, Store, Phone, Clock,
  CreditCard, HeadphonesIcon, Monitor, Settings, RefreshCw, Wifi
} from 'lucide-react';
import { isNativeApp } from '../../services/api';
import './ProfileSettings.css';

const ProfileSidebar = ({ activeSection, setActiveSection, userData }) => {
  const nativeMobile = isNativeApp();

  const menuItems = [
    { id: 'overview', icon: Store, label: 'Overview', description: 'Store info & settings' },
    { id: 'contact', icon: Phone, label: 'Contact', description: 'Address & contact details' },
    { id: 'business-hours', icon: Clock, label: 'Business Hours', description: 'Operating schedule' },
    { id: 'payment', icon: CreditCard, label: 'Payment', description: 'Bank & payment methods' },
    { id: 'support', icon: HeadphonesIcon, label: 'Support', description: 'Help & support tickets' },
    { id: 'devices', icon: Monitor, label: 'Devices', description: 'Printers, scanners & more' },
    { id: 'onboarding', icon: Settings, label: 'Onboarding', description: 'Business setup & verification' },
    nativeMobile
      ? { id: 'app-controls', icon: Wifi, label: 'Server Connection', description: 'Set the PC running SMMS (Wi-Fi)' }
      : { id: 'app-controls', icon: RefreshCw, label: 'App Controls', description: 'Reload UI & restart backend' },
  ];

  return (
    <div className="profile-sidebar">
      {/* User Card */}
      <div className="user-card">
        <div className="user-avatar">
          <User size={24} />
        </div>
        <div className="user-info">
          <span className="user-name">{userData?.name || 'User'}</span>
          <span className="user-email">{userData?.email || 'user@email.com'}</span>
          <span className="user-role-badge">{userData?.role || 'User'}</span>
        </div>
      </div>

      {/* Menu Items */}
      <nav className="sidebar-nav">
        {menuItems.map((item) => (
          <button
            key={item.id}
            className={`sidebar-menu-item ${activeSection === item.id ? 'active' : ''}`}
            onClick={() => setActiveSection(item.id)}
          >
            <item.icon size={20} />
            <div className="menu-item-text">
              <span className="menu-item-label">{item.label}</span>
              <span className="menu-item-desc">{item.description}</span>
            </div>
            {activeSection === item.id && <span className="active-indicator" />}
          </button>
        ))}
      </nav>
    </div>
  );
};

export default ProfileSidebar;
