import { X, Package, Tag, DollarSign, Boxes, Calendar } from 'lucide-react';
import './ViewProductModal.css';

const ViewProductModal = ({ isOpen, onClose, product }) => {
  if (!isOpen || !product) return null;

  // Calculate stock status
  const getStockStatus = () => {
    if (product.quantity === 0) return { label: 'Out of Stock', class: 'status-danger' };
    if (product.quantity <= 10) return { label: 'Low Stock', class: 'status-warning' };
    return { label: 'In Stock', class: 'status-success' };
  };

  const stockStatus = getStockStatus();

  // Check if expiring soon (within 30 days)
  const isExpiringSoon = () => {
    if (!product.expiryDate) return false;
    const expiry = new Date(product.expiryDate);
    const today = new Date();
    const diffDays = Math.ceil((expiry - today) / (1000 * 60 * 60 * 24));
    return diffDays <= 30 && diffDays > 0;
  };

  const isExpired = () => {
    if (!product.expiryDate) return false;
    return new Date(product.expiryDate) < new Date();
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-container view-modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Product Details</h2>
          <button className="close-btn" onClick={onClose}>
            <X size={24} />
          </button>
        </div>

        <div className="modal-body">
          {/* Product Header */}
          <div className="product-header-section">
            <div className="product-icon">
              <Package size={32} />
            </div>
            <div className="product-title-info">
              <h3 className="product-name">{product.itemName}</h3>
              <span className="product-code">#{product.itemCode}</span>
            </div>
            <span className={`stock-badge ${stockStatus.class}`}>{stockStatus.label}</span>
          </div>

          {/* Category Section */}
          <div className="detail-section">
            <div className="section-header">
              <Tag size={18} />
              <h4>Category Information</h4>
            </div>
            <div className="section-grid">
              <div className="info-card">
                <span className="info-label">Category</span>
                <span className="info-value">{product.category}</span>
              </div>
              <div className="info-card">
                <span className="info-label">Subcategory</span>
                <span className="info-value">{product.subcategory || '-'}</span>
              </div>
            </div>
          </div>

          {/* Pricing Section */}
          <div className="detail-section">
            <div className="section-header">
              <DollarSign size={18} />
              <h4>Pricing Details</h4>
            </div>
            <div className="section-grid">
              <div className="info-card highlight">
                <span className="info-label">MRP</span>
                <span className="info-value price">₹{product.mrp?.toFixed(2) || '0.00'}</span>
              </div>
              <div className="info-card highlight primary">
                <span className="info-label">Sale Rate</span>
                <span className="info-value price">₹{product.saleRate?.toFixed(2) || '0.00'}</span>
              </div>
            </div>
            {product.mrp > product.saleRate && (
              <div className="discount-badge">
                {Math.round(((product.mrp - product.saleRate) / product.mrp) * 100)}% OFF
              </div>
            )}
          </div>

          {/* Inventory Section */}
          <div className="detail-section">
            <div className="section-header">
              <Boxes size={18} />
              <h4>Inventory</h4>
            </div>
            <div className="section-grid">
              <div className="info-card">
                <span className="info-label">Available Quantity</span>
                <span className={`info-value quantity ${product.quantity <= 10 ? 'low' : ''}`}>
                  {product.quantity} units
                </span>
              </div>
              <div className="info-card">
                <span className="info-label">Stock Value</span>
                <span className="info-value">₹{(product.quantity * product.saleRate).toFixed(2)}</span>
              </div>
            </div>
          </div>

          {/* Expiry Section */}
          <div className="detail-section">
            <div className="section-header">
              <Calendar size={18} />
              <h4>Expiry Details</h4>
            </div>
            <div className="section-grid">
              <div className="info-card">
                <span className="info-label">Expiry Date</span>
                <span className={`info-value ${isExpired() ? 'expired' : isExpiringSoon() ? 'expiring' : ''}`}>
                  <Calendar size={14} style={{ marginRight: '6px', verticalAlign: 'middle' }} />
                  {product.expiryDate ? new Date(product.expiryDate).toLocaleDateString('en-IN', {
                    day: '2-digit', 
                    month: 'short', 
                    year: 'numeric' 
                  }) : '-'}
                  {isExpired() && <span className="expiry-tag danger">Expired</span>}
                  {isExpiringSoon() && !isExpired() && <span className="expiry-tag warning">Expiring Soon</span>}
                </span>
              </div>
            </div>
          </div>
        </div>

        <div className="modal-footer">
          <button className="close-modal-btn" onClick={onClose}>
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

export default ViewProductModal;
