import { useEffect, useState } from 'react';
import { Printer, Bluetooth, Loader2, CheckCircle2, XCircle } from 'lucide-react';
import {
    getSavedPrinter,
    scanForPrinters,
    connectToPrinter,
    disconnectPrinter,
    isPrinterConnected,
    clearSavedPrinter,
} from '../../services/bluetoothPrinter';
import './AppControlsPanel.css';

// Mobile-only — pair a Bluetooth thermal receipt printer, matching the
// reference billing app's printer support. Lives alongside Server
// Connection in Profile > Server Connection on native builds.
const BluetoothPrinterSettings = ({ embedded = false }) => {
    const [scanning, setScanning] = useState(false);
    const [devices, setDevices] = useState([]);
    const [connected, setConnected] = useState(null);
    const [connecting, setConnecting] = useState(null); // address currently connecting
    const [message, setMessage] = useState('');

    const refreshConnectionState = async () => {
        const isConnected = await isPrinterConnected();
        setConnected(isConnected ? getSavedPrinter() : null);
    };

    useEffect(() => {
        refreshConnectionState();
    }, []);

    const handleScan = async () => {
        setScanning(true);
        setDevices([]);
        setMessage('');
        try {
            await scanForPrinters((device) => {
                setDevices((prev) => (prev.some((d) => d.address === device.address) ? prev : [...prev, device]));
            });
        } catch (error) {
            setMessage(error.message || 'Scan failed.');
        } finally {
            setScanning(false);
        }
    };

    const handleConnect = async (device) => {
        setConnecting(device.address);
        setMessage('');
        try {
            await connectToPrinter(device);
            setMessage(`Connected to ${device.name || device.address}.`);
            await refreshConnectionState();
        } catch (error) {
            setMessage(error.message || 'Could not connect.');
        } finally {
            setConnecting(null);
        }
    };

    const handleDisconnect = async () => {
        await disconnectPrinter();
        clearSavedPrinter();
        setConnected(null);
        setMessage('Printer disconnected.');
    };

    return (
        <div className={`app-controls-card ${embedded ? 'embedded' : ''}`}>
            <div className="app-controls-header">
                <div>
                    <h4><Printer size={16} style={{ verticalAlign: '-2px', marginRight: 6 }} />Bluetooth Printer</h4>
                    <p>Pair a thermal receipt printer to print bills directly from checkout.</p>
                </div>
            </div>

            <div className="app-controls-status">
                <span className={`status-dot ${connected ? 'online' : 'offline'}`}></span>
                <span>{connected ? `Connected: ${connected.name}` : 'No printer connected'}</span>
            </div>

            {message && (
                <div className="app-controls-message" style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    {connected ? <CheckCircle2 size={15} /> : <XCircle size={15} />}
                    {message}
                </div>
            )}

            {devices.length > 0 && (
                <div style={{ padding: '0 18px 10px', display: 'grid', gap: 6 }}>
                    {devices.map((device) => (
                        <button
                            key={device.address}
                            className="app-control-action"
                            onClick={() => handleConnect(device)}
                            disabled={connecting === device.address}
                            style={{ justifyContent: 'space-between' }}
                        >
                            <span>{device.name || 'Unknown device'} <small style={{ opacity: 0.6 }}>{device.address}</small></span>
                            {connecting === device.address ? <Loader2 size={16} className="spin" /> : <Bluetooth size={16} />}
                        </button>
                    ))}
                </div>
            )}

            <div className="app-controls-actions">
                <button className="app-control-action" onClick={handleScan} disabled={scanning}>
                    {scanning ? <Loader2 size={16} className="spin" /> : <Bluetooth size={16} />}
                    <span>{scanning ? 'Scanning...' : 'Scan for Printers'}</span>
                </button>

                {connected && (
                    <button className="app-control-action" onClick={handleDisconnect}>
                        <span>Disconnect</span>
                    </button>
                )}
            </div>

            <div className="app-controls-footnote">
                Turn on your thermal printer and enable Bluetooth on your phone before scanning. Most printers pair without a PIN.
            </div>
        </div>
    );
};

export default BluetoothPrinterSettings;
